    .map((name) => ({ name, items: items.filter((item) => groupOf(item.at) === name) }))
    .filter((group) => group.items.length > 0)

  const addItem = () => {
    nextId.current += 1
    setItems((current) => [{ id: `new-${nextId.current}`, title: "新的同步记录", at: NOW - 10 * 60000 }, ...current])
