// Ported from Magic UI (MIT) — https://github.com/magicuidesign/magicui/blob/main/apps/www/registry/magicui/backlight.tsx

import * as React from "react"

import { cn } from "@/lib/utils"

export interface BacklightProps {
  children?: React.ReactElement
  blur?: number
  className?: string
}

function Backlight({ children, blur = 18, className }: BacklightProps) {
  const id = React.useId()
  return (
    <div data-slot="backlight" className={cn("relative inline-grid", className)}>
      <svg width="0" height="0" aria-hidden className="absolute">
        <filter id={id} x="-50%" y="-50%" width="200%" height="200%">
          <feGaussianBlur in="SourceGraphic" stdDeviation={blur} result="blurred" />
          <feColorMatrix in="blurred" type="saturate" values="4" />
          <feComposite in="SourceGraphic" operator="over" />
        </filter>
      </svg>
      <div style={{ filter: `url(#${id})` }}>{children}</div>
    </div>
  )
}

export { Backlight }

// @vitest-environment jsdom

import { afterEach, beforeEach, expect, test, vi } from "vitest"
import { act, cleanup, fireEvent, render, screen } from "@testing-library/react"
import "@testing-library/jest-dom/vitest"
import Matter from "matter-js"

import { BallPit } from "./ball-pit"

let reduceMotion = false
let now = 0
let rafId = 0
const queue = new Map<number, FrameRequestCallback>()
let createSpy: ReturnType<typeof vi.spyOn>

beforeEach(() => {
  reduceMotion = false
  now = 0
  rafId = 0
  queue.clear()
  vi.stubGlobal("matchMedia", (query: string) => ({
    matches: query.includes("prefers-reduced-motion") ? reduceMotion : false,
    media: query,
    addEventListener() {},
    removeEventListener() {},
    addListener() {},
    removeListener() {},
    dispatchEvent() {
      return false
    },
  }))
  vi.stubGlobal("requestAnimationFrame", (cb: FrameRequestCallback) => {
    rafId += 1
    queue.set(rafId, cb)
    return rafId
  })
  vi.stubGlobal("cancelAnimationFrame", (handle: number) => {
    queue.delete(handle)
  })
  createSpy = vi.spyOn(Matter.Engine, "create")
})

afterEach(() => {
  cleanup()
  createSpy.mockRestore()
  vi.unstubAllGlobals()
})

function pump(steps: number) {
  act(() => {
    for (let i = 0; i < steps; i += 1) {
      const next = queue.entries().next().value as [number, FrameRequestCallback] | undefined
      if (!next) break
      queue.delete(next[0])
      now += 32
      next[1](now)
    }
  })
}

function pit() {
  return screen.getByRole("application", { name: "头像球池" })
}

test("默认渲染头像球，颜色跟随主题，不标记减弱动效", () => {
  render(<BallPit />)
  expect(screen.getByText("林")).toBeInTheDocument()
  expect(screen.getByText("赵")).toBeInTheDocument()
