    value: { writeText },
  })
  render(
    <div>
      <Snippet defaultValue="pnpm">
        <SnippetHeader>
          <SnippetTabsList>
            <SnippetTabsTrigger value="pnpm">pnpm</SnippetTabsTrigger>
          </SnippetTabsList>
          <SnippetCopyButton value="pnpm add effect-ui" />
        </SnippetHeader>
