import { Pause, Play } from "lucide-react";
import {
  type KeyboardEvent,
  type PointerEvent,
  useEffect,
  useRef,
  useState,
} from "react";
import { useAnimationActive } from "@/hooks/use-animation-active";
import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion";
import { cn } from "@/lib/utils";

const FRAMES = 10;
// Handles pull to whole seconds within this many px.
const SNAP_PX = 5;

type Part = "start" | "end" | "range" | "seek";

export interface ClipRange {
  start: number;
  end: number;
}

export interface ClipTrimmerProps {
  /**
   * A wide image the demo pans across to stand in for footage. Swap the
   * preview and filmstrip for your own video and frame grabs.
   */
  src?: string;
  alt?: string;
  /** Clip length in seconds. */
  duration?: number;
  defaultRange?: ClipRange;
  /** The shortest clip you can trim to, in seconds. */
  minLength?: number;
  onRangeChange?: (range: ClipRange) => void;
  className?: string;
}

const PANORAMA =
  "https://images.unsplash.com/photo-1469474968028-56623f02e42e?w=2400&h=800&fit=crop&auto=format&q=80";

const clamp = (v: number, lo: number, hi: number) =>
  Math.min(hi, Math.max(lo, v));

const formatClock = (s: number) => {
  const tenths = Math.round(s * 10);
  const whole = Math.floor(tenths / 10);
  return `${Math.floor(whole / 60)}:${String(whole % 60).padStart(2, "0")}.${tenths % 10}`;
};

function ClipTrimmer({
  src = PANORAMA,
  alt = "A valley road at dusk",
  duration = 12,
  defaultRange = { start: 2.4, end: 9 },
  minLength = 1,
  onRangeChange,
  className,
}: ClipTrimmerProps) {
  const [range, setRange] = useState<ClipRange>(defaultRange);
  const [time, setTime] = useState(defaultRange.start);
  const [playing, setPlaying] = useState(false);
  const [active, setActive] = useState<Part | null>(null);
  const [snapped, setSnapped] = useState<number | null>(null);
  const rootRef = useRef<HTMLDivElement>(null);

  const motionOn = useAnimationActive(rootRef);
  const prefersReduced = usePrefersReducedMotion();
  const motionOnRef = useRef(false);
  const reducedRef = useRef(false);
  const resumeRef = useRef<() => void>(() => {});
  useEffect(() => {
    motionOnRef.current = motionOn;
    reducedRef.current = prefersReduced;
    resumeRef.current();
  }, [motionOn, prefersReduced]);
  const stripRef = useRef<HTMLDivElement>(null);
  const rangeRef = useRef(range);
  const timeRef = useRef(time);
  const drag = useRef<{
    part: Part;
    x: number;
    from: ClipRange;
    moved: boolean;
  } | null>(null);

  useEffect(() => {
    rangeRef.current = range;
  }, [range]);

  useEffect(() => {
    onRangeChange?.(range);
  }, [range, onRangeChange]);

  // Playback loops inside the kept range.
  useEffect(() => {
    if (!playing) {
      return;
    }
    let frame = 0;
    let last = performance.now();
    const tick = (now: number) => {
      if (!motionOnRef.current) {
        frame = 0;
        last = 0;
        return;
      }
      const { start, end } = rangeRef.current;
      let next = timeRef.current + (last ? (now - last) / 1000 : 0);
      last = now;
      if (next >= end || next < start) {
        next = start;
      }
      timeRef.current = next;
      setTime(next);
      frame = requestAnimationFrame(tick);
    };
    const kick = () => {
      if (!motionOnRef.current) {
        cancelAnimationFrame(frame);
        frame = 0;
        last = 0;
        return;
      }
      if (!frame) {
        last = 0;
        frame = requestAnimationFrame(tick);
      }
    };
    resumeRef.current = kick;
    kick();
    return () => {
      resumeRef.current = () => {};
      cancelAnimationFrame(frame);
    };
  }, [playing]);

  const seek = (t: number) => {
    const next = clamp(t, rangeRef.current.start, rangeRef.current.end);
    timeRef.current = next;
    setTime(next);
  };

  const pxPerSecond = () =>
    (stripRef.current?.getBoundingClientRect().width ?? 1) / duration;

  const secondsAt = (clientX: number) => {
    const rect = stripRef.current?.getBoundingClientRect();
    if (!rect) {
      return 0;
    }
    return clamp(((clientX - rect.left) / rect.width) * duration, 0, duration);
  };

  // A handle near a whole second pulls onto it, like a magnet.
  const snap = (t: number) => {
    const whole = Math.round(t);
    if (Math.abs(whole - t) * pxPerSecond() < SNAP_PX) {
      setSnapped(whole);
      return whole;
    }
    setSnapped(null);
    return t;
  };

  const moveHandle = (part: "start" | "end", t: number) => {
    const { start, end } = rangeRef.current;
    const next =
      part === "start"
        ? { start: clamp(snap(t), 0, end - minLength), end }
        : { start, end: clamp(snap(t), start + minLength, duration) };
    rangeRef.current = next;
    setRange(next);
    // The preview shows the frame you're cutting at.
    const at = part === "start" ? next.start : next.end;
    timeRef.current = at;
    setTime(at);
  };

  const handlePointerDown = (event: PointerEvent<HTMLDivElement>) => {
    if (!event.isPrimary || event.button !== 0 || drag.current) {
      return;
    }
    const target = event.target as HTMLElement;
    const part = (target.closest("[data-part]")?.getAttribute("data-part") ??
      "seek") as Part;
    event.currentTarget.setPointerCapture(event.pointerId);
    drag.current = { part, x: event.clientX, from: range, moved: false };
    setActive(part);
    if (part === "start" || part === "end") {
      setPlaying(false);
    } else if (part === "seek") {
      seek(secondsAt(event.clientX));
    }
  };

  const handlePointerMove = (event: PointerEvent<HTMLDivElement>) => {
    const d = drag.current;
    if (!d) {
      return;
    }
    const dx = event.clientX - d.x;
    if (Math.abs(dx) > 3) {
      d.moved = true;
    }
    if (d.part === "start" || d.part === "end") {
      moveHandle(d.part, d.from[d.part] + dx / pxPerSecond());
    } else if (d.part === "range" && d.moved) {
      const length = d.from.end - d.from.start;
      const start = clamp(
        d.from.start + dx / pxPerSecond(),
        0,
        duration - length
      );
      const next = { start, end: start + length };
      rangeRef.current = next;
      setRange(next);
      seek(timeRef.current);
    } else if (d.part === "seek") {
      seek(secondsAt(event.clientX));
    }
  };

  const endDrag = (event: PointerEvent<HTMLDivElement>) => {
    const d = drag.current;
    if (!d) {
      return;
    }
    // A tap inside the kept range moves the playhead.
    if (d.part === "range" && !d.moved) {
      seek(secondsAt(event.clientX));
    }
    if (d.part === "start" || d.part === "end") {
      seek(rangeRef.current.start);
    }
    drag.current = null;
    setActive(null);
    setSnapped(null);
  };

  const handleKeyDown =
    (part: "start" | "end") => (event: KeyboardEvent<HTMLDivElement>) => {
      const step = event.shiftKey ? 1 : 0.1;
      const moves: Record<string, number> = {
        ArrowLeft: -step,
        ArrowDown: -step,
        ArrowRight: step,
        ArrowUp: step,
        Home: -duration,
        End: duration,
      };
      const move = moves[event.key];
      if (move === undefined) {
        return;
      }
      event.preventDefault();
      const { start, end } = rangeRef.current;
      const from = part === "start" ? start : end;
      const t = Math.round((from + move) * 10) / 10;
      const next =
        part === "start"
          ? { start: clamp(t, 0, end - minLength), end }
          : { start, end: clamp(t, start + minLength, duration) };
      rangeRef.current = next;
      setRange(next);
      seek(part === "start" ? next.start : next.end);
    };

  const togglePlay = () => {
    if (!playing && timeRef.current >= range.end - 0.05) {
      seek(range.start);
    }
    setPlaying((p) => !p);
  };

  const pct = (t: number) => (t / duration) * 100;
  const kept = range.end - range.start;
  const trimming = active === "start" || active === "end";
  const ticks = Array.from({ length: Math.floor(duration) + 1 }, (_, i) => i);
  // A longer, labelled tick every five seconds, like a tape ruler.
  const labelEvery = 5;

  return (
    <div
      data-reduced={prefersReduced ? "true" : "false"}
      data-slot="clip-trimmer"
      ref={rootRef}
      className={cn(
        "w-full max-w-lg select-none rounded-3xl border border-zinc-200 bg-white p-4 text-zinc-900 dark:border-zinc-800 dark:bg-zinc-950 dark:text-zinc-100",
        className
      )}
    >
      <div className="relative aspect-video overflow-hidden rounded-2xl bg-zinc-100 dark:bg-zinc-900">
        <img
          alt={alt}
          className="pointer-events-none absolute inset-0 size-full object-cover"
          draggable={false}
          src={src}
          style={{ objectPosition: `${pct(time)}% 50%` }}
        />
        <span className="absolute bottom-3 left-3 rounded-full bg-black/55 px-2.5 py-1 font-medium text-[11px] text-white tabular-nums">
          {formatClock(time)}
        </span>
        <button
          aria-label={playing ? "Pause" : "Play"}
          className="absolute right-3 bottom-3 flex size-8 items-center justify-center rounded-full bg-black/55 text-white outline-none transition-colors duration-150 ease-out hover:bg-black/70 focus-visible:ring-2 focus-visible:ring-white"
          onClick={togglePlay}
          type="button"
        >
          {playing ? (
            <Pause aria-hidden className="size-3.5" fill="currentColor" />
          ) : (
            <Play
              aria-hidden
              className="size-3.5 translate-x-px"
              fill="currentColor"
            />
          )}
        </button>
      </div>

      <div className="mt-5 px-4">
        <div
          className="relative h-14 cursor-pointer touch-none"
          onLostPointerCapture={endDrag}
          onPointerCancel={endDrag}
          onPointerDown={handlePointerDown}
          onPointerMove={handlePointerMove}
          onPointerUp={endDrag}
          ref={stripRef}
        >
          {/* Filmstrip: one wide shot, cut into frames. */}
          <div className="absolute inset-0 flex overflow-hidden rounded-lg bg-zinc-200 dark:bg-zinc-800">
            {Array.from({ length: FRAMES }, (_, i) => (
              <div
                className="relative h-full flex-1 border-black/10 border-r last:border-r-0"
                // biome-ignore lint/suspicious/noArrayIndexKey: fixed frame slots
                key={i}
              >
                <img
                  alt=""
                  className="pointer-events-none absolute inset-0 size-full object-cover"
                  draggable={false}
                  src={src}
                  style={{
                    objectPosition: `${(i / (FRAMES - 1)) * 100}% 50%`,
                  }}
                />
              </div>
            ))}
          </div>

          {/* What gets cut is dimmed. Full-width layers moved by transform. */}
          <div className="pointer-events-none absolute inset-0 overflow-hidden rounded-lg">
            <div
              className="absolute inset-0 bg-white/75 dark:bg-zinc-950/75"
              style={{ transform: `translateX(${pct(range.start) - 100}%)` }}
            />
            <div
              className="absolute inset-0 bg-white/75 dark:bg-zinc-950/75"
              style={{ transform: `translateX(${pct(range.end)}%)` }}
            />
          </div>

          {/* Playhead */}
          <div
            className={cn(
              "pointer-events-none absolute -inset-y-1 left-0 w-full transition-opacity duration-150 ease-out",
              trimming ? "opacity-0" : "opacity-100"
            )}
            style={{ transform: `translateX(${pct(time)}%)` }}
          >
            <div className="relative h-full w-px -translate-x-1/2 bg-zinc-900 dark:bg-white">
              <span className="absolute -top-0.5 left-1/2 size-[7px] -translate-x-1/2 rounded-full bg-zinc-900 dark:bg-white" />
            </div>
          </div>

          {/* Kept range: the frame, its two handles and the drag area. */}
          <div
            className={cn(
              "absolute inset-y-0 border-orange-600 border-y-[3px]",
              active === "range" ? "cursor-grabbing" : "cursor-grab"
            )}
            data-part="range"
            style={{
              left: `${pct(range.start)}%`,
              width: `${pct(kept)}%`,
            }}
          >
            {(["start", "end"] as const).map((part) => (
              <div
                aria-label={part === "start" ? "Trim start" : "Trim end"}
                aria-valuemax={duration}
                aria-valuemin={0}
                aria-valuenow={Math.round(range[part] * 10) / 10}
                aria-valuetext={`${range[part].toFixed(1)} seconds`}
                className={cn(
                  "group absolute -inset-y-[3px] flex w-4 cursor-ew-resize items-center justify-center bg-orange-600 outline-none focus-visible:ring-2 focus-visible:ring-zinc-400 focus-visible:ring-offset-2 dark:focus-visible:ring-offset-zinc-950",
                  part === "start"
                    ? "-left-4 rounded-l-lg"
                    : "-right-4 rounded-r-lg"
                )}
                data-part={part}
                key={part}
                onKeyDown={handleKeyDown(part)}
                role="slider"
                tabIndex={0}
              >
                <span
                  className={cn(
                    "h-5 w-[3px] rounded-full bg-white/60 transition-colors duration-150 ease-out",
                    active === part && "bg-white"
                  )}
                />
                {/* The exact cut point, while trimming. */}
                <span
                  className={cn(
                    "pointer-events-none absolute -top-8 rounded-md bg-zinc-900 px-1.5 py-0.5 text-[11px] text-white tabular-nums transition-opacity duration-150 ease-out dark:bg-zinc-100 dark:text-zinc-900",
                    active === part ? "opacity-100" : "opacity-0"
                  )}
                >
                  {formatClock(range[part])}
                </span>
              </div>
            ))}
          </div>
        </div>

        {/* Ruler: whole seconds, the one a handle snapped to lights up. */}
        <div aria-hidden className="relative mt-2 h-5">
          {ticks.map((s) => (
            <span
              className="absolute top-0 flex -translate-x-1/2 flex-col items-center"
              key={s}
              style={{ left: `${pct(s)}%` }}
            >
              <span
                className={cn(
                  "w-px transition-colors duration-150 ease-out",
                  s % labelEvery === 0 ? "h-2" : "h-1",
                  snapped === s
                    ? "bg-orange-600"
                    : "bg-zinc-300 dark:bg-zinc-700"
                )}
              />
              {s % labelEvery === 0 && (
                <span
                  className={cn(
                    "mt-0.5 text-[10px] tabular-nums transition-colors duration-150 ease-out",
                    snapped === s
                      ? "text-orange-700 dark:text-orange-400"
                      : "text-zinc-400 dark:text-zinc-500"
                  )}
                >
                  {s}s
                </span>
              )}
            </span>
          ))}
        </div>
      </div>

      <div className="mt-3 flex items-center justify-between gap-3 px-1 text-sm">
        <p className="text-zinc-500 tabular-nums dark:text-zinc-400">
          <span className="font-medium text-zinc-900 dark:text-zinc-100">
            {kept.toFixed(1)}s
          </span>{" "}
          of {duration.toFixed(1)}s
        </p>
        <button
          className="rounded-full px-3 py-1 text-xs text-zinc-500 outline-none transition-colors duration-150 ease-out hover:bg-zinc-100 hover:text-zinc-900 focus-visible:ring-2 focus-visible:ring-zinc-400 disabled:pointer-events-none disabled:opacity-40 dark:text-zinc-400 dark:hover:bg-zinc-900 dark:hover:text-zinc-100"
          disabled={range.start === 0 && range.end === duration}
          onClick={() => {
            const full = { start: 0, end: duration };
            rangeRef.current = full;
            setRange(full);
            seek(timeRef.current);
          }}
          type="button"
        >
          Reset
        </button>
      </div>
    </div>
  );
}

export { ClipTrimmer }

"use client"

import * as React from "react"

import { useAnimationActive } from "@/hooks/use-animation-active"
import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { cn } from "@/lib/utils"

export interface ClothWindBannerProps {
  className?: string
  texture?: string
  intensity?: number
  speed?: number
  colors?: readonly string[]
}

const DEFAULT_COLORS = ["#7c3aed", "#ea580c"] as const

function useSynced(prop: number | undefined, fallback: number) {
  const [draft, setDraft] = React.useState<{ prop: number | undefined; value: number } | null>(null)
  const value = draft && Object.is(draft.prop, prop) ? draft.value : (prop ?? fallback)
  return [value, (next: number) => setDraft({ prop, value: next })] as const
}

const VERT = `
attribute vec2 uv;
attribute vec3 position;
uniform float u_time;
uniform float u_wind;
uniform float u_speed;
uniform vec2 u_mouse;
uniform mat4 modelViewMatrix;
uniform mat4 projectionMatrix;
varying vec2 vUv;
varying float vLight;

float heightAt(vec2 p) {
  float wave = sin(p.x * 7.0 + u_time * u_speed * (0.7 + u_wind)) * 0.12;
  wave += sin(p.x * 15.0 - u_time * u_speed * 1.6 + p.y * 5.0) * 0.05;
  wave += sin(p.x * 28.0 + p.y * 19.0 + u_time * u_speed * 2.2) * 0.02;
  float dx = p.x - u_mouse.x;
  float dy = p.y - u_mouse.y;
  float bulge = exp(-(dx * dx + dy * dy) * 14.0) * 0.28;
  float pin = smoothstep(0.0, 0.2, p.x);
  return (wave * u_wind + bulge) * pin;
}

void main() {
  vUv = uv;
  float lift = heightAt(uv);
  float e = 0.02;
  float dx = heightAt(uv + vec2(e, 0.0)) - heightAt(uv - vec2(e, 0.0));
  float dy = heightAt(uv + vec2(0.0, e)) - heightAt(uv - vec2(0.0, e));
  vec3 normal = normalize(vec3(-dx, -dy, 1.0));
  vLight = clamp(dot(normal, normalize(vec3(-0.2, 0.35, 1.0))), 0.25, 1.0);
  vec3 displaced = position + vec3(0.0, 0.0, lift);
  gl_Position = projectionMatrix * modelViewMatrix * vec4(displaced, 1.0);
}
`

const FRAG = `
precision highp float;
uniform sampler2D u_map;
varying vec2 vUv;
varying float vLight;
void main() {
  vec3 tex = texture2D(u_map, vUv).rgb;
  gl_FragColor = vec4(tex * vLight, 1.0);
}
`

function paintBanner(primary: string, secondary: string) {
  const canvas = document.createElement("canvas")
  canvas.width = 512
  canvas.height = 256
  const context = canvas.getContext("2d")
  if (!context) return canvas
  for (let row = 0; row < 8; row += 1) {
    context.fillStyle = row % 2 === 0 ? primary : secondary
    context.fillRect(0, row * 32, 512, 32)
  }
  context.fillStyle = "#fef3c7"
  context.beginPath()
  context.arc(390, 128, 42, 0, Math.PI * 2)
  context.fill()
  return canvas
}

function ClothFallback({ colors }: { colors: readonly string[] }) {
  const primary = colors[0] ?? DEFAULT_COLORS[0]
  const secondary = colors[1] ?? DEFAULT_COLORS[1]
  return (
    <div
      className="absolute inset-x-10 inset-y-16 rounded-md"
      style={{ background: `repeating-linear-gradient(180deg, ${primary} 0 16px, ${secondary} 16px 32px)` }}
    />
  )
}

function playbackRate(speed: number) {
  return Number.isFinite(speed) && speed > 0 ? speed : 1
}

function ClothWindBanner({
  className,
  texture,
  intensity,
  speed = 1,
  colors = DEFAULT_COLORS,
}: ClothWindBannerProps) {
  const reduced = usePrefersReducedMotion()
  const hostRef = React.useRef<HTMLDivElement>(null)
  const canvasRef = React.useRef<HTMLCanvasElement>(null)
  const mouseRef = React.useRef({ x: 0.7, y: 0.5 })
  const windRef = React.useRef(intensity ?? 0.65)
  const speedRef = React.useRef(playbackRate(speed))
  const colorsRef = React.useRef(colors)
  const active = useAnimationActive(hostRef)
  const [wind, setWind] = useSynced(intensity, 0.65)
  const [fallback, setFallback] = React.useState(false)
  const showCanvas = !reduced && !fallback
  const label = wind < 0.34 ? "微风" : wind < 0.7 ? "和风" : "劲风"

  React.useEffect(() => {
    windRef.current = wind
    speedRef.current = playbackRate(speed)
    colorsRef.current = colors
  }, [wind, speed, colors])

  React.useEffect(() => {
    if (!showCanvas || !active) return
    const canvas = canvasRef.current
    const host = hostRef.current
    if (!canvas || !host) return
    let cancelled = false
    let frame = 0
    const run = async () => {
      const ogl = await import("ogl")
      if (cancelled) return undefined
      const renderer = new ogl.Renderer({ canvas, alpha: true, dpr: Math.min(window.devicePixelRatio || 1, 2) })
      const gl = renderer.gl
      if (!gl) {
        queueMicrotask(() => {
          if (!cancelled) setFallback(true)
        })
        return undefined
      }
      const camera = new ogl.Camera(gl, { fov: 32 })
      camera.position.set(0, 0, 2.4)
      const scene = new ogl.Transform()
      const geometry = new ogl.Plane(gl, { width: 2.4, height: 0.9, widthSegments: 56, heightSegments: 18 })
      const stripe = texture
        ? [DEFAULT_COLORS[0], DEFAULT_COLORS[1]]
        : [colorsRef.current[0] ?? DEFAULT_COLORS[0], colorsRef.current[1] ?? DEFAULT_COLORS[1]]
      const image = paintBanner(stripe[0] ?? DEFAULT_COLORS[0], stripe[1] ?? DEFAULT_COLORS[1])
      const map = new ogl.Texture(gl, { image, wrapS: gl.CLAMP_TO_EDGE, wrapT: gl.CLAMP_TO_EDGE })
      if (texture) {
        const picture = new Image()
        picture.onload = () => {
          map.image = picture
          map.needsUpdate = true
        }
        picture.src = texture
      }
      const uniforms = {
        u_time: { value: 0 },
        u_wind: { value: windRef.current },
        u_speed: { value: speedRef.current },
        u_mouse: { value: [0.7, 0.5] },
        u_map: { value: map },
      }
      const program = new ogl.Program(gl, { vertex: VERT, fragment: FRAG, uniforms })
      program.cullFace = false
      const mesh = new ogl.Mesh(gl, { geometry, program, frustumCulled: false })
      mesh.setParent(scene)
      const resize = () => {
        const rect = host.getBoundingClientRect()
        renderer.setSize(Math.max(rect.width, 1), Math.max(rect.height, 1))
        camera.perspective({ aspect: Math.max(rect.width, 1) / Math.max(rect.height, 1) })
      }
      resize()
      const observer = new ResizeObserver(resize)
      observer.observe(host)
      const started = performance.now()
      let stripeKey = texture ? "" : `${stripe[0]}|${stripe[1]}`
      const tick = () => {
        if (!texture) {
          const primary = colorsRef.current[0] ?? DEFAULT_COLORS[0]
          const secondary = colorsRef.current[1] ?? DEFAULT_COLORS[1]
          const key = `${primary}|${secondary}`
          if (key !== stripeKey) {
            stripeKey = key
            map.image = paintBanner(primary, secondary)
            map.needsUpdate = true
          }
        }
        uniforms.u_time.value = (performance.now() - started) / 1000
        uniforms.u_wind.value = windRef.current
        uniforms.u_speed.value = speedRef.current
        uniforms.u_mouse.value = [mouseRef.current.x, mouseRef.current.y]
        renderer.render({ scene, camera })
        frame = window.requestAnimationFrame(tick)
      }
      frame = window.requestAnimationFrame(tick)
      return () => {
        window.cancelAnimationFrame(frame)
        observer.disconnect()
        gl.getExtension("WEBGL_lose_context")?.loseContext()
      }
    }
    const job = run().catch(() => {
      if (!cancelled) {
        queueMicrotask(() => {
          if (!cancelled) setFallback(true)
        })
      }
      return undefined
    })
    return () => {
      cancelled = true
      window.cancelAnimationFrame(frame)
      void job.then((cleanup) => cleanup?.())
    }
  }, [active, showCanvas, texture])

  return (
    <div data-slot="cloth-wind-banner" className={cn("w-full space-y-3", className)}>
      <label className="flex items-center gap-3 text-sm">
        风力
        <input
          type="range"
          min={0}
          max={1}
          step={0.01}
          value={wind}
          aria-valuetext={label}
          className="w-40"
          onChange={(event) => setWind(Number(event.target.value))}
        />
        <span>{label}</span>
      </label>
      <div
        ref={hostRef}
        className="relative h-64 overflow-hidden rounded-xl border bg-slate-950"
        onPointerMove={(event) => {
          const rect = event.currentTarget.getBoundingClientRect()
          mouseRef.current = {
            x: (event.clientX - rect.left) / Math.max(rect.width, 1),
            y: 1 - (event.clientY - rect.top) / Math.max(rect.height, 1),
          }
        }}
      >
        {showCanvas ? <canvas ref={canvasRef} className="absolute inset-0 size-full" /> : <ClothFallback colors={colors} />}
      </div>
    </div>
  )
}

export { ClothWindBanner }

// @vitest-environment jsdom

import { afterEach, beforeEach, expect, test, vi } from "vitest"
import { act, cleanup, fireEvent, render, screen, within } from "@testing-library/react"
import "@testing-library/jest-dom/vitest"
import Matter from "matter-js"

import { CoinJar } from "./coin-jar"

let reduceMotion = false
let now = 0
let rafId = 0
const queue = new Map<number, FrameRequestCallback>()
let createSpy: ReturnType<typeof vi.spyOn>

beforeEach(() => {
  reduceMotion = false
  now = 0
  rafId = 0
  queue.clear()
  vi.stubGlobal("matchMedia", (query: string) => ({
    matches: query.includes("prefers-reduced-motion") ? reduceMotion : false,
    media: query,
    addEventListener() {},
    removeEventListener() {},
    addListener() {},
    removeListener() {},
    dispatchEvent() {
      return false
    },
  }))
  vi.stubGlobal("requestAnimationFrame", (cb: FrameRequestCallback) => {
    rafId += 1
    queue.set(rafId, cb)
    return rafId
  })
  vi.stubGlobal("cancelAnimationFrame", (handle: number) => {
    queue.delete(handle)
  })
  createSpy = vi.spyOn(Matter.Engine, "create")
})

afterEach(() => {
  cleanup()
  createSpy.mockRestore()
  vi.unstubAllGlobals()
})

function pump(steps: number) {
  act(() => {
    for (let i = 0; i < steps; i += 1) {
      const next = queue.entries().next().value as [number, FrameRequestCallback] | undefined
      if (!next) break
      queue.delete(next[0])
      now += 32
      next[1](now)
    }
  })
}

function jar() {
  return screen.getByRole("application", { name: "投币罐" })
}

function stackedCoin() {
  return within(screen.getByRole("list", { name: "罐内" })).getByText("1元")
}

test("默认展示待投入的硬币，不标记减弱动效", () => {
  render(<CoinJar />)
  expect(screen.getByRole("list", { name: "待投入" })).toHaveTextContent("1元")
  expect(screen.getByText("还没有硬币")).toBeInTheDocument()
  expect(screen.getByText("1元")).toHaveStyle({ backgroundColor: "var(--primary)" })
  expect(document.querySelector("[data-slot='coin-jar']")).not.toHaveAttribute("data-reduced")
  expect(document.querySelector("[data-slot='coin-jar']")).toHaveAttribute("data-stacked", "0")
  expect(createSpy).toHaveBeenCalled()
})

test("点击把硬币投入罐中并回调", () => {
  const onDrop = vi.fn()
  render(<CoinJar onDrop={onDrop} />)
  fireEvent.pointerUp(jar(), { button: 0, clientX: 20, clientY: 40, pointerId: 1, pointerType: "mouse" })
  expect(onDrop).toHaveBeenCalledWith("one")
  expect(jar()).toHaveAttribute("data-stacked", "1")
  expect(screen.getByRole("list", { name: "罐内" })).toHaveTextContent("1元")
  expect(screen.getByRole("list", { name: "待投入" })).not.toHaveTextContent("1元")
  expect(screen.queryByText("还没有硬币")).toBeNull()
})

test("投入后几帧，硬币开始下落", () => {
  render(<CoinJar />)
  fireEvent.pointerUp(jar(), { button: 0, clientX: 12, clientY: 12, pointerId: 1, pointerType: "mouse" })
  const coin = stackedCoin()
  expect(coin.style.transform).toBe("")
  pump(6)
  expect(coin.style.transform).toContain("translate")
})

test("向下键投入一枚硬币", () => {
  const onDrop = vi.fn()
  render(<CoinJar onDrop={onDrop} />)
  fireEvent.keyDown(jar(), { key: "ArrowDown" })
  expect(onDrop).toHaveBeenCalledWith("one")
  expect(jar()).toHaveAttribute("data-stacked", "1")
})

test("触屏点击同样能投入，不依赖悬停", () => {
  const onDrop = vi.fn()
  render(<CoinJar onDrop={onDrop} />)
  fireEvent.pointerUp(jar(), { clientX: 16, clientY: 30, pointerId: 3, pointerType: "touch" })
  expect(onDrop).toHaveBeenCalledWith("one")
})

test("减弱动效时硬币直接叠上，不创建引擎也不申请动画帧", () => {
  reduceMotion = true
  const onDrop = vi.fn()
  render(<CoinJar onDrop={onDrop} />)
  const root = document.querySelector("[data-slot='coin-jar']")
  expect(root).toHaveAttribute("data-reduced", "true")
  expect(root).not.toHaveAttribute("data-physics")
  fireEvent.keyDown(jar(), { key: "Enter" })
  pump(4)
  expect(onDrop).toHaveBeenCalledWith("one")
  expect(stackedCoin().style.transform).toBe("")
  expect(createSpy).not.toHaveBeenCalled()
  expect(queue.size).toBe(0)
})

