              </th>
              <th scope="col" className="px-3 py-2 font-mono text-xs font-normal text-muted-foreground">
                <span className="sr-only">Refund action</span>
              </th>
            </tr>
          </thead>
          <tbody>
            {rows.map((row, idx) => {
              const { input, amount, struck, committed, dragging, contraOpen } = row;
              const refundAmount = amount * struck;
              const bar = barPx(amount);
              const ruleLen = struck * bar;
              const struckUnits = input.qty > 1 ? Math.round(struck * input.qty) : 0;
              const valueText =
                input.qty > 1
                  ? `${money(refundAmount)} of ${money(amount)}, ${struckUnits} of ${input.qty} units`
                  : `${money(refundAmount)} of ${money(amount)}`;
              const armed = struck > 0;
              const flashing = flashIdx === idx;

              return (
                <Fragment key={input.id}>
                  <tr
                    className={
                      "border-b border-border last:border-b-0" +
                      (committed ? " align-top" : "")
                    }
                    {...(committed
                      ? { "aria-description": "partially refunded, see contra entry below" }
                      : {})}
                  >
                    <th scope="row" className="px-3 py-2 align-top font-mono text-xs font-normal text-foreground">
                      {input.description}
                    </th>
                    <td className="px-3 py-2 text-right align-top font-mono text-xs tabular-nums text-muted-foreground">
                      {input.qty}
                    </td>
                    <td className="px-3 py-2 align-top">
                      {/* the interactive slider below is entirely aria-hidden
                      inside (aria-valuetext is its single source of truth for
                      AT); this sibling restores the cell's plain reading-mode
                      data — the billed amount, struck once refunded — so the
                      row stays real, walkable table content and not just a
                      widget's private value */}
                      <span className="sr-only">
                        {money(amount)}
                        {committed ? ", struck, see contra entry below" : ""}
                      </span>
                      <div
                        ref={(el) => {
                          trackRefs.current[idx] = el;
                        }}
                        data-track={idx}
                        role="slider"
                        tabIndex={committed ? -1 : 0}
                        aria-disabled={committed || undefined}
                        aria-label={`Refund ${input.description}`}
                        aria-orientation="horizontal"
                        aria-valuemin={0}
                        aria-valuemax={100}
                        aria-valuenow={Math.round(struck * 100)}
                        aria-valuetext={valueText}
                        onKeyDown={(e) => onTrackKeyDown(e, idx)}
                        onPointerDown={(e) => {
                          if (committed) return;
                          e.preventDefault();
                          e.currentTarget.setPointerCapture(e.pointerId);
                          trackDrag(idx, e.clientX, true);
                        }}
                        onPointerMove={(e) => {
                          if (!dragging) return;
                          trackDrag(idx, e.clientX, true);
                        }}
                        onPointerUp={() => updateStruck(idx, struck, false)}
                        onPointerCancel={() => updateStruck(idx, struck, false)}
                        style={{ width: TRACK_W, height: ROW_H }}
                        className={
                          "relative select-none rounded-sm outline-none transition-colors focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background" +
                          (committed
                            ? " cursor-default"
                            : " cursor-ew-resize touch-none hover:bg-foreground/[0.035]") +
                          (flashing ? " ns-cs-flash" : "")
                        }
                      >
                        {/* the slider's own visual layers (bar, numeral, rule)
                        carry no text to assistive tech — aria-valuetext above
                        is the single source of truth for the control's value
                        — so the billed amount is restated here as real,
                        readable table-cell data, exactly once */}
                        <span className="sr-only">
                          {money(amount)}
                          {committed ? ", struck, see contra entry below" : ""}
                        </span>
                        <span
                          aria-hidden
                          className="absolute left-0 top-1/2 -translate-y-1/2 rounded-full bg-foreground/[0.07]"
                          style={{ width: bar, height: 3 }}
                        />
                        <span
                          aria-hidden
                          className={
                            "absolute left-0 top-1/2 flex h-full -translate-y-1/2 items-center font-mono text-sm tabular-nums" +
                            (committed
                              ? " text-foreground line-through decoration-1 decoration-foreground/70"
                              : " text-foreground")
                          }
                        >
                          {money(amount)}
                        </span>
                        {armed ? (
                          <svg
                            aria-hidden
                            className="ns-cs-rule pointer-events-none absolute inset-0"
                            width={TRACK_W}
                            height={ROW_H}
                          >
                            <line
                              x1={0}
                              y1={ROW_H / 2}
                              x2={Math.max(1, ruleLen)}
                              y2={ROW_H / 2}
                              stroke="var(--foreground)"
                              strokeWidth={1.5}
                              strokeLinecap="round"
                              strokeDasharray={committed ? undefined : "4 3"}
                            />
                          </svg>
                        ) : null}
                      </div>
                    </td>
                    <td className="px-3 py-2 align-top text-right">
                      <button
                        type="button"
                        data-commit={idx}
                        onClick={() => commitLine(idx)}
                        className="rounded-sm border border-border px-2.5 py-1 font-mono text-xs text-foreground transition-colors hover:bg-foreground/[0.05] focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring disabled:pointer-events-none disabled:opacity-40"
                        disabled={committed || !armed}
                      >
                        {committed
                          ? "Refunded"
                          : armed
                            ? `Refund ${money(refundAmount)}`
                            : "Refund"}
                      </button>
                    </td>
                  </tr>

                  {committed ? (
                    <tr key={`${input.id}-contra`} data-contra={idx} className="border-b border-border last:border-b-0">
                      <td colSpan={4} className="p-0">
                        <div
                          className="ns-cs-contra"
                          style={{ height: contraOpen ? ROW_H : 0, opacity: contraOpen ? 1 : 0 }}
                        >
                          <div
                            className="flex items-center gap-3 px-3 font-mono text-xs"
                            style={{ height: ROW_H, animation: contraOpen ? "ns-cs-contra-row 200ms ease-out" : "none" }}
                          >
                            <span className="w-0 flex-1 truncate text-muted-foreground">
                              Contra — {input.description}
                            </span>
                            <span className="shrink-0 text-right text-muted-foreground">
                              {input.qty > 1 ? `−${struckUnits} of ${input.qty} units` : ""}
                            </span>
                            <span
                              aria-hidden
                              className="relative shrink-0 rounded-full bg-foreground/[0.14]"
                              style={{ width: ruleLen, height: 3 }}
                            />
                            <span className="shrink-0 tabular-nums text-foreground">
                              −{money(refundAmount)}
                            </span>
                          </div>
                        </div>
                      </td>
                    </tr>
                  ) : null}
                </Fragment>
              );
            })}
          </tbody>
          <tfoot>
            <tr className="border-t border-border">
              <th scope="row" colSpan={3} className="px-3 py-2 text-right font-mono text-xs font-normal text-muted-foreground">
                Subtotal
              </th>
              <td className="px-3 py-2 text-right font-mono text-xs tabular-nums text-muted-foreground">
                {money(subtotal)}
              </td>
            </tr>
            <tr>
              <th scope="row" colSpan={3} className="px-3 py-2 text-right font-mono text-xs font-normal text-muted-foreground">
                Refunded
              </th>
              <td className="px-3 py-2 text-right font-mono text-xs tabular-nums text-muted-foreground">
                −{money(refunded)}
              </td>
            </tr>
            <tr className="border-t border-border">
              <th scope="row" colSpan={3} className="px-3 py-2 text-right font-mono text-sm font-medium text-foreground">
                Balance
              </th>
              <td className="px-3 py-2 text-right align-middle">
                <span
                  className={"relative inline-block font-mono text-sm font-medium tabular-nums text-foreground" + (balanceFlash ? " ns-cs-flash" : "")}
                >
                  {money(balance)}
                </span>
              </td>
            </tr>
          </tfoot>
        </table>
      </div>

      <p role="status" aria-live="polite" className="sr-only">
        {announcement}
      </p>
    </div>
  );
}

"use client"

import { motion } from "motion/react"
import * as React from "react"

import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { cn } from "@/lib/utils"

export interface CookieConsentValue {
  necessary: true
  analytics: boolean
  marketing: boolean
}

export interface CookieConsentProps {
  className?: string
  storageKey?: string
  onChange?: (value: CookieConsentValue) => void
}

const STORAGE_EVENT = "effect-ui-consent"

function subscribe(onStoreChange: () => void) {
  window.addEventListener("storage", onStoreChange)
  window.addEventListener(STORAGE_EVENT, onStoreChange)
  return () => {
    window.removeEventListener("storage", onStoreChange)
    window.removeEventListener(STORAGE_EVENT, onStoreChange)
  }
}

function readRaw(storageKey: string) {
  try {
    return window.localStorage.getItem(storageKey)
  } catch {
    return null
  }
}

function parseConsent(raw: string | null): CookieConsentValue | null {
  if (!raw) return null
  try {
    const value = JSON.parse(raw) as Partial<CookieConsentValue>
    if (typeof value.analytics !== "boolean" || typeof value.marketing !== "boolean") return null
    return { necessary: true, analytics: value.analytics, marketing: value.marketing }
  } catch {
    return null
  }
}

function writeConsent(storageKey: string, value: CookieConsentValue | null) {
  try {
    if (value) window.localStorage.setItem(storageKey, JSON.stringify(value))
    else window.localStorage.removeItem(storageKey)
  } catch {
    return
  }
  window.dispatchEvent(new Event(STORAGE_EVENT))
}

function Switch({
  label,
  checked,
  disabled,
  onToggle,
}: {
  label: string
  checked: boolean
  disabled?: boolean
  onToggle?: () => void
}) {
  return (
    <button
      type="button"
      role="switch"
      aria-checked={checked}
      aria-disabled={disabled || undefined}
      disabled={disabled}
      onClick={onToggle}
      className="flex w-full items-center justify-between gap-3 rounded-md px-1 py-1.5 text-left text-sm disabled:opacity-70"
    >
      <span>{label}</span>
      <span
        className={cn(
          "relative h-5 w-9 rounded-full",
          checked ? "bg-primary" : "bg-muted-foreground/30",
        )}
      >
        <span
          className={cn(
            "absolute top-0.5 size-4 rounded-full bg-white",
            checked ? "left-4" : "left-0.5",
          )}
        />
      </span>
    </button>
  )
}

function CookieConsent({
  className,
  storageKey = "effect-ui-cookie-consent",
  onChange,
}: CookieConsentProps) {
  const reduced = usePrefersReducedMotion()
  const raw = React.useSyncExternalStore(
    subscribe,
    () => readRaw(storageKey),
    () => null,
  )
  const saved = parseConsent(raw)
  const [expanded, setExpanded] = React.useState(false)
  const [draft, setDraft] = React.useState<CookieConsentValue>({
    necessary: true,
    analytics: false,
    marketing: false,
  })

  const save = (value: CookieConsentValue) => {
    writeConsent(storageKey, value)
    onChange?.(value)
    setDraft(value)
    setExpanded(false)
  }

  const shell = cn(
    "fixed right-4 bottom-4 z-40 w-[22rem] max-w-[calc(100%-2rem)] rounded-xl border bg-popover p-4 text-popover-foreground shadow-xl",
    className,
  )

  if (saved) {
    return (
      <div data-slot="cookie-consent" className={shell}>
        <p className="text-sm font-medium">偏好已保存</p>
        <p className="mt-1 text-xs text-muted-foreground">
          分析 {saved.analytics ? "开启" : "关闭"} · 营销 {saved.marketing ? "开启" : "关闭"}
        </p>
        <button
          type="button"
          className="mt-3 text-sm text-primary underline-offset-4 hover:underline"
          onClick={() => writeConsent(storageKey, null)}
        >
          重新选择
        </button>
      </div>
    )
  }

  return (
    <div data-slot="cookie-consent" className={shell} role="dialog" aria-label="Cookie 偏好">
      <p className="text-sm font-medium">这个演示会记住你的选择</p>
      <p className="mt-1 text-xs leading-5 text-muted-foreground">
        必要项始终开启。分析和营销可以单独开关，结果写在本机 localStorage。
      </p>
      <button
        type="button"
        className="mt-3 text-sm underline-offset-4 hover:underline"
        aria-expanded={expanded}
        onClick={() => setExpanded((current) => !current)}
      >
        {expanded ? "收起类别" : "自定义类别"}
      </button>
      {expanded ? (
        <motion.div
          initial={reduced ? false : { height: 0, opacity: 0 }}
          animate={{ height: "auto", opacity: 1 }}
          transition={{ duration: reduced ? 0 : 0.22 }}
          className="overflow-hidden"
        >
          <div className="mt-2 space-y-1 rounded-lg border p-2">
            <Switch label="必要" checked disabled />
            <Switch
              label="分析"
              checked={draft.analytics}
              onToggle={() => setDraft((current) => ({ ...current, analytics: !current.analytics }))}
            />
            <Switch
              label="营销"
              checked={draft.marketing}
              onToggle={() => setDraft((current) => ({ ...current, marketing: !current.marketing }))}
            />
          </div>
        </motion.div>
      ) : null}
      <div className="mt-3 flex flex-wrap gap-2">
        <button
          type="button"
          className="rounded-md bg-primary px-3 py-1.5 text-sm text-primary-foreground"
          onClick={() => save({ necessary: true, analytics: true, marketing: true })}
        >
          全部接受
        </button>
        <button
          type="button"
          className="rounded-md border px-3 py-1.5 text-sm"
          onClick={() => save({ necessary: true, analytics: false, marketing: false })}
        >
          全部拒绝
        </button>
        <button
          type="button"
          className="rounded-md border px-3 py-1.5 text-sm"
          onClick={() => save(draft)}
        >
          保存选择
        </button>
      </div>
    </div>
  )
}

export { CookieConsent }

