const CONFETTI = [
  { x: -90, y: -76, rotate: 30, color: "#a78bfa" },
  { x: -50, y: -96, rotate: 80, color: "#22d3ee" },
  { x: -16, y: -70, rotate: 12, color: "#f472b6" },
  { x: 18, y: -100, rotate: 140, color: "#facc15" },
  { x: 54, y: -82, rotate: 60, color: "#34d399" },
  { x: 92, y: -64, rotate: 200, color: "#fb7185" },
  { x: -70, y: -40, rotate: 100, color: "#38bdf8" },
  { x: 70, y: -48, rotate: 16, color: "#c084fc" },
]

function digitsOf(value: number, count: number) {
  const safe = Math.max(0, Math.floor(value))
  return Array.from({ length: count }, (_, index) => {
    const power = 10 ** (count - index - 1)
    return Math.floor(safe / power) % 10
  })
}

function RollDigit({ value, reduced, speed }: { value: number; reduced: boolean; speed?: number }) {
  return (
    <span className="relative inline-block h-[1em] w-[0.66em] overflow-hidden">
      <motion.span
        className="absolute inset-x-0 top-0 flex flex-col items-center"
        animate={{ y: `${-value}em` }}
        transition={
          reduced
            ? { duration: 0 }
            : speed === undefined || speed === 1
              ? { type: "spring", stiffness: 220, damping: 24 }
              : { type: "spring", stiffness: 220 * speed, damping: 24 }
        }
      >
        {Array.from({ length: 10 }, (_, digit) => (
          <span key={digit} className="flex h-[1em] items-center justify-center">
            {digit}
          </span>
        ))}
      </motion.span>
    </span>
  )
}

function Unit({
  label,
  value,
  places,
  reduced,
  speed,
  fontSize,
}: {
  label: string
  value: number
  places: number
  reduced: boolean
  speed?: number
  fontSize?: number
}) {
  const keepSize = fontSize === undefined || fontSize === 36
  return (
    <div className="min-w-14 text-center">
      <div
        className={
          keepSize
            ? "font-display text-4xl leading-none tracking-tight tabular-nums"
            : "font-display leading-none tracking-tight tabular-nums"
        }
        style={keepSize ? undefined : { fontSize }}
      >
        {digitsOf(value, places).map((digit, index) => (
          <RollDigit key={`${label}-${index}`} value={digit} reduced={reduced} speed={speed} />
        ))}
      </div>
      <p className="mt-2 text-xs text-muted-foreground">{label}</p>
    </div>
  )
}

function CountdownTimer({
  durationSeconds = 86400,
  confetti = false,
  onComplete,
  className,
  gap,
  speed,
  duration,
  fontSize,
}: CountdownTimerProps) {
  const reduced = usePrefersReducedMotion()
  const [remaining, setRemaining] = React.useState(durationSeconds)
  const onCompleteRef = React.useRef(onComplete)

  React.useEffect(() => {
    onCompleteRef.current = onComplete
  }, [onComplete])

  React.useEffect(() => {
    let finished = false
    const started = Date.now()
    const id = window.setInterval(() => {
      const left = Math.max(0, durationSeconds - Math.floor((Date.now() - started) / 1000))
      setRemaining(left)
      if (left === 0) {
        window.clearInterval(id)
        if (!finished) {
          finished = true
          onCompleteRef.current?.()
        }
      }
    }, 200)
    return () => window.clearInterval(id)
  }, [durationSeconds])

  const days = Math.floor(remaining / 86400)
  const hours = Math.floor(remaining / 3600) % 24
  const minutes = Math.floor(remaining / 60) % 60
  const seconds = remaining % 60
  const dayPlaces = days >= 100 ? 3 : 2
  const showConfetti = confetti && remaining === 0 && !reduced

  return (
    <div
      data-slot="countdown-timer"
      className={cn("relative w-full overflow-hidden rounded-xl border bg-background px-4 py-6", className)}
    >
      <div className="sr-only" aria-live="polite">
        剩余 {days} 天 {hours} 小时 {minutes} 分 {seconds} 秒
        {remaining === 0 ? "，计时结束" : ""}
      </div>
      <div
        className={gap === undefined || gap === 16 ? "flex items-start justify-center gap-4" : "flex items-start justify-center"}
        style={gap === undefined || gap === 16 ? undefined : { gap }}
        aria-hidden
      >
        <Unit label="天" value={days} places={dayPlaces} reduced={reduced} speed={speed} fontSize={fontSize} />
        <Unit label="时" value={hours} places={2} reduced={reduced} speed={speed} fontSize={fontSize} />
        <Unit label="分" value={minutes} places={2} reduced={reduced} speed={speed} fontSize={fontSize} />
        <Unit label="秒" value={seconds} places={2} reduced={reduced} speed={speed} fontSize={fontSize} />
      </div>
      <p className="mt-4 text-center text-sm text-muted-foreground">
        {remaining === 0 ? "计时结束" : "倒计时进行中"}
      </p>
      {showConfetti ? (
        <span className="pointer-events-none absolute inset-x-0 top-1/2">
          {CONFETTI.map((piece) => (
            <motion.span
              key={`${piece.x}-${piece.color}`}
              className="absolute left-1/2 h-2 w-1.5 rounded-sm"
              style={{ background: piece.color }}
              initial={{ x: 0, y: 0, opacity: 1, rotate: 0 }}
              animate={{ x: piece.x, y: piece.y, opacity: 0, rotate: piece.rotate }}
              transition={
                duration === undefined || duration === 900
                  ? { duration: 0.9, ease: "easeOut" }
                  : { duration: duration / 1000, ease: "easeOut" }
              }
            />
          ))}
        </span>
      ) : null}
    </div>
  )
}

export { CountdownTimer }

"use client"

import * as React from "react"
import { motion } from "motion/react"

import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { cn } from "@/lib/utils"

export type CouponResult = { ok: true; label: string } | { ok: false; message: string }

export interface CouponInputProps {
  validate: (code: string) => Promise<CouponResult>
  className?: string
}

function CouponInput({ validate, className }: CouponInputProps) {
  const reduced = usePrefersReducedMotion()
  const [code, setCode] = React.useState("")
  const [status, setStatus] = React.useState<"idle" | "loading" | "success" | "error">("idle")
  const [message, setMessage] = React.useState("")
  const [label, setLabel] = React.useState("")
  const validateRef = React.useRef(validate)
  React.useEffect(() => {
    validateRef.current = validate
  }, [validate])

  const apply = async () => {
    const next = code.trim()
    if (!next || status === "loading") return
    setStatus("loading")
    setMessage("")
    try {
      const result = await validateRef.current(next)
      if (result.ok) {
        setStatus("success")
        setLabel(result.label)
        setMessage("")
      } else {
        setStatus("error")
        setMessage(result.message)
      }
    } catch {
      setStatus("error")
      setMessage("暂时无法核验这张券。")
    }
  }

  if (status === "success") {
    return (
      <div data-slot="coupon-input" className={cn("flex items-center gap-2", className)}>
        <span className="rounded-full bg-emerald-500/15 px-3 py-1 text-sm text-emerald-700">{label}</span>
        <button
          type="button"
          aria-label="移除优惠"
          className="text-sm text-muted-foreground"
          onClick={() => {
            setStatus("idle")
            setLabel("")
            setCode("")
          }}
        >
          移除
        </button>
      </div>
    )
  }

  return (
    <div data-slot="coupon-input" className={cn("grid gap-2", className)}>
      <motion.div animate={status === "error" && !reduced ? { x: [0, -8, 8, -5, 5, 0] } : { x: 0 }} transition={{ duration: 0.35 }} className="flex gap-2">
        <input
          aria-label="优惠码"
          value={code}
          onChange={(event) => {
            setCode(event.target.value)
            if (status === "error") setStatus("idle")
          }}
          className="h-10 flex-1 rounded-md border px-3"
          placeholder="输入优惠码"
        />
        <button type="button" className="rounded-md bg-primary px-3 text-sm text-primary-foreground disabled:opacity-60" disabled={status === "loading"} onClick={() => void apply()}>
          {status === "loading" ? "应用中" : "应用"}
        </button>
      </motion.div>
      {status === "error" ? <p role="alert" className="text-sm text-destructive">{message}</p> : null}
    </div>
  )
}

export { CouponInput }

"use client"

import * as React from "react"
import { motion } from "motion/react"

import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { cn } from "@/lib/utils"

export interface CoverflowItem {
  title: string
  tint: string
}

export interface CoverflowCarouselProps {
  items?: CoverflowItem[]
  className?: string
  /** 侧卡转角。不传或 42 仍是 42°。 */
  angle?: number
  /** 侧卡缩放倍率。不传或 1 时侧卡仍是 0.82。 */
  scale?: number
  /** 弹簧倍率。不传或 1 时刚度 260、阻尼 28。 */
  speed?: number
}

function pace(speed: number | undefined) {
  return speed === undefined || !Number.isFinite(speed) || speed <= 0 ? 1 : speed
}

const defaultItems: CoverflowItem[] = [
  { title: "Shaders", tint: "#7c3aed" },
  { title: "Globe", tint: "#22d3ee" },
  { title: "Sections", tint: "#f472b6" },
  { title: "Cursors", tint: "#f59e0b" },
  { title: "Bento", tint: "#34d399" },
]

function CoverflowCarousel({ items = defaultItems, className, angle, scale, speed }: CoverflowCarouselProps) {
  const reduced = usePrefersReducedMotion()
  const [index, setIndex] = React.useState(0)
  const last = Math.max(items.length - 1, 0)
  const turn = angle === undefined || angle === 42 ? 42 : angle
  const side = scale === undefined || scale === 1 ? 0.82 : 0.82 * scale
  const rate = pace(speed)

  const step = (delta: number) => setIndex((current) => Math.min(last, Math.max(0, current + delta)))

  return (
    <div className={cn("w-full", className)}>
      <div className="relative h-64 [perspective:1100px]">
        {items.map((item, itemIndex) => {
          const offset = itemIndex - index
          const hidden = Math.abs(offset) > 2
          return (
            <motion.button
              key={item.title}
              type="button"
              aria-current={offset === 0}
              onClick={() => setIndex(itemIndex)}
              animate={{
                x: `${offset * 58}%`,
                rotateY: reduced ? 0 : offset * -turn,
                scale: offset === 0 ? 1 : side,
                z: reduced ? 0 : -Math.abs(offset) * 80,
                opacity: hidden ? 0 : 1,
              }}
              transition={
                reduced
                  ? { duration: 0 }
                  : { type: "spring", stiffness: rate === 1 ? 260 : 260 * rate, damping: rate === 1 ? 28 : 28 * rate }
              }
              className="absolute top-4 left-1/2 h-52 w-40 -translate-x-1/2 rounded-2xl border border-white/20 text-white shadow-xl"
              style={{
                zIndex: 20 - Math.abs(offset),
                background: `linear-gradient(160deg, ${item.tint}, #09090b)`,
                transformStyle: "preserve-3d",
              }}
            >
              <span className="font-display text-xl">{item.title}</span>
            </motion.button>
          )
        })}
      </div>
      <div className="mt-2 flex justify-center gap-2">
        <button type="button" className="rounded-full border px-3 py-1 text-xs" onClick={() => step(-1)}>
          上一张
        </button>
        <button type="button" className="rounded-full border px-3 py-1 text-xs" onClick={() => step(1)}>
          下一张
        </button>
      </div>
    </div>
  )
}

export { CoverflowCarousel }

