                  onClick={() => {
                    onSelect?.(item.label)
                    setOpen(false)
                  }}
                >
                  <Icon className="size-4" />
                  {item.label}
                </button>
              )
            })}
          </div>
        ) : (
          <button type="button" aria-expanded={false} className="flex items-center gap-1.5 px-4 py-2" onClick={() => setOpen(true)}>
            <Plus className="size-4" />
            {label}
          </button>
        )}
      </motion.div>
    </div>
  )
}

