  }
  if (brand === "mastercard") {
    return (
      <svg viewBox="0 0 36 24" className="h-6 w-9" aria-hidden>
        <rect width="36" height="24" rx="4" fill="#0f172a" />
        <circle cx="15" cy="12" r="6" fill="#f97316" />
        <circle cx="21" cy="12" r="6" fill="#facc15" fillOpacity="0.9" />
      </svg>
