// Ported from SmoothUI (MIT) — https://github.com/educlopez/smoothui/blob/main/packages/smoothui/components/dither-chart/index.tsx


import { useAnimationActive } from "@/hooks/use-animation-active"
import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { cn } from "@/lib/utils"

import { useCallback, useEffect, useMemo, useRef } from "react";

/* -------------------------------------------------------------------------- */
/* Public types                                                               */
/* -------------------------------------------------------------------------- */

export const DITHER_CHART_VARIANTS = [
  "donut",
  "line",
  "bar",
  "stacked",
  "gauge",
  "funnel",
  "heatmap",
  "bubbles",
] as const;

export type DitherChartVariant = (typeof DITHER_CHART_VARIANTS)[number];

/** Bayer matrix order used to quantise every fill into a dot pattern. */
export type DitherChartMatrixOrder = 2 | 4 | 8;

export interface DitherChartPoint {
  /** Optional label, used only by the screen-reader text alternative. */
  label?: string;
  /** Numeric value of the point. */
  value: number;
}

export interface DitherChartSeries {
  /** Overrides the palette colour for this series. */
  color?: string;
  /** Series name, used only by the screen-reader text alternative. */
  name?: string;
  /** Ordered data points of the series. */
  points: DitherChartPoint[];
}

export interface DitherChartProps {
  /** Draw the chart in on mount / when it scrolls into view. */
  animate?: boolean;
  /** Caption rendered under the chart. */
  caption?: string;
  className?: string;
  /**
   * Chart data. Every variant reads the same shape:
   * `donut`, `gauge`, `funnel` use the first series, `heatmap` maps one series
   * per row, the rest render every series.
   */
  data: DitherChartSeries[];
  /** CSS height in pixels. */
  height?: number;
  /** Accessible title rendered above the chart. */
  label?: string;
  /** Bayer matrix order. Larger matrices produce finer gradients. */
  matrix?: DitherChartMatrixOrder;
  /** Colours cycled per series (or per slice for `donut`). */
  palette?: string[];
  /** Size in CSS pixels of one dithered pixel. */
  pixelSize?: number;
  variant?: DitherChartVariant;
  /** CSS width in pixels. */
  width?: number;
}

/* -------------------------------------------------------------------------- */
/* Constants                                                                  */
/* -------------------------------------------------------------------------- */

const DEFAULT_WIDTH = 320;
const DEFAULT_HEIGHT = 180;
const DEFAULT_PIXEL_SIZE = 3;
const DEFAULT_MATRIX: DitherChartMatrixOrder = 4;
const DEFAULT_VARIANT: DitherChartVariant = "line";

const DRAW_IN_DURATION_MS = 900;
const BEZIER_ITERATIONS = 16;
const EASE_OUT_X1 = 0.23;
const EASE_OUT_Y1 = 1;
const EASE_OUT_X2 = 0.32;
const EASE_OUT_Y2 = 1;

const ALPHA_MAX = 255;
const RGBA_STRIDE = 4;
const ALPHA_OFFSET = 3;
const QUADRANT_OFFSETS = [
  [0, 2],
  [3, 1],
];

/** Alpha ramp that gives each series a distinct dither density. */
const TONE_RAMP = [1, 0.68, 0.46, 0.3, 0.2];
const AREA_TONE_FACTOR = 0.45;
const TRACK_TONE = 0.16;
const HEATMAP_MIN_TONE = 0.08;

const EDGE_INSET = 1;
const LINE_WIDTH = 1;
const BAR_FILL_RATIO = 0.72;
const FUNNEL_ROW_GAP = 1;
const DONUT_INNER_RATIO = 0.55;
const GAUGE_INNER_RATIO = 0.62;
const GAUGE_START_ANGLE = Math.PI * 0.75;
const GAUGE_SWEEP = Math.PI * 1.5;
const GAUGE_MAX_VALUE = 100;
const BUBBLE_MIN_RADIUS = 1;
const BUBBLE_MAX_RATIO = 0.16;
const FULL_TURN = Math.PI * 2;
const QUARTER_TURN = Math.PI / 2;
const HALF = 0.5;
const MIN_DIMENSION = 1;

/* -------------------------------------------------------------------------- */
/* Bayer matrices                                                             */
/* -------------------------------------------------------------------------- */

const buildBayer = (order: number): number[][] => {
  if (order <= 1) {
    return [[0]];
  }
  const half = buildBayer(order / 2);
  const halfSize = half.length;
  const matrix: number[][] = [];
  for (let y = 0; y < order; y++) {
    const row: number[] = [];
    for (let x = 0; x < order; x++) {
      const quadrantY = y < halfSize ? 0 : 1;
      const quadrantX = x < halfSize ? 0 : 1;
      const cell = half[y % halfSize]?.[x % halfSize] ?? 0;
      const offset = QUADRANT_OFFSETS[quadrantY]?.[quadrantX] ?? 0;
      row.push(cell * QUADRANT_OFFSETS.length ** 2 + offset);
    }
    matrix.push(row);
  }
  return matrix;
};

const BAYER_MATRICES: Record<DitherChartMatrixOrder, number[][]> = {
  2: buildBayer(2),
  4: buildBayer(4),
  8: buildBayer(8),
};

/* -------------------------------------------------------------------------- */
/* Easing                                                                     */
/* -------------------------------------------------------------------------- */

const bezierAxis = (t: number, a: number, b: number): number => {
  const inverse = 1 - t;
  return 3 * inverse * inverse * t * a + 3 * inverse * t * t * b + t * t * t;
};

/** Solves `cubic-bezier(.23, 1, .32, 1)` for a linear progress value. */
const easeOut = (progress: number): number => {
  let low = 0;
  let high = 1;
  let t = progress;
  for (let i = 0; i < BEZIER_ITERATIONS; i++) {
    if (bezierAxis(t, EASE_OUT_X1, EASE_OUT_X2) < progress) {
      low = t;
    } else {
      high = t;
    }
    t = (low + high) * HALF;
  }
  return bezierAxis(t, EASE_OUT_Y1, EASE_OUT_Y2);
};

/* -------------------------------------------------------------------------- */
/* Drawing helpers                                                            */
/* -------------------------------------------------------------------------- */

interface DrawContext {
  colorAt: (index: number) => string;
  ctx: CanvasRenderingContext2D;
  height: number;
  progress: number;
  series: DitherChartSeries[];
  toneAt: (index: number) => number;
  width: number;
}

const seriesMax = (series: DitherChartSeries[]): number => {
  let max = 0;
  for (const item of series) {
    for (const point of item.points) {
      if (point.value > max) {
        max = point.value;
      }
    }
  }
  return max || 1;
};

const maxPointCount = (series: DitherChartSeries[]): number => {
  let count = 0;
  for (const item of series) {
    if (item.points.length > count) {
      count = item.points.length;
    }
  }
  return count || 1;
};

const sumPoints = (points: DitherChartPoint[]): number => {
  let total = 0;
  for (const point of points) {
    total += point.value;
  }
  return total || 1;
};

const ringSegment = (
  ctx: CanvasRenderingContext2D,
  cx: number,
  cy: number,
  outer: number,
  inner: number,
  start: number,
  end: number
) => {
  ctx.beginPath();
  ctx.arc(cx, cy, outer, start, end);
  ctx.arc(cx, cy, inner, end, start, true);
  ctx.closePath();
  ctx.fill();
};

const drawLine = ({
  colorAt,
  ctx,
  height,
  progress,
  series,
  toneAt,
  width,
}: DrawContext) => {
  const max = seriesMax(series);
  const baseline = height - EDGE_INSET;
  const usable = baseline - EDGE_INSET;
  for (let i = 0; i < series.length; i++) {
    const item = series[i];
    if (!item || item.points.length < 2) {
      continue;
    }
    const { points } = item;
    const step = (width - EDGE_INSET * 2) / (points.length - 1);
    const coords = points.map((point, index) => ({
      x: EDGE_INSET + step * index,
      y: baseline - (point.value / max) * usable * progress,
    }));
    const color = item.color ?? colorAt(i);
    const lastX = EDGE_INSET + step * (points.length - 1);
    const origin = coords[0];
    if (!origin) {
      continue;
    }

    ctx.fillStyle = color;
    ctx.globalAlpha = toneAt(i) * AREA_TONE_FACTOR;
    ctx.beginPath();
    ctx.moveTo(origin.x, baseline);
    for (const coord of coords) {
      ctx.lineTo(coord.x, coord.y);
    }
    ctx.lineTo(lastX, baseline);
    ctx.closePath();
    ctx.fill();

    ctx.strokeStyle = color;
    ctx.globalAlpha = toneAt(i);
    ctx.lineWidth = LINE_WIDTH;
    ctx.beginPath();
    ctx.moveTo(origin.x, origin.y);
    for (const coord of coords) {
      ctx.lineTo(coord.x, coord.y);
    }
    ctx.stroke();
  }
};

const drawBar = ({
  colorAt,
  ctx,
  height,
  progress,
  series,
  toneAt,
  width,
}: DrawContext) => {
  const max = seriesMax(series);
  const groups = maxPointCount(series);
  const baseline = height - EDGE_INSET;
  const usable = baseline - EDGE_INSET;
  const slot = (width - EDGE_INSET * 2) / groups;
  const barWidth = Math.max(
    MIN_DIMENSION,
    (slot * BAR_FILL_RATIO) / series.length
  );
  const groupWidth = barWidth * series.length;

  for (let group = 0; group < groups; group++) {
    const slotStart = EDGE_INSET + slot * group + (slot - groupWidth) * HALF;
    for (let i = 0; i < series.length; i++) {
      const item = series[i];
      if (!item) {
        continue;
      }
      const value = item.points[group]?.value ?? 0;
      const barHeight = (value / max) * usable * progress;
      ctx.fillStyle = item.color ?? colorAt(i);
      ctx.globalAlpha = toneAt(i);
      ctx.fillRect(
        slotStart + barWidth * i,
        baseline - barHeight,
        barWidth,
        barHeight
      );
    }
  }
};

const drawStacked = ({
  colorAt,
  ctx,
  height,
  progress,
  series,
  toneAt,
  width,
}: DrawContext) => {
  const groups = maxPointCount(series);
  let maxTotal = 1;
  for (let group = 0; group < groups; group++) {
    let total = 0;
    for (const item of series) {
      total += item.points[group]?.value ?? 0;
    }
    if (total > maxTotal) {
      maxTotal = total;
    }
  }

  const baseline = height - EDGE_INSET;
  const usable = baseline - EDGE_INSET;
  const slot = (width - EDGE_INSET * 2) / groups;
  const barWidth = Math.max(MIN_DIMENSION, slot * BAR_FILL_RATIO);

  for (let group = 0; group < groups; group++) {
    const x = EDGE_INSET + slot * group + (slot - barWidth) * HALF;
    let stacked = 0;
    for (let i = 0; i < series.length; i++) {
      const item = series[i];
      if (!item) {
        continue;
      }
      const value = item.points[group]?.value ?? 0;
      const segment = (value / maxTotal) * usable * progress;
      ctx.fillStyle = item.color ?? colorAt(i);
      ctx.globalAlpha = toneAt(i);
      ctx.fillRect(x, baseline - stacked - segment, barWidth, segment);
      stacked += segment;
    }
  }
};

const drawDonut = ({
  colorAt,
  ctx,
  height,
  progress,
  series,
  toneAt,
  width,
}: DrawContext) => {
  const points = series[0]?.points ?? [];
  if (points.length === 0) {
    return;
  }
  const total = sumPoints(points);
  const cx = width * HALF;
  const cy = height * HALF;
  const outer = Math.min(width, height) * HALF - EDGE_INSET;
  const inner = outer * DONUT_INNER_RATIO;
  let angle = -QUARTER_TURN;

  for (let i = 0; i < points.length; i++) {
    const point = points[i];
    if (!point) {
      continue;
    }
    const sweep = (point.value / total) * FULL_TURN * progress;
    ctx.fillStyle = colorAt(i);
    ctx.globalAlpha = toneAt(i);
    ringSegment(ctx, cx, cy, outer, inner, angle, angle + sweep);
    angle += sweep;
  }
};

const drawGauge = ({
  colorAt,
  ctx,
  height,
  progress,
  series,
  toneAt,
  width,
}: DrawContext) => {
  const value = series[0]?.points[0]?.value ?? 0;
  const ratio = Math.min(1, Math.max(0, value / GAUGE_MAX_VALUE));
  const cx = width * HALF;
  const cy = height * HALF;
  const outer = Math.min(width, height) * HALF - EDGE_INSET;
  const inner = outer * GAUGE_INNER_RATIO;

  ctx.fillStyle = colorAt(0);
  ctx.globalAlpha = TRACK_TONE;
  ringSegment(
    ctx,
    cx,
    cy,
    outer,
    inner,
    GAUGE_START_ANGLE,
    GAUGE_START_ANGLE + GAUGE_SWEEP
  );

  ctx.globalAlpha = toneAt(0);
  ringSegment(
    ctx,
    cx,
    cy,
    outer,
    inner,
    GAUGE_START_ANGLE,
    GAUGE_START_ANGLE + GAUGE_SWEEP * ratio * progress
  );
};

const drawFunnel = ({
  colorAt,
  ctx,
  height,
  progress,
  series,
  toneAt,
  width,
}: DrawContext) => {
  const points = series[0]?.points ?? [];
  if (points.length === 0) {
    return;
  }
  const max = seriesMax(series);
  const rowHeight = (height - EDGE_INSET * 2) / points.length;
  const usable = width - EDGE_INSET * 2;

  for (let i = 0; i < points.length; i++) {
    const point = points[i];
    if (!point) {
      continue;
    }
    const rowWidth = (point.value / max) * usable * progress;
    ctx.fillStyle = colorAt(i);
    ctx.globalAlpha = toneAt(i);
    ctx.fillRect(
      (width - rowWidth) * HALF,
      EDGE_INSET + rowHeight * i,
      rowWidth,
      Math.max(MIN_DIMENSION, rowHeight - FUNNEL_ROW_GAP)
    );
  }
};

const drawHeatmap = ({
  colorAt,
  ctx,
  height,
  progress,
  series,
  width,
}: DrawContext) => {
  const max = seriesMax(series);
  const columns = maxPointCount(series);
  const cellWidth = (width - EDGE_INSET * 2) / columns;
  const cellHeight = (height - EDGE_INSET * 2) / series.length;
  ctx.fillStyle = colorAt(0);

  for (let row = 0; row < series.length; row++) {
    const item = series[row];
    if (!item) {
      continue;
    }
    for (let column = 0; column < columns; column++) {
      const value = item.points[column]?.value ?? 0;
      const intensity =
        HEATMAP_MIN_TONE + (value / max) * (1 - HEATMAP_MIN_TONE);
      ctx.globalAlpha = intensity * progress;
      ctx.fillRect(
        EDGE_INSET + cellWidth * column,
        EDGE_INSET + cellHeight * row,
        cellWidth,
        cellHeight
      );
    }
  }
};

const drawBubbles = ({
  colorAt,
  ctx,
  height,
  progress,
  series,
  toneAt,
  width,
}: DrawContext) => {
  const max = seriesMax(series);
  const columns = maxPointCount(series);
  const baseline = height - EDGE_INSET;
  const usable = baseline - EDGE_INSET;
  const step = (width - EDGE_INSET * 2) / columns;
  const maxRadius = Math.min(width, height) * BUBBLE_MAX_RATIO;

  for (let i = 0; i < series.length; i++) {
    const item = series[i];
    if (!item) {
      continue;
    }
    ctx.fillStyle = item.color ?? colorAt(i);
    ctx.globalAlpha = toneAt(i);
    const { points } = item;
    for (let j = 0; j < points.length; j++) {
      const point = points[j];
      if (!point) {
        continue;
      }
      const ratio = point.value / max;
      const radius =
        (BUBBLE_MIN_RADIUS + ratio * (maxRadius - BUBBLE_MIN_RADIUS)) *
        progress;
      if (radius <= 0) {
        continue;
      }
      ctx.beginPath();
      ctx.arc(
        EDGE_INSET + step * (j + HALF),
        baseline - ratio * usable,
        radius,
        0,
        FULL_TURN
      );
      ctx.fill();
    }
  }
};

const VARIANT_PAINTERS: Record<
  DitherChartVariant,
  (context: DrawContext) => void
> = {
  bar: drawBar,
  bubbles: drawBubbles,
  donut: drawDonut,
  funnel: drawFunnel,
  gauge: drawGauge,
  heatmap: drawHeatmap,
  line: drawLine,
  stacked: drawStacked,
};

/** Quantises every pixel's alpha through the Bayer matrix. */
const applyDither = (
  ctx: CanvasRenderingContext2D,
  width: number,
  height: number,
  order: DitherChartMatrixOrder
) => {
  const image = ctx.getImageData(0, 0, width, height);
  const pixels = image.data;
  const matrix = BAYER_MATRICES[order];
  const levels = order * order;

  for (let y = 0; y < height; y++) {
    const row = matrix[y % order];
    if (!row) {
      continue;
    }
    for (let x = 0; x < width; x++) {
      const index = (y * width + x) * RGBA_STRIDE + ALPHA_OFFSET;
      const sample = pixels[index] ?? 0;
      const coverage = sample / ALPHA_MAX;
      const threshold = ((row[x % order] ?? 0) + HALF) / levels;
      pixels[index] = coverage > threshold ? ALPHA_MAX : 0;
    }
  }

  ctx.putImageData(image, 0, 0);
};

const resolvePalette = (element: HTMLElement, palette?: string[]): string[] => {
  if (palette && palette.length > 0) {
    return palette;
  }
  const styles = getComputedStyle(element);
  const current = styles.color || "#000000";
  const brand = styles.getPropertyValue("--color-brand").trim();
  return brand ? [brand, current] : [current];
};

/* -------------------------------------------------------------------------- */
/* Component                                                                  */
/* -------------------------------------------------------------------------- */

const DitherChart = ({
  animate = true,
  caption,
  className,
  data,
  height = DEFAULT_HEIGHT,
  label,
  matrix = DEFAULT_MATRIX,
  palette,
  pixelSize = DEFAULT_PIXEL_SIZE,
  variant = DEFAULT_VARIANT,
  width = DEFAULT_WIDTH,
}: DitherChartProps) => {
  const hostRef = useRef<HTMLElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const bufferRef = useRef<HTMLCanvasElement | null>(null);
  const shouldReduceMotion = usePrefersReducedMotion();
  const motionOn = useAnimationActive(hostRef);
  const motionOnRef = useRef(motionOn);
  const controlsRef = useRef<{ start: () => void; stop: () => void } | null>(null);

  useEffect(() => {
    motionOnRef.current = motionOn;
    if (motionOn) {
      controlsRef.current?.start();
    } else {
      controlsRef.current?.stop();
    }
  }, [motionOn]);

  const draw = useCallback(
    (progress: number) => {
      const canvas = canvasRef.current;
      if (!canvas || data.length === 0) {
        return;
      }

      const buffer = bufferRef.current ?? document.createElement("canvas");
      bufferRef.current = buffer;

      const lowWidth = Math.max(MIN_DIMENSION, Math.round(width / pixelSize));
      const lowHeight = Math.max(MIN_DIMENSION, Math.round(height / pixelSize));
      buffer.width = lowWidth;
      buffer.height = lowHeight;

      const bufferCtx = buffer.getContext("2d", { willReadFrequently: true });
      if (!bufferCtx) {
        return;
      }
      bufferCtx.clearRect(0, 0, lowWidth, lowHeight);
      bufferCtx.globalAlpha = 1;

      const colors = resolvePalette(canvas, palette);
      const painter = VARIANT_PAINTERS[variant];
      painter({
        colorAt: (index: number) => colors[index % colors.length] ?? "#000000",
        ctx: bufferCtx,
        height: lowHeight,
        progress,
        series: data,
        toneAt: (index: number) => TONE_RAMP[index % TONE_RAMP.length] ?? 1,
        width: lowWidth,
      });
      bufferCtx.globalAlpha = 1;
      applyDither(bufferCtx, lowWidth, lowHeight, matrix);

      const ratio = window.devicePixelRatio || 1;
      canvas.width = Math.round(width * ratio);
      canvas.height = Math.round(height * ratio);
      const ctx = canvas.getContext("2d");
      if (!ctx) {
        return;
      }
      ctx.imageSmoothingEnabled = false;
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.drawImage(
        buffer,
        0,
        0,
        lowWidth,
        lowHeight,
        0,
        0,
        canvas.width,
        canvas.height
      );
    },
    [data, height, matrix, palette, pixelSize, variant, width]
  );

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) {
      return;
    }

    if (!animate || shouldReduceMotion) {
      draw(1);
      return;
    }

    let frame = 0;
    let elapsed = 0;
    let last = 0;
    let running = false;
    draw(0);

    const tick = (time: number) => {
      if (last === 0) {
        last = time;
      }
      elapsed += time - last;
      last = time;
      const progress = Math.min(1, elapsed / DRAW_IN_DURATION_MS);
      draw(easeOut(progress));
      if (progress < 1) {
        frame = requestAnimationFrame(tick);
      } else {
        running = false;
      }
    };

    const start = () => {
      if (running || elapsed >= DRAW_IN_DURATION_MS) {
        return;
      }
      running = true;
      last = 0;
      frame = requestAnimationFrame(tick);
    };

    const stop = () => {
      if (!running) {
        return;
      }
      cancelAnimationFrame(frame);
      running = false;
    };

    controlsRef.current = { start, stop };
    if (motionOnRef.current) {
      start();
    }

    return () => {
      controlsRef.current = null;
      cancelAnimationFrame(frame);
    };
  }, [animate, draw, shouldReduceMotion]);

  const description = useMemo(() => {
    const summaries = data.map((item, index) => {
      const name = item.name ?? `Series ${index + 1}`;
      const values = item.points
        .map(
          (point, pointIndex) =>
            `${point.label ?? `Point ${pointIndex + 1}`}: ${point.value}`
        )
        .join(", ");
      return `${name} — ${values}`;
    });
    return `${label ?? "Dithered chart"}, ${variant} variant. ${summaries.join(". ")}.`;
  }, [data, label, variant]);

  return (
    <figure
      className={cn("inline-flex flex-col gap-2 text-foreground", className)}
      data-reduced={shouldReduceMotion ? "true" : "false"}
      data-slot="dither-chart"
      ref={hostRef}
    >
      {label ? (
        <span className="font-medium text-foreground text-sm">{label}</span>
      ) : null}
      <canvas
        aria-hidden="true"
        className="block"
        height={height}
        ref={canvasRef}
        style={{ height: `${height}px`, width: `${width}px` }}
        tabIndex={-1}
        width={width}
      />
      <span className="sr-only">{description}</span>
      {caption ? (
        <figcaption className="text-muted-foreground text-xs">
          {caption}
        </figcaption>
      ) : null}
    </figure>
  );
};

export { DitherChart }

"use client"

import * as React from "react"

import { useAnimationActive } from "@/hooks/use-animation-active"
import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { cn } from "@/lib/utils"

export interface DitherGradientProps {
  className?: string
  colors?: string[]
  speed?: number
  count?: number
  intensity?: number
}

const DITHER_COLORS = ["#1a0d47", "#f57338", "#33bfd1"]

const VERT = `
attribute vec2 a_pos;
void main(){ gl_Position = vec4(a_pos, 0.0, 1.0); }
`

const FRAG = `
precision mediump float;
uniform vec2 u_res;
uniform float u_time;
uniform float u_speed;
uniform float u_count;
uniform float u_intensity;
uniform vec3 u_a;
uniform vec3 u_b;
uniform vec3 u_c;
float bayer(vec2 pixel) {
  int x = int(mod(pixel.x, 4.0));
  int y = int(mod(pixel.y, 4.0));
  int index = y * 4 + x;
  float value = 0.0;
  if (index == 0) value = 0.0;
  else if (index == 1) value = 8.0;
  else if (index == 2) value = 2.0;
  else if (index == 3) value = 10.0;
  else if (index == 4) value = 12.0;
  else if (index == 5) value = 4.0;
  else if (index == 6) value = 14.0;
  else if (index == 7) value = 6.0;
  else if (index == 8) value = 3.0;
  else if (index == 9) value = 11.0;
  else if (index == 10) value = 1.0;
  else if (index == 11) value = 9.0;
  else if (index == 12) value = 15.0;
  else if (index == 13) value = 7.0;
  else if (index == 14) value = 13.0;
  else value = 5.0;
  return value / 16.0;
}
void main() {
  vec2 uv = gl_FragCoord.xy / u_res;
  float shift = u_time * 0.15 * u_speed;
  float t = uv.x * 0.75 + uv.y * 0.35 + sin(uv.y * 6.0 + shift) * 0.08;
  vec3 color = mix(u_a, u_b, clamp(t, 0.0, 1.0));
  color = mix(color, u_c, clamp(uv.y - 0.45 + sin(shift), 0.0, 1.0) * 0.55);
  float levels = u_count;
  float threshold = (bayer(gl_FragCoord.xy) - 0.5) * u_intensity;
  color = floor(color * levels + threshold + 0.5) / levels;
  gl_FragColor = vec4(color, 1.0);
}
`

function hexToRgb(hex: string, fallback: [number, number, number]): [number, number, number] {
  const raw = hex.trim().replace(/^#/, "")
  const digits = raw.length === 3 ? [...raw].map((char) => `${char}${char}`).join("") : raw
  if (!/^[0-9a-fA-F]{6}$/.test(digits)) return fallback
  const value = Number.parseInt(digits, 16)
  return [((value >> 16) & 255) / 255, ((value >> 8) & 255) / 255, (value & 255) / 255]
}

function compile(gl: WebGLRenderingContext, type: number, source: string) {
  const shader = gl.createShader(type)
  if (!shader) return null
  gl.shaderSource(shader, source)
  gl.compileShader(shader)
  if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
    gl.deleteShader(shader)
    return null
  }
  return shader
}

function playbackRate(speed: number) {
  return Number.isFinite(speed) && speed > 0 ? speed : 1
}

function DitherGradient({
  className,
  colors = DITHER_COLORS,
  speed = 1,
  count = 5,
  intensity = 1,
}: DitherGradientProps) {
  const reduced = usePrefersReducedMotion()
  const canvasRef = React.useRef<HTMLCanvasElement>(null)
  const active = useAnimationActive(canvasRef)
  const [fallback, setFallback] = React.useState(false)
  const live = React.useRef({ colors, speed: playbackRate(speed), count, intensity })

  React.useEffect(() => {
    live.current = { colors, speed: playbackRate(speed), count, intensity }
  }, [colors, speed, count, intensity])
  const stillKey = reduced ? `${colors.join("|")}|${count}|${intensity}|${speed}` : ""

  React.useEffect(() => {
    const canvas = canvasRef.current
    if (!canvas || !active) return
    const gl = canvas.getContext("webgl")
    if (!gl) {
      setFallback(true)
      return
    }
    const vert = compile(gl, gl.VERTEX_SHADER, VERT)
    const frag = compile(gl, gl.FRAGMENT_SHADER, FRAG)
    if (!vert || !frag) {
      setFallback(true)
      return
    }
    const program = gl.createProgram()
    if (!program) {
      setFallback(true)
      return
    }
    gl.attachShader(program, vert)
    gl.attachShader(program, frag)
    gl.linkProgram(program)
    if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
      setFallback(true)
      return
    }
    const buffer = gl.createBuffer()
    gl.bindBuffer(gl.ARRAY_BUFFER, buffer)
    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 1, -1, -1, 1, 1, 1]), gl.STATIC_DRAW)
    const position = gl.getAttribLocation(program, "a_pos")
    gl.enableVertexAttribArray(position)
    gl.vertexAttribPointer(position, 2, gl.FLOAT, false, 0, 0)
    const resolution = gl.getUniformLocation(program, "u_res")
    const time = gl.getUniformLocation(program, "u_time")
    const speedLoc = gl.getUniformLocation(program, "u_speed")
    const countLoc = gl.getUniformLocation(program, "u_count")
    const intensityLoc = gl.getUniformLocation(program, "u_intensity")
    const colorA = gl.getUniformLocation(program, "u_a")
    const colorB = gl.getUniformLocation(program, "u_b")
    const colorC = gl.getUniformLocation(program, "u_c")
    let frame = 0
    const started = performance.now()
    const draw = (now: number) => {
      const spec = live.current
      const a = hexToRgb(spec.colors[0] ?? "", [0.1, 0.05, 0.28])
      const b = hexToRgb(spec.colors[1] ?? "", [0.96, 0.45, 0.22])
      const c = hexToRgb(spec.colors[2] ?? "", [0.2, 0.75, 0.82])
      const rect = canvas.getBoundingClientRect()
      const dpr = Math.min(window.devicePixelRatio || 1, 2)
      const width = Math.max(1, Math.floor(rect.width * dpr))
      const height = Math.max(1, Math.floor(rect.height * dpr))
      if (canvas.width !== width || canvas.height !== height) {
        canvas.width = width
        canvas.height = height
      }
      gl.viewport(0, 0, width, height)
      gl.useProgram(program)
      gl.uniform2f(resolution, width, height)
      gl.uniform1f(time, reduced ? 0 : (now - started) / 1000)
      gl.uniform1f(speedLoc, spec.speed)
      gl.uniform1f(countLoc, spec.count)
      gl.uniform1f(intensityLoc, spec.intensity)
      gl.uniform3f(colorA, a[0], a[1], a[2])
      gl.uniform3f(colorB, b[0], b[1], b[2])
      gl.uniform3f(colorC, c[0], c[1], c[2])
      gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4)
      if (!reduced) frame = window.requestAnimationFrame(draw)
    }
    frame = window.requestAnimationFrame(draw)
    return () => window.cancelAnimationFrame(frame)
  }, [active, reduced, stillKey])

  if (fallback) {
    return (
      <div
        className={cn("h-64 rounded-2xl border", className)}
        style={{
          backgroundImage:
            "linear-gradient(120deg, #2e1065, #ea580c 55%, #22d3ee), radial-gradient(circle, #09090b 1px, transparent 1.4px)",
          backgroundSize: "auto, 4px 4px",
        }}
      />
    )
  }

  return <canvas ref={canvasRef} className={cn("h-64 w-full rounded-2xl border bg-zinc-950", className)} />
}

