// Ported from ns-ui (MIT, (c) 2026 Nikolas Sapalidis) — https://github.com/nikolas-sapa/ns-ui/blob/main/registry/core/due-slip/component.tsx

import {
  useEffect,
  useRef,
  useState,
} from "react";

import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion";
import { useAnimationActive } from "@/hooks/use-animation-active";
import type { RefObject } from "react";

type NsJob = { token: number; cb: (now: number) => void; raf: number };
type NsApi = {
  requestFrame: (cb: (now: number) => void) => number;
  cancelFrame: (id: number | null | undefined) => void;
  motionNow: () => number;
};

const nsApi: NsApi = {
  requestFrame: (cb) => requestAnimationFrame((t) => cb(t)),
  cancelFrame: (id) => {
    if (id) cancelAnimationFrame(id);
  },
  motionNow: () => performance.now(),
};

function nsRequestFrame(cb: (now: number) => void) {
  return nsApi.requestFrame(cb);
}
function nsCancelFrame(id: number | null | undefined) {
  nsApi.cancelFrame(id);
}
function nsMotionNow() {
  return nsApi.motionNow();
}

function useNsBind(rootRef: RefObject<HTMLElement | null>) {
  const reduced = usePrefersReducedMotion();
  const live = useAnimationActive(rootRef as RefObject<Element | null>);
  const liveRef = useRef(live);
  const reducedRef = useRef(reduced);
  const holdRef = useRef(0);
  const offsetRef = useRef(0);
  const jobsRef = useRef(new Map<number, NsJob>());
  const seqRef = useRef(1);

  const motionNow = () => {
    const raw = performance.now();
    if (!liveRef.current) {
      if (holdRef.current === 0) holdRef.current = raw;
      return holdRef.current - offsetRef.current;
    }
    if (holdRef.current !== 0) {
      offsetRef.current += raw - holdRef.current;
      holdRef.current = 0;
    }
    return raw - offsetRef.current;
  };

  const requestFrame = (cb: (now: number) => void) => {
    const token = seqRef.current++;
    const job: NsJob = { token, cb, raf: 0 };
    jobsRef.current.set(token, job);
    const kick = () => {
      if (!liveRef.current) {
        if (holdRef.current === 0) holdRef.current = performance.now();
        job.raf = 0;
        return;
      }
      job.raf = requestAnimationFrame(() => {
        if (!jobsRef.current.has(token)) return;
        if (!liveRef.current) {
          job.raf = 0;
          if (holdRef.current === 0) holdRef.current = performance.now();
          return;
        }
        jobsRef.current.delete(token);
        cb(motionNow());
      });
    };
    kick();
    return token;
  };

  const cancelFrame = (id: number | null | undefined) => {
    if (id == null) return;
    const job = jobsRef.current.get(id);
    if (!job) return;
    if (job.raf) cancelAnimationFrame(job.raf);
    jobsRef.current.delete(id);
  };

  useEffect(() => {
    liveRef.current = live;
    reducedRef.current = reduced;
  }, [live, reduced]);

  useEffect(() => {
    nsApi.requestFrame = requestFrame;
    nsApi.cancelFrame = cancelFrame;
    nsApi.motionNow = motionNow;
  });

  useEffect(() => {
    if (!live) return;
    for (const job of [...jobsRef.current.values()]) {
      if (job.raf) continue;
      const { token, cb } = job;
      job.raf = requestAnimationFrame(() => {
        if (!jobsRef.current.has(token)) return;
        if (!liveRef.current) {
          job.raf = 0;
          return;
        }
        jobsRef.current.delete(token);
        cb(motionNow());
      });
    }
  }, [live]);

  useEffect(
    () => () => {
      for (const job of jobsRef.current.values()) {
        if (job.raf) cancelAnimationFrame(job.raf);
      }
      jobsRef.current.clear();
    },
    [],
  );

  return { reduced, live, motionOn: live && !reduced, requestFrame, cancelFrame, motionNow };
}

function NsPause({ slot }: { slot: string }) {
  return (
    <style>{`[data-slot="${slot}"][data-motion="off"],[data-slot="${slot}"][data-motion="off"] *{animation-play-state:paused !important}`}</style>
  );
}

// ---------------------------------------------------------------------------
// DueSlip — a library date-due card for a shared doc: every collaborator who
// opens it gets their initials and an HH:MM stamp pressed into the next free
// ruled row. Row POSITION is reading order — there is no hover state that
// carries meaning, unlike an avatar-stack "seen by" pile, which only reveals
// who's there via pointer interrogation and collapses to a generic "+N" the
// moment the record gets interesting. Here every reader is a permanent line
// item; the only thing that ever collapses is the *visual* overflow past the
// ruled area, and even then a real integer count sits on the card behind it.
//
// One governing scalar, arrival index (a reader's position in the readers
// array), drives every derived visual: row position (plain document order),
// ink alpha (1.0 easing down to a 0.55 floor by the 14th row, so a long
// ledger's tail stays legible instead of vanishing), while rotation is seeded
// independently from a hash of the reader's id (not the index) so re-sorting
// or filtering the same person never reshuffles their tilt. The newest
// arrival plays a 320ms ease-out-expo press-in (scale 1.06 -> 1.0) on just
// the ink chip; the row's static +/-2.5deg tilt is not itself motion and
// stays under reduced-motion, only the spring is stripped.
//
// Fully controlled: `readers` is the only data prop, in arrival order. The
// component holds no ledger state of its own — only transient UI state (which
// ids are mid press-animation, whether the full-name view is open, the live
// announcement). Pure DOM/SVG/CSS, no canvas; every color is one of
// --background / --foreground / --ns-muted / --border / --ns-accent, and
// --ns-accent appears nowhere but the expand control's focus ring.
// ---------------------------------------------------------------------------

export interface DueSlipReader {
  /** stable identifier; also seeds this reader's stamp rotation */
  id: string;
  /** full name, shown once the slip is expanded */
  name: string;
  /** 1-3 char initials; derived from `name` when omitted */
  initials?: string;
  /** when this reader first opened the doc */
  readAt: number | Date;
}

export interface DueSlipProps {
  /** readers in arrival order — index 0 opened first */
  readers: DueSlipReader[];
  /** accessible name for the ledger list, also shown as the card title. @default "Read receipts" */
  label?: string;
  /** rows visible in the ruled card before overflow flips to a second card behind. @default 6 */
  visibleRows?: number;
  /** row count over which ink alpha ramps from 1.0 down to its 0.55 floor. @default 14 */
  alphaFloorRow?: number;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

type Vars = React.CSSProperties & Record<`--${string}`, string | number>;

const PRESS_MS = 320;
const ALPHA_FLOOR = 0.55;

function toDate(v: number | Date): Date {
  return v instanceof Date ? v : new Date(v);
}

function formatHHMM(d: Date): string {
  const hh = String(d.getHours()).padStart(2, "0");
  const mm = String(d.getMinutes()).padStart(2, "0");
  return `${hh}:${mm}`;
}

function initialsOf(name: string): string {
  const parts = name.trim().split(/\s+/).filter(Boolean);
  const first = parts[0];
  const lastName = parts[parts.length - 1];
  if (!first || !lastName) return "?";
  if (parts.length === 1) return first.slice(0, 2).toUpperCase();
  return `${first[0] ?? ""}${lastName[0] ?? ""}`.toUpperCase();
}

// Deterministic tilt from the reader's id, not their row index, so the same
// person keeps the same stamp angle no matter where they land in the list.
function stampRotate(id: string): number {
  let h = 0;
  for (let i = 0; i < id.length; i++) h = (h * 31 + id.charCodeAt(i)) | 0;
  const s = Math.sin(h) * 43758.5453;
  const frac = s - Math.floor(s);
  return (frac - 0.5) * 5; // -2.5..2.5deg
}

function inkAlpha(index: number, floorRow: number): number {
  if (floorRow <= 1) return ALPHA_FLOOR;
  const t = Math.min(1, Math.max(0, index) / (floorRow - 1));
  return 1 - t * (1 - ALPHA_FLOOR);
}

function useReducedMotion() {
  return usePrefersReducedMotion();
}

function ChevronGlyph({ expanded }: { expanded: boolean }) {
  return (
    <svg
      viewBox="0 0 16 16"
      width="11"
      height="11"
      fill="none"
      aria-hidden="true"
      className="ns-due-chevron"
      data-expanded={expanded}
    >
      <path d="M5 3.5 10 8l-5 4.5" stroke="currentColor" strokeWidth="1.3" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  );
}

export function DueSlip({
  readers,
  label = "Read receipts",
  visibleRows = 6,
  alphaFloorRow = 14,
  className = "",
}: DueSlipProps) {
  const nsRootRef = useRef<HTMLDivElement | null>(null);
  const nsMotion = useNsBind(nsRootRef as RefObject<HTMLElement | null>);
  const nsRequestFrame = nsMotion.requestFrame;
  const nsCancelFrame = nsMotion.cancelFrame;
  const nsMotionNow = nsMotion.motionNow;

  const reducedMotion = useReducedMotion();
  const [expanded, setExpanded] = useState(false);
  const [arrivingIds, setArrivingIds] = useState<Set<string>>(() => new Set());
  const [liveMsg, setLiveMsg] = useState("");
  const prevIdsRef = useRef<Set<string> | null>(null);

  // New arrivals only: the first render seeds prevIdsRef without animating
  // (those rows are history, not something that just happened), every render
  // after that diffs against the previous id set.
  useEffect(() => {
    const prev = prevIdsRef.current;
    const nowIds = new Set(readers.map((r) => r.id));
    if (prev) {
      const newcomers = readers.filter((r) => !prev.has(r.id));
      if (newcomers.length > 0) {
        const last = newcomers[newcomers.length - 1];
        if (last) setLiveMsg(`Read by ${last.name}, ${formatHHMM(toDate(last.readAt))}`);
        if (!reducedMotion) {
          setArrivingIds((cur) => {
            const next = new Set(cur);
            for (const r of newcomers) next.add(r.id);
            return next;
          });
          for (const r of newcomers) {
            const id = r.id;
            window.setTimeout(() => {
              setArrivingIds((cur) => {
                if (!cur.has(id)) return cur;
                const next = new Set(cur);
                next.delete(id);
                return next;
              });
            }, PRESS_MS);
          }
        }
      }
    }
    prevIdsRef.current = nowIds;
  }, [readers, reducedMotion]);

  const visible = expanded ? readers : readers.slice(0, visibleRows);
  const overflow = expanded ? 0 : Math.max(0, readers.length - visibleRows);

  return (
    <div
      ref={nsRootRef}
      className={["ns-due-wrap", className].join(" ")}
      data-slot="due-slip"
      data-reduced={nsMotion.reduced ? "true" : "false"}
      data-motion={nsMotion.motionOn ? "on" : "off"}
    >
      <NsPause slot="due-slip" />
      {overflow > 0 && (
        <div className="ns-due-ghost" aria-hidden="true">
          <span className="ns-due-ghost-count">+{overflow}</span>
        </div>
      )}

      <div className="ns-due-card" data-expanded={expanded || undefined}>
        <button
          type="button"
          className="ns-due-trigger"
          data-expanded={expanded || undefined}
          aria-expanded={expanded}
          aria-label={
            expanded
              ? `${label} expanded — press Escape to collapse`
              : `Expand ${label} to show full names`
          }
          onClick={() => setExpanded(true)}
          onKeyDown={(e) => {
            if (e.key === "Escape" && expanded) {
              e.preventDefault();
              e.stopPropagation();
              setExpanded(false);
            }
          }}
        >
          <span className="ns-due-trigger-title">{label}</span>
          {/* Opening is one-way by click — activating this control again
              while already expanded is a no-op, only Escape closes it (see
              the keydown handler above). That's deliberate: a real reader
              scanning full names shouldn't have their view yanked shut by a
              stray re-click. Once expanded, swap the affordance itself so
              the control stops reading as a broken toggle: the hint spells
              out the real close path and the chevron freezes instead of
              inviting another click. */}
          {expanded ? (
            <span className="ns-due-trigger-hint" aria-hidden="true">
              Esc to collapse
            </span>
          ) : (
            <ChevronGlyph expanded={expanded} />
          )}
        </button>

        <ol role="list" aria-label={label} className="ns-due-rows" data-scroll={expanded || undefined}>
          {visible.map((r, i) => {
            const date = toDate(r.readAt);
            const hhmm = formatHHMM(date);
            const initials = (r.initials?.slice(0, 3).toUpperCase()) || initialsOf(r.name);
            const rotate = stampRotate(r.id);
            const alpha = inkAlpha(i, alphaFloorRow);
            const arriving = arrivingIds.has(r.id);

            return (
              <li
                key={r.id}
                aria-label={`Read by ${r.name}, ${hhmm}`}
                className="ns-due-row"
                data-arriving={arriving || undefined}
                style={
                  {
                    "--due-rotate": `${rotate.toFixed(2)}deg`,
                    "--due-ink": `${(alpha * 100).toFixed(1)}%`,
                  } as Vars
                }
              >
                <span className="ns-due-stamp">
                  <span className="ns-due-ink">{initials}</span>
                </span>
                {expanded && <span className="ns-due-name">{r.name}</span>}
                <time dateTime={date.toISOString()} className="ns-due-time">
                  {hhmm}
                </time>
              </li>
            );
          })}
          {visible.length === 0 && (
            <li className="ns-due-empty" aria-hidden="true">
              No reads yet
            </li>
          )}
        </ol>
      </div>

      <div aria-live="polite" className="sr-only">
        {liveMsg}
      </div>

      <style>{`
.ns-due-wrap{position:relative;display:inline-block;width:100%;padding-right:4px;padding-bottom:4px}
.ns-due-ghost{position:absolute;top:4px;left:4px;right:0;bottom:0;z-index:0;border-radius:12px;border:1px solid var(--border);background:var(--background);pointer-events:none;display:flex;align-items:flex-end;justify-content:flex-end;padding:8px 12px}
.ns-due-ghost-count{font-family:var(--font-mono);font-size:12px;color:var(--muted-foreground)}
.ns-due-card{position:relative;z-index:1;width:100%;border-radius:12px;border:1px solid var(--border);background:var(--background);overflow:hidden}
.ns-due-trigger{display:flex;width:100%;align-items:center;justify-content:space-between;gap:8px;padding:10px 12px;border:none;border-bottom:1px solid var(--border);background:transparent;color:var(--foreground);font-family:var(--font-mono);font-size:11px;letter-spacing:0.08em;text-transform:uppercase;cursor:pointer;outline:none;transition:background-color 150ms ease-out}
.ns-due-trigger:hover{background:color-mix(in srgb, var(--foreground) 5%, transparent)}
.ns-due-trigger:focus-visible{outline:2px solid var(--ring);outline-offset:-2px;border-radius:6px}
.ns-due-trigger[data-expanded]{cursor:default}
.ns-due-trigger[data-expanded]:hover{background:transparent}
.ns-due-trigger-hint{flex-shrink:0;font-family:var(--font-mono);font-size:10px;letter-spacing:0.04em;text-transform:none;color:var(--muted-foreground)}
.ns-due-chevron{color:var(--muted-foreground);transition:transform 180ms cubic-bezier(0.22,1,0.36,1)}
.ns-due-chevron[data-expanded="true"]{transform:rotate(90deg)}
.ns-due-rows{list-style:none;margin:0;padding:0}
.ns-due-rows[data-scroll]{max-height:280px;overflow-y:auto}
.ns-due-row{display:flex;align-items:baseline;gap:10px;min-height:28px;padding:4px 12px}
.ns-due-row + .ns-due-row{border-top:1px solid var(--border)}
.ns-due-empty{padding:10px 12px;font-family:var(--font-mono);font-size:12px;color:var(--muted-foreground)}
.ns-due-stamp{display:inline-flex;align-items:center;justify-content:center;min-width:30px;height:20px;padding:0 5px;border:1px solid var(--border);border-radius:6px;rotate:var(--due-rotate, 0deg);transform-origin:center}
.ns-due-ink{font-family:var(--font-mono);font-size:11px;font-weight:600;letter-spacing:0.02em;color:color-mix(in srgb, var(--foreground) var(--due-ink, 100%), var(--muted-foreground))}
.ns-due-name{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-family:var(--font-mono);font-size:12px;color:color-mix(in srgb, var(--foreground) var(--due-ink, 100%), var(--muted-foreground))}
.ns-due-time{margin-left:auto;flex-shrink:0;font-family:var(--font-mono);font-size:11px;color:var(--muted-foreground)}
.ns-due-row[data-arriving="true"] .ns-due-stamp{animation:ns-due-press ${PRESS_MS}ms cubic-bezier(0.16,1,0.3,1) both}
@keyframes ns-due-press{from{scale:1.06}to{scale:1}}
.ns-due-wrap[data-reduced] .ns-due-row[data-arriving="true"] .ns-due-stamp{animation:none}
.ns-due-wrap[data-reduced] .ns-due-chevron{transition:none}
.ns-due-wrap[data-reduced] .ns-due-trigger{transition:none}
@media (prefers-reduced-motion: reduce){
  .ns-due-row[data-arriving="true"] .ns-due-stamp{animation:none}
  .ns-due-chevron,.ns-due-trigger{transition:none}
}
`}</style>
    </div>
  );
}

"use client"

// Ported from SmoothUI (MIT) — https://github.com/educlopez/smoothui/blob/main/packages/smoothui/components/duration-picker/index.tsx

import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"

import { cn } from "@/lib/utils"
import { AnimatePresence, motion } from "motion/react";
import {
  type KeyboardEvent,
  type PointerEvent as ReactPointerEvent,
  useCallback,
  useEffect,
  useId,
  useMemo,
  useRef,
  useState,
} from "react";

export type DurationUnit = "hours" | "minutes" | "seconds";

export type DurationPickerProps = {
  /** Additional CSS classes */
  className?: string;
  /** Controlled value in seconds */
  value?: number;
  /** Default value (uncontrolled) in seconds */
  defaultValue?: number;
  /** Called whenever the duration changes, with the new value in seconds */
  onValueChange?: (value: number) => void;
  /** Which unit segments to render, most-significant first */
  units?: DurationUnit[];
  /** Minimum total duration in seconds */
  min?: number;
  /** Maximum total duration in seconds */
  max?: number;
  /** Increment applied per arrow key press, in the focused unit's own scale */
  step?: number;
  /** Enable horizontal pointer drag to scrub a segment's value */
  scrub?: boolean;
  /** Disable all interaction */
  disabled?: boolean;
  /** Visible label rendered above the picker */
  label?: string;
};

const UNIT_ORDER: DurationUnit[] = ["hours", "minutes", "seconds"];
const UNIT_DIVISOR: Record<DurationUnit, number> = {
  hours: 3600,
  minutes: 60,
  seconds: 1,
};
const UNIT_LABEL: Record<DurationUnit, string> = {
  hours: "hour",
  minutes: "minute",
  seconds: "second",
};

const DEFAULT_UNITS: DurationUnit[] = ["hours", "minutes", "seconds"];
const DEFAULT_MIN = 0;
const DEFAULT_MAX = 359_999;
const DEFAULT_STEP = 1;
const SHIFT_MULTIPLIER = 10;
const PAGE_STEP_MULTIPLIER = 5;
const TYPE_BUFFER_TIMEOUT_MS = 600;
const PX_PER_DRAG_STEP = 6;
const DIGIT_HEIGHT = 24;
const DIGIT_ROLL_DISTANCE = 12;
const DIGIT_KEY_PATTERN = /^[0-9]$/;

const PAD_FORMATTER = new Intl.NumberFormat(undefined, {
  minimumIntegerDigits: 2,
  useGrouping: false,
});

const clamp = (val: number, min: number, max: number) =>
  Math.min(Math.max(val, min), max);

const sortUnits = (units: DurationUnit[]): DurationUnit[] => {
  const sorted = UNIT_ORDER.filter((unit) => units.includes(unit));
  return sorted.length > 0 ? sorted : DEFAULT_UNITS;
};

const decomposeDuration = (
  totalSeconds: number,
  units: DurationUnit[]
): number[] => {
  let remaining = Math.max(0, Math.trunc(totalSeconds));
  const values: number[] = [];
  for (const unit of units) {
    const divisor = UNIT_DIVISOR[unit];
    const segmentValue = Math.floor(remaining / divisor);
    values.push(segmentValue);
    remaining -= segmentValue * divisor;
  }
  return values;
};

const getSegmentMax = (
  index: number,
  units: DurationUnit[],
  overallMax: number
): number => {
  if (index === 0) {
    return Math.floor(overallMax / UNIT_DIVISOR[units[0]!]);
  }
  const higherDivisor = UNIT_DIVISOR[units[index - 1]!];
  const thisDivisor = UNIT_DIVISOR[units[index]!];
  return Math.floor(higherDivisor / thisDivisor) - 1;
};

const pluralize = (count: number, unit: DurationUnit) =>
  `${count} ${UNIT_LABEL[unit]}${count === 1 ? "" : "s"}`;

/** Formats a duration in seconds into a padded, colon-separated string for the given units. */
export const formatDuration = (
  totalSeconds: number,
  units: DurationUnit[] = DEFAULT_UNITS
): string => {
  const sortedUnits = sortUnits(units);
  const values = decomposeDuration(totalSeconds, sortedUnits);
  return values.map((value) => PAD_FORMATTER.format(value)).join(":");
};

type AnimatedDigitProps = {
  char: string;
  reduceMotion: boolean;
};

const AnimatedDigit = ({ char, reduceMotion }: AnimatedDigitProps) => (
  <span
    className="relative inline-block w-[0.62em] text-center"
    style={{ height: DIGIT_HEIGHT }}
  >
    <AnimatePresence initial={false} mode="popLayout">
      <motion.span
        animate={reduceMotion ? { opacity: 1, y: 0 } : { opacity: 1, y: 0 }}
        className="absolute inset-0 flex items-center justify-center"
        exit={
          reduceMotion
            ? { opacity: 0, transition: { duration: 0 } }
            : { opacity: 0, y: DIGIT_ROLL_DISTANCE }
        }
        initial={
          reduceMotion
            ? { opacity: 1, y: 0 }
            : { opacity: 0, y: -DIGIT_ROLL_DISTANCE }
        }
        key={char}
        transition={
          reduceMotion
            ? { duration: 0 }
            : { bounce: 0.1, duration: 0.25, type: "spring" }
        }
      >
        {char}
      </motion.span>
    </AnimatePresence>
  </span>
);

type TypingState = { index: number; text: string };

const DurationPicker = ({
  className,
  value: controlledValue,
  defaultValue = 0,
  onValueChange,
  units = DEFAULT_UNITS,
  min = DEFAULT_MIN,
  max = DEFAULT_MAX,
  step = DEFAULT_STEP,
  scrub = true,
  disabled = false,
  label,
}: DurationPickerProps) => {
  const shouldReduceMotion = usePrefersReducedMotion();
  const labelId = useId();
  const isControlled = controlledValue !== undefined;
  const [internalValue, setInternalValue] = useState(
    clamp(defaultValue, min, max)
  );
  const value = isControlled ? controlledValue : internalValue;

  const sortedUnits = useMemo(() => sortUnits(units), [units]);
  const values = useMemo(
    () => decomposeDuration(value, sortedUnits),
    [value, sortedUnits]
  );

  const segmentRefs = useRef<(HTMLDivElement | null)[]>([]);
  const dragStateRef = useRef<{
    index: number;
    startX: number;
    startValue: number;
  } | null>(null);
  const typingRef = useRef<TypingState | null>(null);
  const typingTimeoutRef = useRef<ReturnType<typeof setTimeout> | undefined>(
    undefined
  );
  const [draggingIndex, setDraggingIndex] = useState<number | null>(null);

  const setTotal = useCallback(
    (next: number) => {
      const clamped = clamp(Math.round(next), min, max);
      if (!isControlled) {
        setInternalValue(clamped);
      }
      onValueChange?.(clamped);
    },
    [isControlled, min, max, onValueChange]
  );

  const commitSegmentValue = useCallback(
    (index: number, rawValue: number) => {
      const divisor = UNIT_DIVISOR[sortedUnits[index]!];
      const currentValues = decomposeDuration(value, sortedUnits);
      const delta = (rawValue - currentValues[index]!) * divisor;
      setTotal(value + delta);
    },
    [sortedUnits, value, setTotal]
  );

  const clearTypingTimeout = useCallback(() => {
    if (typingTimeoutRef.current !== undefined) {
      clearTimeout(typingTimeoutRef.current);
      typingTimeoutRef.current = undefined;
    }
  }, []);

  useEffect(() => clearTypingTimeout, [clearTypingTimeout]);

  const focusSegment = useCallback((index: number) => {
    segmentRefs.current[index]?.focus();
  }, []);

  const commitTyped = useCallback(
    (index: number, text: string, advance: boolean) => {
      commitSegmentValue(index, Number.parseInt(text, 10));
      typingRef.current = null;
      clearTypingTimeout();
      if (advance) {
        focusSegment(index + 1);
      }
    },
    [commitSegmentValue, clearTypingTimeout, focusSegment]
  );

  const handleDigit = useCallback(
    (index: number, digit: string) => {
      const isLast = index === sortedUnits.length - 1;
      const { current } = typingRef;
      clearTypingTimeout();

      if (current && current.index === index && current.text.length === 1) {
        commitTyped(index, current.text + digit, !isLast);
        return;
      }

      typingRef.current = { index, text: digit };
      commitSegmentValue(index, Number.parseInt(digit, 10));
      typingTimeoutRef.current = setTimeout(() => {
        commitTyped(index, digit, !isLast);
      }, TYPE_BUFFER_TIMEOUT_MS);
    },
    [sortedUnits, clearTypingTimeout, commitTyped, commitSegmentValue]
  );

  const handleSegmentKeyDown = useCallback(
    (event: KeyboardEvent<HTMLDivElement>, index: number) => {
      if (disabled) {
        return;
      }
      const unit = sortedUnits[index];
      const divisor = UNIT_DIVISOR[unit!];
      const multiplier = event.shiftKey ? SHIFT_MULTIPLIER : 1;

      if (DIGIT_KEY_PATTERN.test(event.key)) {
        event.preventDefault();
        handleDigit(index, event.key);
        return;
      }

      switch (event.key) {
        case "ArrowUp":
          event.preventDefault();
          setTotal(value + step * multiplier * divisor);
          break;
        case "ArrowDown":
          event.preventDefault();
          setTotal(value - step * multiplier * divisor);
          break;
        case "PageUp":
          event.preventDefault();
          setTotal(value + step * PAGE_STEP_MULTIPLIER * divisor);
          break;
        case "PageDown":
          event.preventDefault();
          setTotal(value - step * PAGE_STEP_MULTIPLIER * divisor);
          break;
        case "Home":
          event.preventDefault();
          commitSegmentValue(index, 0);
          break;
        case "End":
          event.preventDefault();
          commitSegmentValue(index, getSegmentMax(index, sortedUnits, max));
          break;
        case "ArrowRight":
          event.preventDefault();
          focusSegment(index + 1);
          break;
        case "ArrowLeft":
          event.preventDefault();
          focusSegment(index - 1);
          break;
        default:
          break;
      }
    },
    [
      disabled,
      sortedUnits,
      step,
      value,
      max,
      setTotal,
      commitSegmentValue,
      focusSegment,
      handleDigit,
    ]
  );

  const handleSegmentBlur = useCallback(
    (index: number) => {
      if (typingRef.current?.index === index) {
        clearTypingTimeout();
        typingRef.current = null;
      }
    },
    [clearTypingTimeout]
  );

  const handlePointerDown = useCallback(
    (event: ReactPointerEvent<HTMLDivElement>, index: number) => {
      if (!scrub || disabled) {
        return;
      }
      event.currentTarget.setPointerCapture(event.pointerId);
      dragStateRef.current = {
        index,
        startValue: value,
        startX: event.clientX,
      };
      setDraggingIndex(index);
    },
    [scrub, disabled, value]
  );

  const handlePointerMove = useCallback(
    (event: ReactPointerEvent<HTMLDivElement>) => {
      const drag = dragStateRef.current;
      if (!drag) {
        return;
      }
      const divisor = UNIT_DIVISOR[sortedUnits[drag.index]!];
      const deltaSteps = Math.round(
        (event.clientX - drag.startX) / PX_PER_DRAG_STEP
      );
      setTotal(drag.startValue + deltaSteps * step * divisor);
    },
    [sortedUnits, step, setTotal]
  );

  const handlePointerUp = useCallback(() => {
    dragStateRef.current = null;
    setDraggingIndex(null);
  }, []);

  return (
    <div className={cn("inline-flex flex-col gap-1.5", className)} data-reduced={shouldReduceMotion ? "true" : "false"} data-slot="duration-picker">
      {label ? (
        <span
          className="font-medium text-muted-foreground text-xs"
          id={labelId}
        >
          {label}
        </span>
      ) : null}
      <div
        aria-label={label ? undefined : "Duration"}
        aria-labelledby={label ? labelId : undefined}
        className={cn(
          "inline-flex items-center gap-0.5 rounded-lg border border-border bg-muted/40 px-2 py-1.5",
          disabled && "opacity-50"
        )}
        role="group"
      >
        {sortedUnits.map((unit, index) => {
          const text = PAD_FORMATTER.format(values[index]!);
          const isDragging = draggingIndex === index;
          return (
            // biome-ignore lint/suspicious/noArrayIndexKey: segments are stable per unit
            <span className="flex items-center" key={unit}>
              {index > 0 && (
                <span aria-hidden="true" className="mx-0.5 text-foreground/40">
                  :
                </span>
              )}
              <div
                aria-disabled={disabled || undefined}
                aria-label={UNIT_LABEL[unit]}
                aria-valuemax={getSegmentMax(index, sortedUnits, max)}
                aria-valuemin={0}
                aria-valuenow={values[index]}
                aria-valuetext={pluralize(values[index]!, unit)}
                className={cn(
                  "relative flex select-none items-center justify-center rounded-md px-1 py-0.5 font-medium text-foreground tabular-nums outline-none",
                  "focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2",
                  scrub && !disabled && "cursor-ew-resize",
                  disabled && "pointer-events-none",
                  isDragging && "bg-foreground/10"
                )}
                onBlur={() => handleSegmentBlur(index)}
                onKeyDown={(event) => handleSegmentKeyDown(event, index)}
                onPointerDown={(event) => handlePointerDown(event, index)}
                onPointerMove={handlePointerMove}
                onPointerUp={handlePointerUp}
                ref={(el) => {
                  segmentRefs.current[index] = el;
                }}
                role="spinbutton"
                style={{ fontSize: 18, touchAction: "none" }}
                tabIndex={disabled ? -1 : 0}
              >
                {text.split("").map((char, charIndex) => (
                  <AnimatedDigit
                    char={char}
                    // biome-ignore lint/suspicious/noArrayIndexKey: digit position within a segment is stable
                    key={charIndex}
                    reduceMotion={Boolean(shouldReduceMotion)}
                  />
                ))}
              </div>
            </span>
          );
        })}
      </div>
    </div>
  );
};

