          style={{
            width: unit === "%" ? `${width}%` : width,
            height: unit === "%" ? undefined : height,
            aspectRatio: unit === "%" ? `${width} / ${height}` : undefined,
            borderRadius: radius,
            maxWidth: "100%",
          }}
