"use client"

import React, {
  useCallback,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  type CSSProperties,
  type PointerEvent,
} from "react"
import Matter from "matter-js"

import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { cn } from "@/lib/utils"

const { Bodies, Body, Composite, Engine } = Matter

export type FolderFloatItem = string | { label: string; value: string }
export type FolderFloatTrigger = "hover" | "click"

export interface FolderFloatProps {
  items?: FolderFloatItem[]
  label?: string
  sublabel?: string
  trigger?: FolderFloatTrigger
  defaultOpen?: boolean
  closeOnSelect?: boolean
  physics?: boolean
  drift?: number
  onSelect?: (value: string, index: number) => void
  onOpenChange?: (open: boolean) => void
  folderColor?: string
  frontColor?: string
  paperColor?: string
  itemColor?: string
  itemTextColor?: string
  labelColor?: string
  width?: number
  height?: number
  radius?: number
  spread?: number
  lift?: number
  tilt?: number
  flapAngle?: number
  restAngle?: number
  openDuration?: number
  stagger?: number
  bounce?: number
  className?: string
}

type Entry = { label: string; value: string }
type Size = { w: number; h: number }
type Zone = { left: number; right: number; top: number; bottom: number }
type Drag = { i: number; id: number; dx: number; dy: number; sx: number; sy: number; moved: boolean }
type PhaseBody = Matter.Body & { plugin: { phase: number } }
interface World {
  engine: Matter.Engine | null
  bodies: Matter.Body[]
  sizes: Size[]
  raf: number
  last: number
  t0: number
  drag: Drag | null
  zone: Zone | null
  live: boolean
}
interface Latest {
  onSelect?: FolderFloatProps["onSelect"]
  onOpenChange?: FolderFloatProps["onOpenChange"]
  drift: number
  reduce: boolean
}

const DEFAULT_ITEMS: FolderFloatItem[] = [
  "Try a warmer palette",
  "Tighten the spacing",
  "Logo feels small",
  "Love the new hero",
]
const PAD = 28
const CHAR = 6.8
const GAP = 12
const ROW = 52
const DRAG_MIN = 4
const ZONE_PAD = 8

const jitter = (i: number) => {
  const x = Math.sin(i * 12.9898 + 4.1414) * 43758.5453
  return x - Math.floor(x)
}

const layout = (list: Entry[], spread: number, lift: number, tilt: number, sizes: (Size | null)[]) => {
  const rows: { items: { i: number; pw: number }[]; width: number }[] = []
  let row: { i: number; pw: number }[] = []
  let width = 0
  list.forEach((item, i) => {
    const pw = sizes[i]?.w ?? PAD + item.label.length * CHAR
    if (row.length && width + GAP + pw > spread * 2) {
      rows.push({ items: row, width })
      row = []
      width = 0
    }
    row.push({ i, pw })
    width += (row.length > 1 ? GAP : 0) + pw
  })
  if (row.length) rows.push({ items: row, width })
  const pos: { x: number; y: number; r: number }[] = []
  rows.forEach((r, ri) => {
    let x = -r.width / 2
    const shift = (ri % 2 ? 1 : -1) * Math.min(16, spread * 0.1)
    r.items.forEach(({ i, pw }) => {
      const j = jitter(i)
      pos[i] = { x: x + pw / 2 + shift + (j - 0.5) * 6, y: -lift - ri * ROW - j * 6, r: tilt * (j * 2 - 1) }
      x += pw + GAP
    })
  })
  return pos
}

const STYLE = `
@keyframes folder-float-drift { 0%, 100% { translate: 0 0; } 50% { translate: 0 -3px; } }
@keyframes folder-float-pop { 30% { scale: 1.1; } 100% { scale: 1; } }
`

function FolderFloat({
  items = DEFAULT_ITEMS,
  label = "Design feedback",
  sublabel = "",
  trigger = "hover",
  defaultOpen = false,
  closeOnSelect = true,
  physics = true,
  drift = 0.5,
  onSelect,
  onOpenChange,
  folderColor = "var(--primary)",
  frontColor = "var(--foreground)",
  paperColor = "var(--card)",
  itemColor = "var(--muted)",
  itemTextColor = "var(--card-foreground)",
  labelColor = "var(--card)",
  width = 200,
  height = 148,
  radius = 14,
  spread = 180,
  lift = 26,
  tilt = 8,
  flapAngle = 34,
  restAngle = 16,
  openDuration = 520,
  stagger = 45,
  bounce = 0.3,
  className = "",
}: FolderFloatProps) {
  const [open, setOpen] = useState(defaultOpen)
  const [popped, setPopped] = useState(-1)
  const [live, setLive] = useState(false)
  const [sizes, setSizes] = useState<Size[]>([])
  const anchorRef = useRef<HTMLDivElement>(null)
  const pillRefs = useRef<(HTMLButtonElement | null)[]>([])
  const world = useRef<World>({
    engine: null,
    bodies: [],
    sizes: [],
    raf: 0,
    last: 0,
    t0: 0,
    drag: null,
    zone: null,
    live: false,
  })
  const reduced = usePrefersReducedMotion()
  const latest = useRef<Latest>({ drift, reduce: reduced })
  const popTimer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined)
  const liveTimer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined)
  const list: Entry[] = items.map((item) => (typeof item === "string" ? { label: item, value: item } : item))
  const n = list.length
  const sub = sublabel || `${n} ${n === 1 ? "note" : "notes"}`
  const pos = layout(list, spread, lift, tilt, sizes)
  const posKey = pos.map((p) => `${p.x},${p.y}`).join("|")

  useEffect(() => {
    latest.current.onSelect = onSelect
    latest.current.onOpenChange = onOpenChange
    latest.current.drift = drift
    latest.current.reduce = reduced
  })

  const labelsKey = list.map((item) => item.label).join("|")
  useLayoutEffect(() => {
    const measure = () => {
      const next = pillRefs.current.slice(0, n).map((el) => (el ? { w: el.offsetWidth, h: el.offsetHeight } : null))
      if (next.some((s) => !s)) return
      const sized = next as Size[]
      setSizes((prev) =>
        prev.length === sized.length && prev.every((s, i) => s.w === sized[i]?.w && s.h === sized[i]?.h) ? prev : sized
      )
    }
    measure()
    document.fonts?.ready.then(measure)
  }, [n, labelsKey])

  const stopPhysics = useCallback(() => {
    const w = world.current
    clearTimeout(liveTimer.current)
    cancelAnimationFrame(w.raf)
    w.raf = 0
    if (w.engine) {
      w.bodies.forEach((b, i) => {
        const el = pillRefs.current[i]
        if (!el) return
        el.style.setProperty("--x", `${b.position.x.toFixed(1)}px`)
        el.style.setProperty("--y", `${(b.position.y - (w.sizes[i]?.h ?? 0) / 2).toFixed(1)}px`)
      })
      Composite.clear(w.engine.world, false, true)
      Engine.clear(w.engine)
      w.engine = null
    }
    w.bodies = []
    w.drag = null
    w.live = false
    setLive(false)
  }, [])

  const startPhysics = useCallback(() => {
    const w = world.current
    if (w.engine) return
    const els = pillRefs.current.slice(0, n)
    if (els.some((el) => !el)) return
    const engine = Engine.create({ gravity: { x: 0, y: 0 } })
    engine.enableSleeping = false
    w.engine = engine
    w.sizes = (els as HTMLButtonElement[]).map((el) => ({ w: el.offsetWidth, h: el.offsetHeight }))
    const ys = pos.map((p) => p.y)
    const zone = {
      left: -spread - ZONE_PAD,
      right: spread + ZONE_PAD,
      top: Math.min(...ys) - ZONE_PAD,
      bottom: -lift + Math.max(...w.sizes.map((s) => s.h)),
    }
    w.zone = zone
    w.bodies = els.map((_, i) => {
      const { w: bw, h: bh } = w.sizes[i] ?? { w: 0, h: 0 }
      const b = Bodies.rectangle(pos[i]?.x ?? 0, (pos[i]?.y ?? 0) + bh / 2, bw, bh, {
        chamfer: { radius: Math.min(bh / 2 - 1, 16) },
        restitution: 0.55,
        friction: 0,
        frictionAir: 0.08,
        inertia: Infinity,
      })
      ;(b as PhaseBody).plugin = { phase: jitter(i) * Math.PI * 2 }
      return b
    })
    const T = 80
    const walls = [
      Bodies.rectangle((zone.left + zone.right) / 2, zone.top - T / 2, zone.right - zone.left + 2 * T, T, {
        isStatic: true,
      }),
      Bodies.rectangle((zone.left + zone.right) / 2, zone.bottom + T / 2, zone.right - zone.left + 2 * T, T, {
        isStatic: true,
      }),
      Bodies.rectangle(zone.left - T / 2, (zone.top + zone.bottom) / 2, T, zone.bottom - zone.top + 2 * T, {
        isStatic: true,
      }),
      Bodies.rectangle(zone.right + T / 2, (zone.top + zone.bottom) / 2, T, zone.bottom - zone.top + 2 * T, {
        isStatic: true,
      }),
    ]
    Composite.add(engine.world, [...w.bodies, ...walls])
    w.live = true
    w.last = 0
    setLive(true)
    const tick = (now: number) => {
      const s = world.current
      if (!s.engine) return
      if (!s.last) s.t0 = now
      const dt = s.last ? Math.min(32, now - s.last) : 16
      s.last = now
      const t = (now - s.t0) / 1000
      const k = latest.current.drift * 0.00005 * Math.min(1, t / 2)
      s.bodies.forEach((b, i) => {
        if (s.drag && s.drag.i === i) return
        const ph = (b as PhaseBody).plugin.phase
        Body.applyForce(b, b.position, {
          x: Math.sin(t * 0.9 + ph) * k * b.mass,
          y: Math.cos(t * 1.3 + ph * 1.7) * k * b.mass,
        })
      })
      Engine.update(s.engine, dt)
      s.bodies.forEach((b, i) => {
        const el = pillRefs.current[i]
        if (!el) return
        el.style.setProperty("--x", `${b.position.x.toFixed(1)}px`)
        el.style.setProperty("--y", `${(b.position.y - (s.sizes[i]?.h ?? 0) / 2).toFixed(1)}px`)
      })
      s.raf = requestAnimationFrame(tick)
    }
    w.raf = requestAnimationFrame(tick)
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [n, spread, lift, posKey])

  const set = useCallback(
    (next: boolean) => {
      if (!next) stopPhysics()
      setOpen((prev) => {
        if (prev === next) return prev
        latest.current.onOpenChange?.(next)
        return next
      })
    },
    [stopPhysics]
  )

  useEffect(() => {
    clearTimeout(liveTimer.current)
    if (!open || !physics || latest.current.reduce) {
      stopPhysics()
      return undefined
    }
    liveTimer.current = setTimeout(startPhysics, openDuration + (n - 1) * stagger + 80)
    return () => clearTimeout(liveTimer.current)
  }, [open, physics, reduced, openDuration, stagger, n, startPhysics, stopPhysics])

  useEffect(
    () => () => {
      clearTimeout(popTimer.current)
      stopPhysics()
    },
    [stopPhysics]
  )

  const pick = (item: Entry, i: number) => {
    latest.current.onSelect?.(item.value, i)
    clearTimeout(popTimer.current)
    setPopped(i)
    popTimer.current = setTimeout(() => setPopped(-1), 320)
    if (closeOnSelect) set(false)
  }

  const pointerAt = (e: PointerEvent<HTMLButtonElement>) => {
    const r = anchorRef.current?.getBoundingClientRect()
    return r ? { x: e.clientX - r.left, y: e.clientY - r.top } : { x: 0, y: 0 }
  }
  const down = (e: PointerEvent<HTMLButtonElement>, i: number) => {
    const w = world.current
    if (!w.live || e.button !== 0) return
    const b = w.bodies[i]
    if (!b) return
    const p = pointerAt(e)
    w.drag = {
      i,
      id: e.pointerId,
      dx: b.position.x - p.x,
      dy: b.position.y - p.y,
      sx: e.clientX,
      sy: e.clientY,
      moved: false,
    }
    try {
      e.currentTarget.setPointerCapture(e.pointerId)
    } catch {}
  }
  const move = (e: PointerEvent<HTMLButtonElement>, i: number) => {
    const w = world.current
    const d = w.drag
    if (!d || d.i !== i || d.id !== e.pointerId) return
    if (!d.moved && Math.hypot(e.clientX - d.sx, e.clientY - d.sy) >= DRAG_MIN) {
      d.moved = true
      e.currentTarget.setAttribute("data-drag", "")
    }
    if (!d.moved) return
    const b = w.bodies[i]
    const size = w.sizes[i]
    if (!b || !size) return
    const { w: bw, h: bh } = size
    const z = w.zone as Zone
    const p = pointerAt(e)
    const x = Math.min(z.right - bw / 2, Math.max(z.left + bw / 2, p.x + d.dx))
    const y = Math.min(z.bottom - bh / 2, Math.max(z.top + bh / 2, p.y + d.dy))
    Body.setVelocity(b, { x: (x - b.position.x) * 0.6, y: (y - b.position.y) * 0.6 })
    Body.setPosition(b, { x, y })
  }
  const up = (e: PointerEvent<HTMLButtonElement>, i: number, item: Entry) => {
    const w = world.current
    const d = w.drag
    if (!d || d.i !== i || d.id !== e.pointerId) return
    w.drag = null
    e.currentTarget.removeAttribute("data-drag")
    try {
      e.currentTarget.releasePointerCapture(e.pointerId)
    } catch {}
    if (!d.moved && e.type === "pointerup") pick(item, i)
  }

  const hover = trigger === "hover"

  return (
    <div
      className={cn(
        "group relative inline-block text-[13px] leading-none font-medium [width:var(--ff-w)] [padding-top:var(--ff-tab)] [font-family:inherit]",
        className
      )}
      data-open={open ? "" : undefined}
      data-live={live ? "" : undefined}
      data-physics={physics ? "" : undefined}
      data-trigger={trigger}
      onPointerEnter={
        hover
          ? (event) => {
              if (event.pointerType === "touch") return
              set(true)
            }
          : undefined
      }
      onPointerLeave={
        hover
          ? (event) => {
              if (event.pointerType === "touch") return
              if (!world.current.drag) set(false)
            }
          : undefined
      }
      onKeyDown={(e: React.KeyboardEvent<HTMLDivElement>) => {
        if (e.key === "Escape" && open) {
          e.stopPropagation()
          set(false)
        }
      }}
      style={
        {
          "--ff-w": `${width}px`,
          "--ff-h": `${height}px`,
          "--ff-r": `${radius}px`,
          "--ff-back": folderColor,
          "--ff-front": frontColor,
          "--ff-paper": paperColor,
          "--ff-item": itemColor,
          "--ff-item-ink": itemTextColor,
          "--ff-label": labelColor,
          "--ff-spread": `${spread}px`,
          "--ff-lift": `${lift}px`,
          "--ff-angle": `${flapAngle}deg`,
          "--ff-rest": `${restAngle}deg`,
          "--ff-open": `${openDuration}ms`,
          "--ff-close": `${Math.round(openDuration * 0.6)}ms`,
          "--ff-stagger": `${stagger}ms`,
          "--ff-n": n,
          "--ff-tab": "14px",
          "--ff-ease-out": "cubic-bezier(0.23, 1, 0.32, 1)",
          "--ff-spring": `cubic-bezier(0.34, ${(1 + bounce * 1.9).toFixed(2)}, 0.64, 1)`,
        } as CSSProperties
      }
    >
      <style>{STYLE}</style>
      <div
        ref={anchorRef}
        className="absolute top-[var(--ff-tab)] left-1/2 z-[1] h-0 w-0 group-data-[open]:before:absolute group-data-[open]:before:top-[calc(-1*(var(--ff-lift)+120px))] group-data-[open]:before:left-[calc(-1*(var(--ff-spread)+100px))] group-data-[open]:before:h-[calc(var(--ff-lift)+120px)] group-data-[open]:before:w-[calc(2*var(--ff-spread)+200px)] group-data-[open]:before:content-['']"
      >
        {list.map((item, i) => {
          const p = pos[i] ?? { x: 0, y: 0, r: 0 }
          return (
            <button
              key={`${item.value}-${i}`}
              ref={(el) => {
                pillRefs.current[i] = el
              }}
              type="button"
              className="pointer-events-none absolute top-0 left-1/2 m-0 h-[34px] cursor-pointer rounded-[17px] border-0 px-3.5 whitespace-nowrap opacity-0 shadow-[0_4px_12px_rgba(0,0,0,0.14)] outline-none [background:var(--ff-item)] [color:var(--ff-item-ink)] [font:inherit] [transform:translate(-50%,44px)_scale(0.6)] [transform-origin:50%_50%] [-webkit-tap-highlight-color:transparent] [transition:transform_var(--ff-close)_var(--ff-ease-out)_calc((var(--ff-n)-1-var(--i))*var(--ff-stagger)*0.5),opacity_160ms_ease_calc((var(--ff-n)-1-var(--i))*var(--ff-stagger)*0.5+var(--ff-close)*0.45),scale_160ms_var(--ff-ease-out)] group-data-[open]:pointer-events-auto group-data-[open]:opacity-100 group-data-[open]:[transform:translate(calc(-50%+var(--x)),var(--y))_rotate(var(--r))_scale(1)] group-data-[open]:[transition:transform_var(--ff-open)_var(--ff-spring)_calc(var(--i)*var(--ff-stagger)),opacity_160ms_ease_calc(var(--i)*var(--ff-stagger)),scale_160ms_var(--ff-ease-out)] group-data-[live]:cursor-grab group-data-[live]:[transition:scale_160ms_var(--ff-ease-out)] data-[drag]:cursor-grabbing! group-data-[open]:hover:[scale:1.05] group-data-[open]:active:[scale:0.97] data-[pop]:[animation:folder-float-pop_320ms_var(--ff-ease-out)] motion-reduce:[transition:opacity_200ms_ease] motion-reduce:group-data-[open]:[transition:opacity_200ms_ease_calc(var(--i)*var(--ff-stagger))]"
              tabIndex={open ? 0 : -1}
              aria-hidden={!open}
              data-pop={popped === i ? "" : undefined}
              style={
                {
                  "--i": i,
                  "--x": `${p.x.toFixed(1)}px`,
                  "--y": `${p.y.toFixed(1)}px`,
                  "--r": `${p.r.toFixed(2)}deg`,
                } as CSSProperties
              }
              onPointerDown={(e) => down(e, i)}
              onPointerMove={(e) => move(e, i)}
              onPointerUp={(e) => up(e, i, item)}
              onPointerCancel={(e) => up(e, i, item)}
              onClick={(e) => {
                if (!world.current.live || e.detail === 0) pick(item, i)
              }}
            >
