import * as React from "react"

import { useAnimationActive } from "@/hooks/use-animation-active"
import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { cn } from "@/lib/utils"

export interface GalaxySpiralProps {
  className?: string
  arms?: number
  radius?: number
  count?: number
  randomness?: number
  speed?: number
  colors?: readonly string[]
}

const VERT = `
attribute vec3 position;
attribute float aRadius;
uniform float u_time;
uniform float u_speed;
uniform mat4 modelViewMatrix;
uniform mat4 projectionMatrix;
varying float vRadius;
void main() {
  float spin = (1.35 - clamp(aRadius, 0.0, 1.2)) * u_time * u_speed;
  float c = cos(spin);
  float s = sin(spin);
  vec3 p = vec3(position.x * c - position.z * s, position.y, position.x * s + position.z * c);
  vec4 mv = modelViewMatrix * vec4(p, 1.0);
  gl_Position = projectionMatrix * mv;
  gl_PointSize = clamp(140.0 / max(0.4, -mv.z), 1.0, 12.0);
  vRadius = aRadius;
}
`

const FRAG = `
precision highp float;
uniform vec3 u_inner;
uniform vec3 u_outer;
varying float vRadius;
void main() {
  vec2 p = gl_PointCoord * 2.0 - 1.0;
  float d = dot(p, p);
  if (d > 1.0) discard;
  float glow = pow(1.0 - d, 1.4);
  vec3 color = mix(u_inner, u_outer, clamp(vRadius, 0.0, 1.0));
  gl_FragColor = vec4(color * glow, glow);
}
`

function mulberry32(seed: number) {
  let state = seed >>> 0
  return () => {
    state += 0x6d2b79f5
    let next = state
    next = Math.imul(next ^ (next >>> 15), next | 1)
    next ^= next + Math.imul(next ^ (next >>> 7), next | 61)
    return ((next ^ (next >>> 14)) >>> 0) / 4294967296
  }
}

function useSynced<T>(prop: T | undefined, fallback: T): [T, (next: T) => void] {
  const [draft, setDraft] = React.useState<{ prop: T | undefined; value: T } | null>(null)
  const value = draft && Object.is(draft.prop, prop) ? draft.value : (prop ?? fallback)
  return [value, (next) => setDraft({ prop, value: next })]
}

function hexToRgb(hex: string) {
  const value = Number.parseInt(hex.slice(1), 16)
  return [((value >> 16) & 255) / 255, ((value >> 8) & 255) / 255, (value & 255) / 255]
}

function fillGalaxy(positions: Float32Array, radii: Float32Array, arms: number, radius: number, randomness: number) {
  const rand = mulberry32(arms * 1000 + Math.round(radius * 100) + Math.round(randomness * 50))
  const count = radii.length
  for (let index = 0; index < count; index += 1) {
    const arm = index % arms
    const along = Math.pow(rand(), 0.85)
    const distance = 0.08 + along * radius
    const angle = (arm / arms) * Math.PI * 2 + distance * 4.2
    const scatter = randomness * distance * 0.45
    positions[index * 3] = Math.cos(angle) * distance + (rand() - 0.5) * scatter
    positions[index * 3 + 1] = (rand() - 0.5) * scatter * 0.28
    positions[index * 3 + 2] = Math.sin(angle) * distance + (rand() - 0.5) * scatter
    radii[index] = distance / Math.max(radius, 0.2)
  }
}

function GalaxyFallback() {
  return (
    <div
      className="absolute inset-0"
      style={{
        background:
          "radial-gradient(circle at 50% 55%, #fde68a 0 5%, #312e81 16%, #020617 58%), repeating-conic-gradient(from 12deg, transparent 0 16deg, rgba(147,197,253,0.2) 16deg 18deg)",
      }}
    />
  )
}

function GalaxySpiral({
  className,
  arms: armsProp,
  radius: radiusProp,
  count: countProp,
  randomness: randomnessProp,
  speed: speedProp,
  colors: colorsProp,
}: GalaxySpiralProps) {
  const reduced = usePrefersReducedMotion()
  const hostRef = React.useRef<HTMLDivElement>(null)
  const canvasRef = React.useRef<HTMLCanvasElement>(null)
  const active = useAnimationActive(hostRef)
  const [arms, setArms] = useSynced(armsProp, 3)
  const [radius, setRadius] = useSynced(radiusProp, 1)
  const [count, setCount] = useSynced(countProp, 1800)
  const [randomness, setRandomness] = useSynced(randomnessProp, 0.45)
  const [speed, setSpeed] = useSynced(speedProp, 0.7)
  const [inner, setInner] = useSynced(colorsProp?.[0], "#f8e7b0")
  const [outer, setOuter] = useSynced(colorsProp?.[1], "#7dd3fc")
  const [fallback, setFallback] = React.useState(false)
  const live = React.useRef({ arms, radius, count, randomness, speed, inner, outer, tiltX: 0.35, tiltY: 0.2 })
  const drag = React.useRef<{ x: number; y: number; tiltX: number; tiltY: number } | null>(null)
  const showCanvas = !reduced && !fallback

  React.useEffect(() => {
    live.current = { ...live.current, arms, radius, count, randomness, speed, inner, outer }
  }, [arms, radius, count, randomness, speed, inner, outer])

  React.useEffect(() => {
    if (!showCanvas || !active) return
    const canvas = canvasRef.current
    const host = hostRef.current
    if (!canvas || !host) return
    let cancelled = false
    let frame = 0
    const run = async () => {
      const ogl = await import("ogl")
      if (cancelled) return undefined
      const renderer = new ogl.Renderer({ canvas, alpha: false, dpr: Math.min(window.devicePixelRatio || 1, 2) })
      const gl = renderer.gl
      if (!gl) {
        queueMicrotask(() => {
          if (!cancelled) setFallback(true)
        })
        return undefined
      }
      const camera = new ogl.Camera(gl, { fov: 42 })
      camera.position.set(0, 0.85, 2.7)
      camera.rotation.x = -0.28
      const scene = new ogl.Transform()
      const group = new ogl.Transform()
      group.setParent(scene)
      const positions = new Float32Array(live.current.count * 3)
      const radii = new Float32Array(live.current.count)
      fillGalaxy(positions, radii, live.current.arms, live.current.radius, live.current.randomness)
      const geometry = new ogl.Geometry(gl, {
        position: { size: 3, data: positions },
        aRadius: { size: 1, data: radii },
      })
      const uniforms = {
        u_time: { value: 0 },
        u_speed: { value: live.current.speed },
        u_inner: { value: hexToRgb(live.current.inner) },
        u_outer: { value: hexToRgb(live.current.outer) },
      }
      const program = new ogl.Program(gl, {
        vertex: VERT,
        fragment: FRAG,
        uniforms,
        transparent: true,
        depthWrite: false,
        depthTest: false,
      })
      program.setBlendFunc(gl.SRC_ALPHA, gl.ONE)
      const mesh = new ogl.Mesh(gl, { geometry, program, mode: gl.POINTS, frustumCulled: false })
      mesh.setParent(group)
      let stamp = ""
      const resize = () => {
        const rect = host.getBoundingClientRect()
        renderer.setSize(Math.max(rect.width, 1), Math.max(rect.height, 1))
        camera.perspective({ aspect: Math.max(rect.width, 1) / Math.max(rect.height, 1) })
      }
      resize()
      const observer = new ResizeObserver(resize)
      observer.observe(host)
      const started = performance.now()
      const tick = () => {
        const spec = live.current
        const next = `${spec.count}|${spec.arms}|${spec.radius}|${spec.randomness}`
        if (next !== stamp && spec.count === radii.length) {
          stamp = next
          fillGalaxy(positions, radii, spec.arms, spec.radius, spec.randomness)
          const positionAttr = geometry.attributes.position
          const radiusAttr = geometry.attributes.aRadius
          if (positionAttr) positionAttr.needsUpdate = true
          if (radiusAttr) radiusAttr.needsUpdate = true
        }
        uniforms.u_time.value = (performance.now() - started) / 1000
        uniforms.u_speed.value = spec.speed
        uniforms.u_inner.value = hexToRgb(spec.inner)
        uniforms.u_outer.value = hexToRgb(spec.outer)
        group.rotation.x = spec.tiltX
        group.rotation.y = spec.tiltY
        renderer.render({ scene, camera })
        frame = window.requestAnimationFrame(tick)
      }
      frame = window.requestAnimationFrame(tick)
      return () => {
        window.cancelAnimationFrame(frame)
        observer.disconnect()
        gl.getExtension("WEBGL_lose_context")?.loseContext()
      }
    }
    const job = run().catch(() => {
      if (!cancelled) {
        queueMicrotask(() => {
          if (!cancelled) setFallback(true)
        })
      }
      return undefined
    })
    return () => {
      cancelled = true
      window.cancelAnimationFrame(frame)
      void job.then((cleanup) => cleanup?.())
    }
  }, [active, showCanvas, count])

  return (
    <div data-slot="galaxy-spiral" className={cn("w-full space-y-3", className)}>
      <div className="flex flex-wrap gap-3 text-xs">
        <label className="flex items-center gap-2">旋臂<input aria-label="旋臂" type="range" min={2} max={6} step={1} value={arms} onChange={(event) => setArms(Number(event.target.value))} /></label>
        <label className="flex items-center gap-2">半径<input aria-label="半径" type="range" min={0.4} max={1.4} step={0.02} value={radius} onChange={(event) => setRadius(Number(event.target.value))} /></label>
        <label className="flex items-center gap-2">粒子<input aria-label="粒子数" type="range" min={600} max={3200} step={200} value={count} onChange={(event) => setCount(Number(event.target.value))} /></label>
        <label className="flex items-center gap-2">随机<input aria-label="随机度" type="range" min={0} max={1} step={0.01} value={randomness} onChange={(event) => setRandomness(Number(event.target.value))} /></label>
        <label className="flex items-center gap-2">速度<input aria-label="速度" type="range" min={0} max={2} step={0.01} value={speed} onChange={(event) => setSpeed(Number(event.target.value))} /></label>
        <label className="flex items-center gap-2">内色<input aria-label="内色" type="color" value={inner} onChange={(event) => setInner(event.target.value)} /></label>
        <label className="flex items-center gap-2">外色<input aria-label="外色" type="color" value={outer} onChange={(event) => setOuter(event.target.value)} /></label>
      </div>
      <div
        ref={hostRef}
        role="img"
        aria-label="螺旋星系。拖动可倾斜，内圈转得更快。"
        className="relative h-80 touch-none overflow-hidden rounded-xl border bg-slate-950"
        onPointerDown={(event) => {
          drag.current = { x: event.clientX, y: event.clientY, tiltX: live.current.tiltX, tiltY: live.current.tiltY }
          event.currentTarget.setPointerCapture(event.pointerId)
        }}
        onPointerMove={(event) => {
          if (!drag.current) return
          live.current.tiltY = drag.current.tiltY + (event.clientX - drag.current.x) * 0.005
          live.current.tiltX = drag.current.tiltX + (event.clientY - drag.current.y) * 0.005
        }}
        onPointerUp={() => {
          drag.current = null
        }}
      >
        {showCanvas ? <canvas ref={canvasRef} className="absolute inset-0 size-full" /> : <GalaxyFallback />}
      </div>
    </div>
  )
}

export { GalaxySpiral }

"use client";

// Ported from ns-ui (MIT, (c) 2026 Nikolas Sapalidis) — https://github.com/nikolas-sapa/ns-ui/blob/main/registry/core/galley-bracket/component.tsx

import {
  useCallback,
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from "react";

import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion";
import { useAnimationActive } from "@/hooks/use-animation-active";
import type { RefObject } from "react";

type NsJob = { token: number; cb: (now: number) => void; raf: number };
type NsApi = {
  requestFrame: (cb: (now: number) => void) => number;
  cancelFrame: (id: number | null | undefined) => void;
  motionNow: () => number;
};

const nsApi: NsApi = {
  requestFrame: (cb) => requestAnimationFrame((t) => cb(t)),
  cancelFrame: (id) => {
    if (id) cancelAnimationFrame(id);
  },
  motionNow: () => performance.now(),
};

function nsRequestFrame(cb: (now: number) => void) {
  return nsApi.requestFrame(cb);
}
function nsCancelFrame(id: number | null | undefined) {
  nsApi.cancelFrame(id);
}
function nsMotionNow() {
  return nsApi.motionNow();
}

function useNsBind(rootRef: RefObject<HTMLElement | null>) {
  const reduced = usePrefersReducedMotion();
  const live = useAnimationActive(rootRef as RefObject<Element | null>);
  const liveRef = useRef(live);
  const reducedRef = useRef(reduced);
  const holdRef = useRef(0);
  const offsetRef = useRef(0);
  const jobsRef = useRef(new Map<number, NsJob>());
  const seqRef = useRef(1);

  const motionNow = () => {
    const raw = performance.now();
    if (!liveRef.current) {
      if (holdRef.current === 0) holdRef.current = raw;
      return holdRef.current - offsetRef.current;
    }
    if (holdRef.current !== 0) {
      offsetRef.current += raw - holdRef.current;
      holdRef.current = 0;
    }
    return raw - offsetRef.current;
  };

  const requestFrame = (cb: (now: number) => void) => {
    const token = seqRef.current++;
    const job: NsJob = { token, cb, raf: 0 };
    jobsRef.current.set(token, job);
    const kick = () => {
      if (!liveRef.current) {
        if (holdRef.current === 0) holdRef.current = performance.now();
        job.raf = 0;
        return;
      }
      job.raf = requestAnimationFrame(() => {
        if (!jobsRef.current.has(token)) return;
        if (!liveRef.current) {
          job.raf = 0;
          if (holdRef.current === 0) holdRef.current = performance.now();
          return;
        }
        jobsRef.current.delete(token);
        cb(motionNow());
      });
    };
    kick();
    return token;
  };

  const cancelFrame = (id: number | null | undefined) => {
    if (id == null) return;
    const job = jobsRef.current.get(id);
    if (!job) return;
    if (job.raf) cancelAnimationFrame(job.raf);
    jobsRef.current.delete(id);
  };

  useEffect(() => {
    liveRef.current = live;
    reducedRef.current = reduced;
  }, [live, reduced]);

  useEffect(() => {
    nsApi.requestFrame = requestFrame;
    nsApi.cancelFrame = cancelFrame;
    nsApi.motionNow = motionNow;
  });

  useEffect(() => {
    if (!live) return;
    for (const job of [...jobsRef.current.values()]) {
      if (job.raf) continue;
      const { token, cb } = job;
      job.raf = requestAnimationFrame(() => {
        if (!jobsRef.current.has(token)) return;
        if (!liveRef.current) {
          job.raf = 0;
          return;
        }
        jobsRef.current.delete(token);
        cb(motionNow());
      });
    }
  }, [live]);

  useEffect(
    () => () => {
      for (const job of jobsRef.current.values()) {
        if (job.raf) cancelAnimationFrame(job.raf);
      }
      jobsRef.current.clear();
    },
    [],
  );

  return { reduced, live, motionOn: live && !reduced, requestFrame, cancelFrame, motionNow };
}

function NsPause({ slot }: { slot: string }) {
  return (
    <style>{`[data-slot="${slot}"][data-motion="off"],[data-slot="${slot}"][data-motion="off"] *{animation-play-state:paused !important}`}</style>
  );
}

// ---------------------------------------------------------------------------
// GalleyBracket — remote collaborators' live selections drawn as proofreader's
// marks, not highlight washes: a thin corner bracket at each end of a range,
// a hairline underline between them, and the selector's initials set small in
// the left margin at the opening bracket. Ranges are measured off the real
// rendered text with Range.getClientRects() (a Range over one text node, the
// same primitive selecting the text and reading getClientRects() would use),
// so a multi-line selection gets one underline per wrapped line and brackets
// only at its true start/end — never one per line. When ranges overlap, the
// only thing that varies per selection is its arrival index within that
// overlap group (arrival order, not z-index or hue): later arrivals' brackets
// stand outward from the text by index*3px and draw slightly lighter, so
// concurrent selections nest like stacked proof brackets instead of blending
// into a third, unreadable color. Marks draw in with a 160ms stroke-dashoffset
// reveal on first arrival only — the same selection re-ranging (a drag) never
// replays it, which is what keeps rapid re-selection from strobing. The SVG
// layer is aria-hidden; the real accessible surface is a debounced (2s)
// role=status summary ("Ana selected 12 words") plus a keyboard-reachable
// list of jump buttons that move the platform's own Selection into the named
// range. Every stroke is --foreground at reduced opacity — no filled
// highlights, ever, because two overlapping fills produce a third value that
// identifies nobody. DOM+SVG+CSS only, no canvas.
// ---------------------------------------------------------------------------

export interface GalleyBracketSelection {
  /** stable id for this collaborator's current range */
  id: string;
  /** full name — used in the debounced summary and the jump list */
  name: string;
  /** short code drawn small in the margin at the opening bracket; derived from `name` if omitted */
  initials?: string;
  /** character offset into `text` where the range starts */
  start: number;
  /** character offset into `text` where the range ends (exclusive) */
  end: number;
  /** arrival order key, lower = earlier. Defaults to this selection's index in the array, so
   *  passing a freshly-appended selection last is enough to make it the latest arrival. */
  arrivedAt?: number;
}

export interface GalleyBracketProps {
  /** the shared paragraph's plain text. One instance renders one paragraph — for a
   *  multi-paragraph editor, render one GalleyBracket per paragraph so range offsets
   *  stay simple character indices into a single text node. */
  text: string;
  /** remote collaborators' current ranges into `text` */
  selections: GalleyBracketSelection[];
  /** named in the debounced summary ("Ana selected 12 words in paragraph 3") */
  contextLabel?: string;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

type LocalRect = { left: number; top: number; right: number; bottom: number };

const BRACKET_ARM = 6; // px, horizontal foot length
const OFFSET_STEP = 3; // px, outward nesting distance per arrival index
const UNDER_GAP = 4; // px, underline distance below the line's own baseline box
const BASE_OPACITY = 0.55;
const OPACITY_STEP = 0.09;
const MIN_OPACITY = 0.22;
const DEBOUNCE_MS = 2000;

function clamp(n: number, lo: number, hi: number): number {
  return Math.max(lo, Math.min(n, hi));
}

function deriveInitials(name: string): string {
  const parts = name.trim().split(/\s+/).filter(Boolean);
  if (parts.length === 0) return "?";
  if (parts.length === 1) return (parts[0] ?? "").slice(0, 2).toUpperCase();
  return `${parts[0]?.[0] ?? ""}${parts[1]?.[0] ?? ""}`.toUpperCase();
}

function wordCount(text: string, start: number, end: number): number {
  const len = text.length;
  const s = clamp(start, 0, len);
  const e = clamp(end, s, len);
  const slice = text.slice(s, e).trim();
  return slice ? slice.split(/\s+/).length : 0;
}

function opacityFor(localIndex: number): number {
  return Math.max(MIN_OPACITY, BASE_OPACITY - localIndex * OPACITY_STEP);
}

function overlaps(a: { start: number; end: number }, b: { start: number; end: number }): boolean {
  return a.start < b.end && b.start < a.end;
}

// Groups selections whose [start,end) ranges transitively overlap, then ranks each
// member by arrival order within its own group. That local rank — not the raw
// arrivedAt value, not DOM order — is the one scalar every other visual property
// derives from (outward offset, stroke opacity).
function computeArrivalIndex(sels: GalleyBracketSelection[]): Map<string, number> {
  const n = sels.length;
  const parent = Array.from({ length: n }, (_, i) => i);
  const find = (x: number): number => {
    while (parent[x] !== x) {
      parent[x] = parent[parent[x] as number] as number;
      x = parent[x] as number;
    }
    return x;
  };
  const union = (a: number, b: number) => {
    const ra = find(a);
    const rb = find(b);
    if (ra !== rb) parent[ra] = rb;
  };
  for (let i = 0; i < n; i++) {
    for (let j = i + 1; j < n; j++) {
      const a = sels[i];
      const b = sels[j];
      if (a && b && overlaps(a, b)) union(i, j);
    }
  }
  const arrivalKey = (i: number) => sels[i]?.arrivedAt ?? i;
  const groups = new Map<number, number[]>();
  for (let i = 0; i < n; i++) {
    const r = find(i);
    const g = groups.get(r);
    if (g) g.push(i);
    else groups.set(r, [i]);
  }
  const result = new Map<string, number>();
  for (const idxs of groups.values()) {
    idxs.sort((a, b) => arrivalKey(a) - arrivalKey(b));
    idxs.forEach((idx, local) => {
      const sel = sels[idx];
      if (sel) result.set(sel.id, local);
    });
  }
  return result;
}

function toLocal(rects: DOMRect[], originLeft: number, originTop: number): LocalRect[] {
  return rects
    .filter((r) => r.width > 0 && r.height > 0)
    .map((r) => ({
      left: r.left - originLeft,
      top: r.top - originTop,
      right: r.right - originLeft,
      bottom: r.bottom - originTop,
    }))
    .sort((a, b) => a.top - b.top);
}

function BracketMark({
  rect,
  side,
  localIndex,
  opacity,
}: {
  rect: LocalRect;
  side: "open" | "close";
  localIndex: number;
  opacity: number;
}) {
  const topY = rect.top - localIndex * OFFSET_STEP;
  const footY = rect.bottom + UNDER_GAP + localIndex * OFFSET_STEP;
  const x = side === "open" ? rect.left : rect.right;
  const footX = side === "open" ? x + BRACKET_ARM : x - BRACKET_ARM;
  return (
    <>
      <line
        x1={x}
        y1={topY}
        x2={x}
        y2={footY}
        pathLength={1}
        strokeDasharray={1}
        className="ns-galley-draw"
        stroke="var(--foreground)"
        strokeWidth={1}
        strokeLinecap="round"
        opacity={opacity}
      />
      <line
        x1={x}
        y1={footY}
        x2={footX}
        y2={footY}
        pathLength={1}
        strokeDasharray={1}
        className="ns-galley-draw"
        stroke="var(--foreground)"
        strokeWidth={1}
        strokeLinecap="round"
        opacity={opacity}
      />
    </>
  );
}

export function GalleyBracket({ text, selections, contextLabel, className = "" }: GalleyBracketProps) {
  const nsRootRef = useRef<HTMLDivElement | null>(null);
  const nsMotion = useNsBind(nsRootRef as RefObject<HTMLElement | null>);
  const nsRequestFrame = nsMotion.requestFrame;
  const nsCancelFrame = nsMotion.cancelFrame;
  const nsMotionNow = nsMotion.motionNow;

  const containerRef = useRef<HTMLDivElement>(null);
  const textRef = useRef<HTMLParagraphElement>(null);

  const [size, setSize] = useState({ width: 0, height: 0 });
  const [marks, setMarks] = useState<Record<string, LocalRect[]>>({});
  const [liveMessage, setLiveMessage] = useState("");
  const reducedMotion = usePrefersReducedMotion();

  const prevSelRef = useRef<Map<string, { start: number; end: number }>>(new Map());
  const debounceTimer = useRef(0);

  const arrivalIndex = useMemo(() => computeArrivalIndex(selections), [selections]);

  const measure = useCallback(() => {
    const container = containerRef.current;
    const p = textRef.current;
    if (!container || !p) return;
    const box = container.getBoundingClientRect();
    setSize({ width: box.width, height: box.height });
    const node = p.firstChild;
    if (!(node instanceof Text)) {
      setMarks({});
      return;
    }
    const len = node.data.length;
    const next: Record<string, LocalRect[]> = {};
    for (const sel of selections) {
      const s = clamp(sel.start, 0, len);
      const e = clamp(sel.end, s, len);
      if (e <= s) continue;
      const range = document.createRange();
      try {
        range.setStart(node, s);
        range.setEnd(node, e);
        const rects = toLocal(Array.from(range.getClientRects()), box.left, box.top);
        if (rects.length) next[sel.id] = rects;
      } catch {
        // stale offsets against a text node mid-update — skip this selection's marks this frame
      }
    }
    setMarks(next);
  }, [selections]);

  useLayoutEffect(() => {
    measure();
    const container = containerRef.current;
    if (!container) return;
    const ro = new ResizeObserver(() => measure());
    ro.observe(container);
    const onResize = () => measure();
    window.addEventListener("resize", onResize);
    document.fonts?.ready?.then(() => measure()).catch(() => {});
    return () => {
      ro.disconnect();
      window.removeEventListener("resize", onResize);
    };
  }, [measure]);

  // debounced accessible summary — announces only the range that most recently
  // changed, 2s after changes stop, so a drag-selection in progress never floods
  // the live region with one announcement per pointermove.
  useEffect(() => {
    const prev = prevSelRef.current;
    let changed: GalleyBracketSelection | undefined;
    for (const sel of selections) {
      const p = prev.get(sel.id);
      if (!p || p.start !== sel.start || p.end !== sel.end) changed = sel;
    }
    prevSelRef.current = new Map(selections.map((s) => [s.id, { start: s.start, end: s.end }]));
    if (!changed) return;
    const target = changed;
    window.clearTimeout(debounceTimer.current);
    debounceTimer.current = window.setTimeout(() => {
      const words = wordCount(text, target.start, target.end);
      const where = contextLabel ? ` in ${contextLabel}` : "";
      setLiveMessage(`${target.name} selected ${words} word${words === 1 ? "" : "s"}${where}.`);
    }, DEBOUNCE_MS);
  }, [selections, text, contextLabel]);

  useEffect(() => {
    const timer = debounceTimer;
    return () => window.clearTimeout(timer.current);
  }, []);

  const jumpTo = (sel: GalleyBracketSelection) => {
    const node = textRef.current?.firstChild;
    if (!(node instanceof Text)) return;
    const len = node.data.length;
    const s = clamp(sel.start, 0, len);
    const e = clamp(sel.end, s, len);
    if (e <= s) return;
    const range = document.createRange();
    try {
      range.setStart(node, s);
      range.setEnd(node, e);
    } catch {
      return;
    }
    const live = window.getSelection();
    live?.removeAllRanges();
    live?.addRange(range);
    textRef.current?.scrollIntoView({
      block: "center",
      behavior: reducedMotion ? "auto" : "smooth",
    });
  };

  return (
    <div ref={nsRootRef} data-slot="galley-bracket" data-reduced={nsMotion.reduced ? "true" : "false"} data-motion={nsMotion.motionOn ? "on" : "off"} className={["ns-galley relative", className].filter(Boolean).join(" ")}>
      <NsPause slot="galley-bracket" />
      <style>{`
.ns-galley-draw{ stroke-dashoffset: 1; animation: ns-galley-draw-in 160ms cubic-bezier(0.16,1,0.3,1) forwards; }
@keyframes ns-galley-draw-in{ from{ stroke-dashoffset: 1; } to{ stroke-dashoffset: 0; } }
@media (prefers-reduced-motion: reduce){
  .ns-galley-draw{ animation: none !important; stroke-dashoffset: 0 !important; }
}
`}</style>

      <div ref={containerRef} className="relative py-2 pl-9 pr-2">
        <p ref={textRef} className="text-base leading-[2.2] text-foreground">
          {text}
        </p>
        <svg
          aria-hidden
          className="pointer-events-none absolute inset-0 h-full w-full overflow-visible"
          viewBox={`0 0 ${Math.max(size.width, 1)} ${Math.max(size.height, 1)}`}
          preserveAspectRatio="none"
        >
          {selections.map((sel) => {
            const rects = marks[sel.id];
            if (!rects || rects.length === 0) return null;
            const first = rects[0];
            const last = rects[rects.length - 1];
            if (!first || !last) return null;
            const local = arrivalIndex.get(sel.id) ?? 0;
            const op = opacityFor(local);
            const initials = sel.initials?.trim() || deriveInitials(sel.name);
            return (
              <g key={sel.id} data-selection={sel.id}>
                {rects.map((r, i) => {
                  const y = r.bottom + UNDER_GAP + local * OFFSET_STEP;
                  return (
                    <line
                      key={i}
                      x1={r.left}
                      y1={y}
                      x2={r.right}
                      y2={y}
                      pathLength={1}
                      strokeDasharray={1}
                      className="ns-galley-draw"
                      stroke="var(--foreground)"
                      strokeWidth={1}
                      opacity={op}
                    />
                  );
                })}
                <BracketMark rect={first} side="open" localIndex={local} opacity={op} />
                <BracketMark rect={last} side="close" localIndex={local} opacity={op} />
                <text
                  x={4}
                  y={first.top - local * OFFSET_STEP + 9}
                  className="font-mono text-[8px]"
                  fill="var(--foreground)"
                  opacity={op}
                >
                  {initials}
                </text>
              </g>
            );
          })}
        </svg>
      </div>

      <div role="status" aria-live="polite" className="sr-only">
        {liveMessage}
      </div>

      {selections.length > 0 && (
        <div className="mt-4">
          <p className="mb-1.5 font-mono text-[10px] uppercase tracking-[0.14em] text-muted-foreground">
            Active selections
          </p>
          <ul className="flex flex-wrap gap-2">
            {selections.map((sel) => {
              const words = wordCount(text, sel.start, sel.end);
              return (
                <li key={sel.id}>
                  <button
                    type="button"
                    data-jump
                    onClick={() => jumpTo(sel)}
                    className="rounded-full border border-border px-2.5 py-1 font-mono text-[11px] text-muted-foreground outline-none transition-colors hover:border-foreground/25 hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background"
                  >
                    {sel.name} · {words} word{words === 1 ? "" : "s"}
                  </button>
                </li>
              );
            })}
          </ul>
        </div>
      )}
    </div>
  );
}

