function cssName(id: string) {
  return `glow-${id.replace(/[^a-zA-Z0-9_-]/g, "")}`
}

export function GlowDivider({
  color = "var(--primary)",
  duration = 2400,
  intensity = 1,
  size = 2,
  orientation = "horizontal",
