type HaloBadgeVariant = "default" | "secondary" | "destructive" | "outline"

const rims = {
  default: {
    primary: "linear-gradient(90deg, #ff0080, #7928ca, #00d4ff, #0070f3)",
    secondary: "linear-gradient(90deg, #ff4d4d, #f9cb28, #ff0080)",
