interface CardStackProps {
  stack: StackData
  isDark: boolean
  still: boolean
}

function CardStack({ stack, isDark, still }: CardStackProps) {
  const [order, setOrder] = useState<[number, number, number]>([0, 1, 2])
  const [exitingId, setExitingId] = useState<number | null>(null)
  const [exitDir, setExitDir] = useState<'up' | 'down'>('up')
  const [returningIds, setReturningIds] = useState<Set<number>>(new Set())
  const dismissing = useRef(false)
  const orderRef = useRef(order)

  useEffect(() => {
    orderRef.current = order
  }, [order])

  const cycle = useCallback((dir: 'up' | 'down' = 'up') => {
    if (dismissing.current) return
    dismissing.current = true
    setExitDir(dir)

    const frontId = orderRef.current[0]
    setExitingId(frontId)

    const wait = still ? 0 : 380
    setTimeout(() => {
      setReturningIds(new Set([frontId]))
      setOrder(prev => [prev[1], prev[2], prev[0]])
      setExitingId(null)

      requestAnimationFrame(() => requestAnimationFrame(() => {
        setReturningIds(new Set())
        dismissing.current = false
      }))
    }, wait)
  }, [still])

  const containerHeight = CARD_H + PEEK * 2 + 4

  return (
    <div
      style={{
        position: 'relative',
        height: containerHeight,
        width: '100%',
      }}
    >
      {([0, 1, 2] as const).map((cardIndex) => {
        const slotIndex = order.indexOf(cardIndex)
        const slot = SLOTS[slotIndex]
        if (!slot) return null
        const isExiting = exitingId === cardIndex
        const isReturning = returningIds.has(cardIndex)
        const isFront = slotIndex === 0

        const animTarget = isExiting
          ? { y: exitDir === 'down' ? 160 : -160, scale: 0.88, opacity: 0 }
          : { y: slot.y, scale: slot.scale, opacity: 1 }

        // The exit duration must equal the 380 ms timeout in cycle().
        const animTransition = still || isReturning
          ? { duration: 0 }
          : isExiting
            ? { duration: 0.38, ease: [0.4, 0, 0.2, 1] as [number, number, number, number] }
            : { type: 'spring' as const, stiffness: 280, damping: 26 }

        return (
          <motion.div
            key={cardIndex}
            animate={animTarget}
            transition={animTransition}
            drag={isFront ? 'y' : false}
            dragConstraints={{ top: 0, bottom: 0 }}
            dragElastic={0.2}
            onDragEnd={(_, info) => {
              if (Math.abs(info.offset.y) > 60 || Math.abs(info.velocity.y) > 400) {
                cycle(info.offset.y > 0 ? 'down' : 'up')
              }
            }}
            whileHover={isFront ? { y: slot.y - 4, transition: { type: 'spring', stiffness: 300, damping: 24 } } : {}}
            style={{
              position: 'absolute',
              left: 0,
              right: 0,
              top: 0,
              zIndex: isExiting ? 10 : slot.z,
              transformOrigin: 'center top',
              cursor: isFront ? 'grab' : 'default',
            }}
          >
            <SingleCard
              card={stack.cards[cardIndex]}
              stack={stack}
              isDark={isDark}
              isFront={isFront}
              frontIndex={order[0]}
              onCycle={cycle}
            />
          </motion.div>
        )
      })}
    </div>
  )
}

export interface AiJobCardsProps {
  stacks?: readonly StackData[]
  className?: string
}

export function AiJobCards({ stacks = defaultJobStacks, className }: AiJobCardsProps = {}) {
  const containerRef = useRef<HTMLDivElement>(null)
  const reduced = usePrefersReducedMotion()
  const live = useAnimationActive(containerRef)
  const still = reduced || !live
  const isDark = useIsDark(containerRef)
  const [narrow, setNarrow] = useState(false)

  useEffect(() => {
    const el = containerRef.current
    if (!el) return
    const obs = new ResizeObserver(entries => {
      for (const entry of entries) {
        setNarrow(entry.contentRect.width < 480)
      }
    })
    obs.observe(el)
    return () => obs.disconnect()
  }, [])

  const outerBg = isDark ? '#0d0d0c' : '#CADBDD'

  return (
    <div
      ref={containerRef}
      data-reduced={reduced ? "true" : "false"}
      data-motion={still ? "off" : "on"}
      className={`flex min-h-[32rem] w-full items-center justify-center motion-reduce:transition-none ${className ?? ""}`}
      style={{ background: outerBg }}
    >
      <div
        style={{
          width: '100%',
          padding: 'clamp(16px, 5%, 40px)',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
        }}
      >
        <div
          style={{
            display: 'flex',
            flexDirection: narrow ? 'column' : 'row',
            gap: 16,
            width: '100%',
            maxWidth: 760,
            alignItems: narrow ? 'stretch' : 'flex-start',
          }}
        >
          {stacks.map((stack) => (
            <div key={stack.company} style={{ flex: 1, minWidth: 0 }}>
              <CardStack stack={stack} isDark={isDark} still={still} />
            </div>
          ))}
        </div>
      </div>
    </div>
  )
}

"use client"

import { useVirtualizer } from "@tanstack/react-virtual"
import * as React from "react"

import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { cn } from "@/lib/utils"

export interface JsonViewerProps {
  data?: unknown
  className?: string
}

type JsonType = "object" | "array" | "string" | "number" | "boolean" | "null"

interface JsonRow {
  path: string
  keyLabel: string
  type: JsonType
  preview: string
  depth: number
  expandable: boolean
  raw: unknown
}

const SAMPLE = {
  name: "effect-ui",
  version: 1,
  active: true,
  note: null,
  items: Array.from({ length: 48 }, (_, index) => ({
    id: index + 1,
    name: `资源 ${index + 1}`,
    score: (index * 7) % 100,
    active: index % 3 !== 0,
  })),
}

function kindOf(value: unknown): JsonType {
  if (value === null) return "null"
  if (Array.isArray(value)) return "array"
  if (typeof value === "object") return "object"
  if (typeof value === "string") return "string"
  if (typeof value === "number") return "number"
  return "boolean"
}

function previewOf(value: unknown, type: JsonType) {
  if (type === "string") return JSON.stringify(value)
  if (type === "array") return `Array(${(value as unknown[]).length})`
  if (type === "object") return `Object(${Object.keys(value as object).length})`
  if (type === "null") return "null"
  return String(value)
}

function childPath(parent: string, key: string) {
  if (/^\d+$/.test(key)) return `${parent}[${key}]`
  if (/^[A-Za-z_$][\w$]*$/.test(key)) return `${parent}.${key}`
  return `${parent}[${JSON.stringify(key)}]`
}

function matchesQuery(path: string, preview: string, query: string) {
  if (!query) return false
  const needle = query.toLowerCase()
  return path.toLowerCase().includes(needle) || preview.toLowerCase().includes(needle)
}

function collect(
  value: unknown,
  path: string,
  keyLabel: string,
  depth: number,
  expanded: ReadonlySet<string>,
  query: string,
): { rows: JsonRow[]; hit: boolean } {
  const type = kindOf(value)
  const preview = previewOf(value, type)
  const expandable = type === "object" || type === "array"
  const selfHit = matchesQuery(path, preview, query)
  const row: JsonRow = { path, keyLabel, type, preview, depth, expandable, raw: value }
  if (!expandable) return { rows: query && !selfHit ? [] : [row], hit: selfHit || !query }
  const entries = Array.isArray(value)
    ? value.map((item, index) => [String(index), item] as const)
    : Object.entries(value as Record<string, unknown>)
  const children = entries.map(([key, child]) => collect(child, childPath(path, key), key, depth + 1, expanded, query))
  const childHit = children.some((child) => child.hit)
  const hit = selfHit || childHit
  if (query && !hit) return { rows: [], hit: false }
  const open = expanded.has(path) || (query.length > 0 && childHit)
  const rows = [row]
  if (open) {
    for (const child of children) rows.push(...child.rows)
  }
  return { rows, hit: hit || !query }
}

const TYPE_CLASS: Record<JsonType, string> = {
  string: "text-emerald-600 dark:text-emerald-300",
  number: "text-sky-600 dark:text-sky-300",
  boolean: "text-amber-600 dark:text-amber-300",
  null: "text-muted-foreground",
  object: "text-foreground",
  array: "text-foreground",
}

function highlight(text: string, query: string) {
  if (!query) return text
  const lower = text.toLowerCase()
  const needle = query.toLowerCase()
  const parts: React.ReactNode[] = []
  let cursor = 0
  while (cursor < text.length) {
    const at = lower.indexOf(needle, cursor)
    if (at < 0) {
      parts.push(text.slice(cursor))
      break
    }
    if (at > cursor) parts.push(text.slice(cursor, at))
    parts.push(
      <mark key={`${at}-${cursor}`} className="rounded-sm bg-amber-300/70 text-inherit">
        {text.slice(at, at + needle.length)}
      </mark>,
    )
    cursor = at + needle.length
  }
  return parts
}

function JsonViewer({ data = SAMPLE, className }: JsonViewerProps) {
  const reduced = usePrefersReducedMotion()
  const parentRef = React.useRef<HTMLDivElement>(null)
  const [expanded, setExpanded] = React.useState<Set<string>>(() => new Set(["$", "$.items"]))
  const [query, setQuery] = React.useState("")
  const [notice, setNotice] = React.useState("")
  const tree = collect(data, "$", "$", 0, expanded, query.trim())
  const rows = tree.rows
  const virtualizer = useVirtualizer({
    count: rows.length,
    getScrollElement: () => parentRef.current,
    estimateSize: () => 32,
    overscan: 8,
  })

  const copyText = (text: string) => {
    void navigator.clipboard.writeText(text).then(
      () => setNotice("已复制"),
      () => setNotice("复制失败"),
    )
  }

  const toggle = (path: string) => {
    setExpanded((current) => {
      const next = new Set(current)
      if (next.has(path)) next.delete(path)
      else next.add(path)
      return next
    })
  }

  return (
    <div data-slot="json-viewer" className={cn("w-full space-y-2", className)}>
      <div className="flex items-center justify-between gap-3">
        <label className="text-sm">
          搜索
          <input
            value={query}
            onChange={(event) => setQuery(event.target.value)}
            className="ml-2 rounded-md border bg-background px-2 py-1 text-sm"
            placeholder="路径或值"
          />
        </label>
        <p className="text-xs text-muted-foreground" aria-live="polite">
          {notice || `${rows.length} 行`}
        </p>
      </div>
      <div ref={parentRef} className="h-80 overflow-auto rounded-xl border">
        <div className="relative w-full" style={{ height: virtualizer.getTotalSize() }}>
          {virtualizer.getVirtualItems().map((virtualRow) => {
            const row = rows[virtualRow.index]
            if (!row) return null
            const open = expanded.has(row.path) || (query.trim().length > 0 && row.expandable)
            return (
              <div
                key={row.path}
                className="absolute top-0 left-0 flex w-full items-center gap-2 px-2 text-xs"
                style={{ height: virtualRow.size, transform: `translateY(${virtualRow.start}px)` }}
              >
                <span style={{ width: row.depth * 14 }} />
                {row.expandable ? (
                  <button
                    type="button"
                    aria-expanded={open}
                    className="w-5 shrink-0 rounded outline-none focus-visible:ring-2 focus-visible:ring-primary"
                    onClick={() => toggle(row.path)}
                  >
                    {open ? "▾" : "▸"}
                  </button>
                ) : (
                  <span className="w-5 shrink-0" />
                )}
                <span className="truncate font-medium">{highlight(row.keyLabel, query.trim())}</span>
                <span className={cn("truncate", TYPE_CLASS[row.type])}>{highlight(row.preview, query.trim())}</span>
                <span className="ml-auto flex shrink-0 gap-1">
                  <button type="button" className="rounded border px-1.5 py-0.5" onClick={() => copyText(row.path)}>
                    路径
                  </button>
                  <button
                    type="button"
                    className="rounded border px-1.5 py-0.5"
                    onClick={() =>
                      copyText(row.type === "object" || row.type === "array" ? JSON.stringify(row.raw) : row.preview)
                    }
                  >
                    值
                  </button>
                </span>
              </div>
            )
          })}
        </div>
      </div>
      <p className="text-xs text-muted-foreground">{reduced ? "列表直接展开，没有过渡。" : "长列表按可见区域渲染。"}</p>
    </div>
  )
}

export { JsonViewer }

"use client"

// Ported from SmoothUI (MIT) — https://github.com/educlopez/smoothui/blob/main/packages/smoothui/components/kinetic-type-scroll/index.tsx


import { useAnimationActive } from "@/hooks/use-animation-active"
import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { cn } from "@/lib/utils"
import {
  type MotionValue,
  motion,
  useScroll,
  useSpring,
  useTransform,
} from "motion/react";
import type { RefObject } from "react";
import { useRef } from "react";

export type KineticTypeScrollAlign = "start" | "center" | "end";

type UseScrollOptions = Parameters<typeof useScroll>[0];
export type ScrollOffsetTuple = NonNullable<UseScrollOptions>["offset"];

export interface KineticTypeScrollProps {
  align?: KineticTypeScrollAlign;
  className?: string;
  /** Scrollable ancestor whose progress drives the effect. */
  container?: RefObject<HTMLElement | null>;
  /** Opacity at rest vs. at each word's peak. */
  dimRange?: [number, number];
  /** Vertical offset in px at rest vs. at each word's peak. */
  liftRange?: [number, number];
  /** Motion scroll offset tuple, forwarded to `useScroll`. */
  offset?: ScrollOffsetTuple;
  /** Scale applied at rest vs. at each word's peak. */
  scaleRange?: [number, number];
  /** Fractional offset between each word's active scroll window (0-1). */
  stagger?: number;
  /** Letter-spacing in px at rest vs. at each word's peak. */
  trackingRange?: [number, number];
  /**
   * `font-variation-settings` "wght" at rest vs. at each word's peak.
   * Only visible when the active font is a variable font.
   */
  weightRange?: [number, number];
  words: string[];
}

interface KineticWordProps {
  dimRange: [number, number];
  index: number;
  liftRange: [number, number];
  motionOn: boolean;
  progress: MotionValue<number>;
  scaleRange: [number, number];
  shouldReduceMotion: boolean;
  stagger: number;
  total: number;
  trackingRange: [number, number];
  weightRange: [number, number];
  word: string;
}

const ALIGN_ROW_CLASS: Record<KineticTypeScrollAlign, string> = {
  center: "justify-center",
  end: "justify-end",
  start: "justify-start",
};

const DEFAULT_SCALE_RANGE: [number, number] = [0.92, 1.18];
const DEFAULT_TRACKING_RANGE: [number, number] = [-0.5, 2.5];
const DEFAULT_WEIGHT_RANGE: [number, number] = [380, 800];
const DEFAULT_LIFT_RANGE: [number, number] = [0, -12];
// Never fully dark: the phrase stays readable at rest and the crest is what
// lights it, so the wave is legible without the line ever going missing.
const DEFAULT_DIM_RANGE: [number, number] = [0.45, 1];
const DEFAULT_STAGGER = 0.12;
/**
 * Head- and tail-room at both ends of the scroll range: the wave starts after
 * the phrase has settled into view and ends before it leaves, so there is time
 * to read the line on either side of the effect.
 */
const WAVE_MARGIN = 0.14;
/**
 * Each word's active window as a multiple of the gap between peaks. Above 1 the
 * windows overlap, which is what turns a row of individual pulses into a single
 * wave travelling through the phrase.
 */
const WINDOW_OVERLAP = 1.2;
const MIN_WINDOW = 0.09;
const INTENSITY_MIDPOINT = 1;
const INTENSITY_SCALE = 2;
// A soft, near-critically-damped spring: the wave should read as one moving
// crest, not as each word snapping.
const SPRING_TRANSITION = {
  bounce: 0,
  duration: 0.32,
  type: "spring" as const,
};

/** Motion default (`["start start", "end end"]`) collapses on an element
 * shorter than its scroller, which left the whole effect stuck near 0. This
 * window opens as the phrase enters the lower part of the viewport and closes
 * around the time it reaches the middle. */
const DEFAULT_OFFSET = ["start 0.9", "end 0.45"] as ScrollOffsetTuple;

const KineticWord = ({
  word,
  dimRange,
  index,
  liftRange,
  motionOn,
  progress,
  scaleRange,
  shouldReduceMotion,
  stagger,
  total,
  trackingRange,
  weightRange,
}: KineticWordProps) => {
  const gaps = Math.max(1, total - 1);
  // Peaks are evenly spaced and the whole wave is centred in the range, so a
  // short phrase does not crowd into the first third of the scroll.
  const spacing = Math.min(stagger, (1 - 2 * WAVE_MARGIN) / gaps);
  const waveStart = (1 - spacing * gaps) / 2;
  const center = waveStart + spacing * index;
  const halfWindow = Math.max(spacing * WINDOW_OVERLAP, MIN_WINDOW);
  const start = center - halfWindow;
  const end = center + halfWindow;

  const localProgress = useTransform(progress, [start, end], [0, 1], {
    clamp: true,
  });
  const intensity = useTransform(
    localProgress,
    (value) => INTENSITY_MIDPOINT - Math.abs(value * INTENSITY_SCALE - 1)
  );
  const rawScale = useTransform(intensity, [0, 1], scaleRange);
  const rawTracking = useTransform(intensity, [0, 1], trackingRange);
  const rawWeight = useTransform(intensity, [0, 1], weightRange);
  const rawLift = useTransform(intensity, [0, 1], liftRange);
  const rawOpacity = useTransform(intensity, [0, 1], dimRange);
  const scale = useSpring(rawScale, SPRING_TRANSITION);
  const trackingValue = useSpring(rawTracking, SPRING_TRANSITION);
  const weight = useSpring(rawWeight, SPRING_TRANSITION);
  const y = useSpring(rawLift, SPRING_TRANSITION);
  const opacity = useSpring(rawOpacity, SPRING_TRANSITION);
  const letterSpacing = useTransform(trackingValue, (value) => `${value}px`);
  const fontVariationSettings = useTransform(
    weight,
    (value) => `"wght" ${Math.round(value)}`
  );

  if (shouldReduceMotion) {
    // No travel and no dimming — the phrase simply reads at its peak weight.
    return (
      <span
        aria-hidden="true"
        className="inline-block"
        style={{ fontVariationSettings: `"wght" ${weightRange[1] ?? 800}` }}
      >
        {word}
      </span>
    );
  }

  if (!motionOn) {
    return (
      <span
        aria-hidden="true"
        className="inline-block"
        style={{
          fontVariationSettings: `"wght" ${weightRange[0] ?? 380}`,
          letterSpacing: `${trackingRange[0] ?? 0}px`,
          opacity: dimRange[0] ?? 1,
          transform: `translateY(${liftRange[0] ?? 0}px) scale(${scaleRange[0] ?? 1})`,
        }}
      >
        {word}
      </span>
    );
  }

  return (
    <motion.span
      aria-hidden="true"
      className="inline-block will-change-transform"
      style={{ fontVariationSettings, letterSpacing, opacity, scale, y }}
    >
      {word}
    </motion.span>
  );
};

/**
 * KineticTypeScroll — editorial kinetic typography driven by scroll.
 * Each word maps a slice of scroll progress to its own scale, tracking
 * and weight curve so the phrase breathes as the section scrolls.
 */
export function KineticTypeScroll({
  words,
  align = "center",
  className,
  container,
  dimRange = DEFAULT_DIM_RANGE,
  liftRange = DEFAULT_LIFT_RANGE,
  offset = DEFAULT_OFFSET,
  scaleRange = DEFAULT_SCALE_RANGE,
  stagger = DEFAULT_STAGGER,
  trackingRange = DEFAULT_TRACKING_RANGE,
  weightRange = DEFAULT_WEIGHT_RANGE,
}: KineticTypeScrollProps) {
  const wrapperRef = useRef<HTMLDivElement>(null);
  const shouldReduceMotion = usePrefersReducedMotion();
  const motionOn = useAnimationActive(wrapperRef);
  const { scrollYProgress } = useScroll({
    container,
    offset,
    target: wrapperRef,
  });

  return (
    <div
      className={cn(
        // Gaps are in `em` and sized to clear the peak scale: `scale` is a
        // transform, so a magnified word overflows its layout box and a fixed
        // 8px gutter lets the crest collide with its neighbours.
        "flex flex-wrap gap-x-[0.4em] gap-y-[0.18em]",
        ALIGN_ROW_CLASS[align],
        className
      )}
      data-reduced={shouldReduceMotion ? "true" : "false"}
      data-slot="kinetic-type-scroll"
      ref={wrapperRef}
    >
      {/* Every glyph below is aria-hidden, so the readable copy lives here. An
          aria-label on this plain div would be dropped by assistive tech. */}
      <span className="sr-only">{words.join(" ")}</span>
      {words.map((word, index) => (
        <KineticWord
          dimRange={dimRange}
          index={index}
          // biome-ignore lint/suspicious/noArrayIndexKey: words may repeat and have no stable id
          key={index}
          liftRange={liftRange}
          motionOn={motionOn}
          progress={scrollYProgress}
          scaleRange={scaleRange}
          shouldReduceMotion={!!shouldReduceMotion}
          stagger={stagger}
          total={words.length}
          trackingRange={trackingRange}
          weightRange={weightRange}
          word={word}
        />
      ))}
    </div>
  );
}

