  active,
  color,
  transition,
}: {
  active: boolean;
  color: string;
  transition: Transition;
}) => (
  <motion.path
    animate={{ d: active ? STOP_PATH : PLAY_PATH }}
    fill={color}
    stroke="none"
    transition={transition}
  />
