export interface InputProps extends Omit<InputHTMLAttributes<HTMLInputElement>, "size"> {
  label: string
}

export function Input({ label, id, className, ...props }: InputProps) {
  const reduced = usePrefersReducedMotion()
  const autoId = useId()
