};

const PixelBrushCanvas = ({
  brush,
  className,
  color,
  grid = false,
  height = DEFAULT_GRID_HEIGHT,
  initial,
  onBrushChange,
  onChange,
  onColorChange,
  palette = DEFAULT_PALETTE,
  pixelSize = DEFAULT_PIXEL_SIZE,
  ref,
  showTools = true,
  width = DEFAULT_GRID_WIDTH,
}: PixelBrushCanvasProps) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const wrapperRef = useRef<HTMLDivElement>(null);
  const pixelsRef = useRef<Uint8Array>(
    createInitialPixels(width, height, initial)
  );
  const undoStackRef = useRef<Uint8Array[]>([]);
  const isPaintingRef = useRef(false);
  const lastPaintedRef = useRef<Cell | null>(null);
  const dragStartRef = useRef<Cell | null>(null);
  const anchorRef = useRef<Cell | null>(null);

  const shouldReduceMotion = usePrefersReducedMotion();
  const [colorDraft, setColorDraft] = useState<{ prop: number | undefined; value: number } | null>(null);
  const [brushDraft, setBrushDraft] = useState<{
    prop: PixelBrushCanvasBrush | undefined;
    value: PixelBrushCanvasBrush;
  } | null>(null);
  const internalColor = colorDraft && Object.is(colorDraft.prop, color) ? colorDraft.value : (color ?? 0);
  const internalBrush =
    brushDraft && Object.is(brushDraft.prop, brush) ? brushDraft.value : (brush ?? "pencil");
  const setInternalColor = (next: number) => setColorDraft({ prop: color, value: next });
  const setInternalBrush = (next: PixelBrushCanvasBrush) => setBrushDraft({ prop: brush, value: next });
  const [cursor, setCursor] = useState<Cell>({ x: 0, y: 0 });
  const [announcement, setAnnouncement] = useState("");

  useLayoutEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) {
      return;
    }
    if (pixelsRef.current.length !== width * height) {
      pixelsRef.current = createInitialPixels(width, height, initial);
      undoStackRef.current = [];
    }
    const dpr = Math.min(window.devicePixelRatio || 1, MAX_DEVICE_PIXEL_RATIO);
    const cssWidth = width * pixelSize;
    const cssHeight = height * pixelSize;
    canvas.style.width = `${cssWidth}px`;
    canvas.style.height = `${cssHeight}px`;
    canvas.width = Math.round(cssWidth * dpr);
    canvas.height = Math.round(cssHeight * dpr);
    const ctx = canvas.getContext("2d");
    if (!ctx) {
      return;
    }
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    drawRegion(
      ctx,
      pixelsRef.current,
      width,
      height,
      pixelSize,
      palette,
      grid,
      {
        maxX: width - 1,
        maxY: height - 1,
        minX: 0,
        minY: 0,
      }
    );
  }, [width, height, pixelSize, palette, grid, initial]);

  const redrawRegion = useCallback(
    (box: BoundingBox) => {
      const ctx = canvasRef.current?.getContext("2d");
      if (!ctx) {
        return;
      }
      drawRegion(
        ctx,
        pixelsRef.current,
        width,
        height,
        pixelSize,
        palette,
        grid,
        box
      );
    },
    [width, height, pixelSize, palette, grid]
  );

  const notifyChange = useCallback(() => {
    onChange?.(pixelsRef.current.slice());
  }, [onChange]);

  const pushUndoSnapshot = useCallback(() => {
    const stack = undoStackRef.current;
    if (stack.length >= MAX_UNDO_STEPS) {
      stack.shift();
    }
    stack.push(pixelsRef.current.slice());
  }, []);

  const announceFocusedCell = (x: number, y: number) => {
    const value = pixelsRef.current[y * width + x];
    setAnnouncement(
      `Column ${x + 1}, row ${y + 1}. Color: ${describeValue(value!, palette)}.`
    );
  };

  const setCellValue = (x: number, y: number, value: number): boolean => {
    if (pixelsRef.current[y * width + x] === value) {
      return false;
    }
    pixelsRef.current[y * width + x] = value;
    redrawRegion({ maxX: x, maxY: y, minX: x, minY: y });
    return true;
  };

  const commitCells = (cells: Cell[], value: number) => {
    pushUndoSnapshot();
    let changed = false;
    const box: BoundingBox = { maxX: -1, maxY: -1, minX: width, minY: height };
    for (const cell of cells) {
      if (cell.x < 0 || cell.x >= width || cell.y < 0 || cell.y >= height) {
        continue;
      }
      if (pixelsRef.current[cell.y * width + cell.x] === value) {
        continue;
      }
      pixelsRef.current[cell.y * width + cell.x] = value;
      changed = true;
      box.minX = Math.min(box.minX, cell.x);
      box.minY = Math.min(box.minY, cell.y);
      box.maxX = Math.max(box.maxX, cell.x);
      box.maxY = Math.max(box.maxY, cell.y);
    }
    if (changed) {
      redrawRegion(box);
      notifyChange();
    } else {
      undoStackRef.current.pop();
    }
  };

  const applyFillAt = (x: number, y: number) => {
    pushUndoSnapshot();
    const box = floodFillIterative(
      pixelsRef.current,
      width,
      height,
      x,
      y,
      internalColor + 1
    );
    if (box) {
      redrawRegion(box);
      notifyChange();
    } else {
      undoStackRef.current.pop();
    }
  };

  const clear = useCallback(() => {
    pushUndoSnapshot();
    pixelsRef.current.fill(EMPTY_CELL_VALUE);
    redrawRegion({ maxX: width - 1, maxY: height - 1, minX: 0, minY: 0 });
    notifyChange();
  }, [width, height, pushUndoSnapshot, redrawRegion, notifyChange]);

  const undo = useCallback(() => {
    const snapshot = undoStackRef.current.pop();
    if (!snapshot) {
      return;
    }
    pixelsRef.current = snapshot;
    redrawRegion({ maxX: width - 1, maxY: height - 1, minX: 0, minY: 0 });
    notifyChange();
  }, [width, height, redrawRegion, notifyChange]);

  useImperativeHandle(
    ref,
    () => ({
      clear,
      getPixels: () => pixelsRef.current.slice(),
      toDataURL: () => canvasRef.current?.toDataURL() ?? "",
      undo,
    }),
    [clear, undo]
  );

  const selectBrush = (next: PixelBrushCanvasBrush) => {
    setInternalBrush(next);
    anchorRef.current = null;
    onBrushChange?.(next);
  };

  const selectColor = (index: number) => {
    setInternalColor(index);
    onColorChange?.(index);
  };

  const handlePointerDown = (event: ReactPointerEvent<HTMLCanvasElement>) => {
    const rect = event.currentTarget.getBoundingClientRect();
    const cell = getCellFromPoint(
      event.clientX,
      event.clientY,
      rect,
      width,
      height,
      pixelSize
    );
    wrapperRef.current?.focus();
    setCursor(cell);

    if (internalBrush === "pencil" || internalBrush === "eraser") {
      event.currentTarget.setPointerCapture(event.pointerId);
      isPaintingRef.current = true;
      lastPaintedRef.current = null;
      pushUndoSnapshot();
      const value =
        internalBrush === "eraser" ? EMPTY_CELL_VALUE : internalColor + 1;
      if (setCellValue(cell.x, cell.y, value)) {
        notifyChange();
      } else {
        undoStackRef.current.pop();
      }
      lastPaintedRef.current = cell;
    } else if (internalBrush === "fill") {
      applyFillAt(cell.x, cell.y);
    } else {
      dragStartRef.current = cell;
    }
    announceFocusedCell(cell.x, cell.y);
  };

  const handlePointerMove = (event: ReactPointerEvent<HTMLCanvasElement>) => {
    if (!isPaintingRef.current) {
      return;
    }
    const rect = event.currentTarget.getBoundingClientRect();
    const cell = getCellFromPoint(
      event.clientX,
      event.clientY,
      rect,
      width,
      height,
      pixelSize
    );
    const last = lastPaintedRef.current;
    if (last && last.x === cell.x && last.y === cell.y) {
      return;
    }
    const value =
      internalBrush === "eraser" ? EMPTY_CELL_VALUE : internalColor + 1;
    if (setCellValue(cell.x, cell.y, value)) {
      notifyChange();
    }
    lastPaintedRef.current = cell;
    setCursor(cell);
  };

  const handlePointerUp = (event: ReactPointerEvent<HTMLCanvasElement>) => {
    if (isPaintingRef.current) {
      isPaintingRef.current = false;
      lastPaintedRef.current = null;
      if (event.currentTarget.hasPointerCapture(event.pointerId)) {
        event.currentTarget.releasePointerCapture(event.pointerId);
      }
      return;
    }
    const start = dragStartRef.current;
    if (start && (internalBrush === "line" || internalBrush === "rect")) {
      const rect = event.currentTarget.getBoundingClientRect();
      const end = getCellFromPoint(
        event.clientX,
        event.clientY,
        rect,
        width,
        height,
        pixelSize
      );
      const cells =
        internalBrush === "line"
          ? getLineCells(start, end)
          : getRectOutlineCells(start, end);
      commitCells(cells, internalColor + 1);
      announceFocusedCell(end.x, end.y);
    }
    dragStartRef.current = null;
  };

  const moveCursor = (dx: number, dy: number) => {
    const nextX = clamp(cursor.x + dx, 0, width - 1);
    const nextY = clamp(cursor.y + dy, 0, height - 1);
    setCursor({ x: nextX, y: nextY });
    announceFocusedCell(nextX, nextY);
  };

  const paintAtCursor = () => {
    if (internalBrush === "pencil" || internalBrush === "eraser") {
      pushUndoSnapshot();
      const value =
        internalBrush === "eraser" ? EMPTY_CELL_VALUE : internalColor + 1;
      if (setCellValue(cursor.x, cursor.y, value)) {
        notifyChange();
      } else {
        undoStackRef.current.pop();
      }
      announceFocusedCell(cursor.x, cursor.y);
    } else if (internalBrush === "fill") {
      applyFillAt(cursor.x, cursor.y);
      announceFocusedCell(cursor.x, cursor.y);
    } else {
      const anchor = anchorRef.current;
      if (!anchor) {
        anchorRef.current = { x: cursor.x, y: cursor.y };
        setAnnouncement(
          `Anchor set at column ${cursor.x + 1}, row ${cursor.y + 1}. Move and press space again to finish.`
        );
        return;
      }
      const cells =
        internalBrush === "line"
          ? getLineCells(anchor, cursor)
          : getRectOutlineCells(anchor, cursor);
      commitCells(cells, internalColor + 1);
      anchorRef.current = null;
      announceFocusedCell(cursor.x, cursor.y);
    }
  };

  const handleKeyDown = (event: ReactKeyboardEvent<HTMLDivElement>) => {
    const isUndoShortcut =
      (event.metaKey || event.ctrlKey) && event.key.toLowerCase() === "z";
    if (isUndoShortcut) {
      event.preventDefault();
      undo();
      return;
    }
    switch (event.key) {
      case "ArrowUp": {
        event.preventDefault();
        moveCursor(0, -1);
        return;
      }
      case "ArrowDown": {
        event.preventDefault();
        moveCursor(0, 1);
        return;
      }
      case "ArrowLeft": {
        event.preventDefault();
        moveCursor(-1, 0);
        return;
      }
      case "ArrowRight": {
        event.preventDefault();
        moveCursor(1, 0);
        return;
      }
      case " ":
      case "Spacebar": {
        event.preventDefault();
        paintAtCursor();
        return;
      }
      default:
        break;
    }
    const lowerKey = event.key.toLowerCase();
    if (lowerKey === "e") {
      selectBrush("eraser");
    } else if (lowerKey === "b") {
      selectBrush("pencil");
    } else if (lowerKey === "g") {
      selectBrush("fill");
    }
  };

  return (
    <div className={cn("inline-flex flex-col gap-3", className)} data-reduced={shouldReduceMotion ? "true" : "false"} data-slot="pixel-brush-canvas">
      <div className="inline-block rounded-lg border border-border bg-muted/40 p-2">
        {/* biome-ignore lint/a11y/noNoninteractiveElementInteractions: role="application" is the keyboard-operable pixel grid; no semantic element models 2D arrow-key navigation */}
        <div
          aria-label="Pixel art drawing canvas"
          className="relative inline-block rounded-sm outline-none focus-visible:ring-2 focus-visible:ring-brand"
          onKeyDown={handleKeyDown}
          ref={wrapperRef}
          role="application"
          // biome-ignore lint/a11y/noNoninteractiveTabindex: role="application" must be focusable to be keyboard-operable
          tabIndex={0}
        >
          <canvas
            className="block touch-none rounded-sm"
            onPointerDown={handlePointerDown}
            onPointerLeave={handlePointerUp}
            onPointerMove={handlePointerMove}
            onPointerUp={handlePointerUp}
            ref={canvasRef}
          />
          <div
            aria-hidden="true"
            className="pointer-events-none absolute border-2 border-brand"
            style={{
              height: pixelSize,
              left: cursor.x * pixelSize,
              top: cursor.y * pixelSize,
              width: pixelSize,
            }}
          />
          <span aria-live="polite" className="sr-only">
            {announcement}
          </span>
        </div>
      </div>
      {showTools ? (
        <ToolPalette
          brush={internalBrush}
          colorIndex={internalColor}
          onSelectBrush={selectBrush}
          onSelectColor={selectColor}
          palette={palette}
        />
      ) : null}
    </div>
  );
};

export { PixelBrushCanvas }

"use client"

import * as React from "react"

import { useAnimationActive } from "@/hooks/use-animation-active"
import { cn } from "@/lib/utils"

export interface PixelCanvasCardProps {
  className?: string
  colors?: string[]
  gap?: number
  speed?: number
  children?: React.ReactNode
}

class Pixel {
  x: number
  y: number
  color: string
  speed: number
  size = 0
  sizeStep = Math.random() * 0.4
  minSize = 0.5
  maxSize: number
  delay: number
  counter = 0
  counterStep: number
  isIdle = false
  isReverse = false
  isShimmer = false

  constructor(width: number, height: number, x: number, y: number, color: string, speed: number, delay: number) {
    this.x = x
    this.y = y
    this.color = color
    this.speed = (Math.random() * 0.8 + 0.1) * speed
    this.maxSize = Math.random() * 1.5 + 0.5
    this.delay = delay
    this.counterStep = Math.random() * 4 + (width + height) * 0.01
  }

  draw(ctx: CanvasRenderingContext2D) {
    const offset = 1 - this.size * 0.5
    ctx.fillStyle = this.color
    ctx.fillRect(this.x + offset, this.y + offset, this.size, this.size)
  }

  appear(ctx: CanvasRenderingContext2D) {
    this.isIdle = false
    if (this.counter <= this.delay) {
      this.counter += this.counterStep
      return
    }
    if (this.size >= this.maxSize) this.isShimmer = true
    if (this.isShimmer) this.shimmer()
    else this.size += this.sizeStep
    this.draw(ctx)
  }

  disappear(ctx: CanvasRenderingContext2D) {
    this.isShimmer = false
    this.counter = 0
    if (this.size <= 0) {
      this.isIdle = true
      return
    }
    this.size -= 0.1
    this.draw(ctx)
  }

  shimmer() {
    if (this.size >= this.maxSize) this.isReverse = true
    else if (this.size <= this.minSize) this.isReverse = false
    this.size += this.isReverse ? -this.speed : this.speed
  }
}

function PixelCanvasCard({
  className,
  colors = ["#e0f2fe", "#7dd3fc", "#0ea5e9"],
  gap = 6,
  speed = 35,
  children,
}: PixelCanvasCardProps) {
  const canvasRef = React.useRef<HTMLCanvasElement>(null)
  const active = useAnimationActive(canvasRef)
  const pixels = React.useRef<Pixel[]>([])
  const mode = React.useRef<"appear" | "disappear" | null>(null)

  React.useEffect(() => {
    const canvas = canvasRef.current
    if (!canvas) return
    const ctx = canvas.getContext("2d")
    if (!ctx) return
    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches
    const clampedGap = Math.min(50, Math.max(4, gap))
    const pixelSpeed = reduced ? 0 : Math.min(100, Math.max(0, speed)) * 0.001

    const init = () => {
      const rect = canvas.getBoundingClientRect()
      canvas.width = Math.floor(rect.width)
      canvas.height = Math.floor(rect.height)
      pixels.current = []
      for (let x = 0; x < canvas.width; x += clampedGap) {
        for (let y = 0; y < canvas.height; y += clampedGap) {
          const color = colors[Math.floor(Math.random() * colors.length)] ?? "#e0f2fe"
          const delay = reduced ? 0 : Math.hypot(x - canvas.width / 2, y - canvas.height / 2)
          pixels.current.push(new Pixel(canvas.width, canvas.height, x, y, color, pixelSpeed, delay))
        }
      }
    }

    init()
    const observer = new ResizeObserver(init)
    observer.observe(canvas)
    if (!active) {
      return () => observer.disconnect()
    }
    let frame = 0
    const tick = () => {
      const current = mode.current
      if (current) {
        ctx.clearRect(0, 0, canvas.width, canvas.height)
        for (const pixel of pixels.current) pixel[current](ctx)
        if (pixels.current.every((pixel) => pixel.isIdle)) mode.current = null
      }
      frame = window.requestAnimationFrame(tick)
    }
    frame = window.requestAnimationFrame(tick)
    return () => {
      observer.disconnect()
      window.cancelAnimationFrame(frame)
    }
  }, [colors, gap, speed, active])

  return (
    <div
      className={cn("relative overflow-hidden rounded-xl border bg-card", className)}
      onMouseEnter={() => {
        mode.current = "appear"
      }}
      onMouseLeave={() => {
        mode.current = "disappear"
      }}
      onFocus={() => {
        mode.current = "appear"
      }}
      onBlur={() => {
        mode.current = "disappear"
      }}
    >
      <canvas ref={canvasRef} className="absolute inset-0 size-full" />
      <div className="relative z-10 p-6">{children}</div>
    </div>
  )
}

export { PixelCanvasCard }

