// Ported from Kibo UI (MIT, (c) shadcnblocks) — https://github.com/shadcnblocks/kibo/blob/main/packages/relative-time/index.tsx

import { useAnimationActive } from "@/hooks/use-animation-active"
import { useControllableState } from "@/hooks/use-controllable-state"
import { cn } from "@/lib/utils"

import { createContext, useContext, useEffect, useRef, type HTMLAttributes, type ReactNode } from "react"

function formatDate(date: Date, timeZone: string, options?: Intl.DateTimeFormatOptions) {
  return new Intl.DateTimeFormat("en-US", options ?? { dateStyle: "long", timeZone }).format(date)
}

function formatTime(date: Date, timeZone: string, options?: Intl.DateTimeFormatOptions) {
  return new Intl.DateTimeFormat(
    "en-US",
    options ?? { hour: "2-digit", minute: "2-digit", second: "2-digit", timeZone },
  ).format(date)
}

interface RelativeTimeContextType {
  time: Date
  dateFormatOptions?: Intl.DateTimeFormatOptions
  timeFormatOptions?: Intl.DateTimeFormatOptions
}

const RelativeTimeContext = createContext<RelativeTimeContextType>({
  time: new Date(0),
})

export interface RelativeTimeProps {
  time?: Date
  defaultTime?: Date
  onTimeChange?: (time: Date) => void
  dateFormatOptions?: Intl.DateTimeFormatOptions
  timeFormatOptions?: Intl.DateTimeFormatOptions
  className?: string
  children?: ReactNode
}

export function RelativeTime({
  time: controlledTime,
  defaultTime,
  onTimeChange,
  dateFormatOptions,
  timeFormatOptions,
  className,
  children,
}: RelativeTimeProps) {
  const rootRef = useRef<HTMLDivElement>(null)
  const motionOn = useAnimationActive(rootRef)
  const initialTime = defaultTime ?? controlledTime ?? new Date()
  const [time, setTime] = useControllableState<Date>({
    value: controlledTime,
    defaultValue: initialTime,
    onChange: onTimeChange,
  })

  useEffect(() => {
    if (controlledTime || !motionOn) return
    const interval = window.setInterval(() => {
      setTime(new Date())
    }, 1000)
    return () => window.clearInterval(interval)
  }, [controlledTime, motionOn, setTime])

  return (
    <RelativeTimeContext.Provider value={{ time, dateFormatOptions, timeFormatOptions }}>
      <div className={cn("grid gap-2", className)} data-slot="relative-time" ref={rootRef}>
        {children}
      </div>
    </RelativeTimeContext.Provider>
  )
}

interface RelativeTimeZoneContextType {
  zone: string
  dateFormatOptions?: Intl.DateTimeFormatOptions
  timeFormatOptions?: Intl.DateTimeFormatOptions
}

const RelativeTimeZoneContext = createContext<RelativeTimeZoneContextType>({ zone: "UTC" })

export interface RelativeTimeZoneProps {
  zone: string
  className?: string
  children?: ReactNode
  dateFormatOptions?: Intl.DateTimeFormatOptions
  timeFormatOptions?: Intl.DateTimeFormatOptions
}

export function RelativeTimeZone({ zone, className, children, dateFormatOptions, timeFormatOptions }: RelativeTimeZoneProps) {
  return (
    <RelativeTimeZoneContext.Provider value={{ zone, dateFormatOptions, timeFormatOptions }}>
      <div className={cn("flex items-center justify-between gap-1.5 text-xs", className)}>{children}</div>
    </RelativeTimeZoneContext.Provider>
  )
}

export function RelativeTimeZoneDisplay({ className, ...props }: HTMLAttributes<HTMLDivElement>) {
  const { time, timeFormatOptions } = useContext(RelativeTimeContext)
  const zoneContext = useContext(RelativeTimeZoneContext)
  return (
    <div className={cn("pl-8 text-muted-foreground tabular-nums", className)} suppressHydrationWarning {...props}>
      {formatTime(time, zoneContext.zone, zoneContext.timeFormatOptions ?? timeFormatOptions)}
    </div>
  )
}

export function RelativeTimeZoneDate({ className, ...props }: HTMLAttributes<HTMLDivElement>) {
  const { time, dateFormatOptions } = useContext(RelativeTimeContext)
  const zoneContext = useContext(RelativeTimeZoneContext)
  return (
    <div className={className} suppressHydrationWarning {...props}>
      {formatDate(time, zoneContext.zone, zoneContext.dateFormatOptions ?? dateFormatOptions)}
    </div>
  )
}

export function RelativeTimeZoneLabel({ className, ...props }: HTMLAttributes<HTMLDivElement>) {
  return (
    <div
      className={cn("bg-secondary flex h-4 items-center justify-center rounded-xs px-1.5 font-mono", className)}
      {...props}
    />
  )
}

"use client"

import * as React from "react"
import { motion, useSpring } from "motion/react"

import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { cn } from "@/lib/utils"

export interface RepetitionImageHoverProps {
  label?: string
  layers?: number
  className?: string
}

function Echo({
  index,
  count,
  nx,
  ny,
  hovering,
  label,
}: {
  index: number
  count: number
  nx: number
  ny: number
  hovering: boolean
  label: string
}) {
  const factor = index / Math.max(count - 1, 1)
  const x = useSpring(0, { stiffness: 220, damping: 18 })
  const y = useSpring(0, { stiffness: 220, damping: 18 })
  React.useEffect(() => {
    x.set(hovering ? nx * factor * 1.7 : 0)
    y.set(hovering ? ny * factor * 1.7 : 0)
  }, [factor, hovering, nx, ny, x, y])
  const scale = 1 - factor * 0.55
  const opacity = hovering || index === 0 ? 1 - factor * 0.62 : 0
  return (
    <motion.div
      aria-hidden={index === 0 ? undefined : true}
      className="absolute top-1/2 left-1/2 flex h-48 w-64 items-end rounded-2xl p-4 text-slate-950 shadow-lg"
      style={{
        x,
        y,
        scale,
        opacity,
        zIndex: count - index,
        marginLeft: "-8rem",
        marginTop: "-6rem",
        backgroundImage: `linear-gradient(145deg, hsl(${18 + index * 16} 82% ${68 - index * 6}%), hsl(${32 + index * 10} 70% 42%))`,
      }}
    >
      <span className="text-lg font-medium">{label}</span>
    </motion.div>
  )
}

function RepetitionImageHover({ label = "回声", layers = 5, className }: RepetitionImageHoverProps) {
  const reduced = usePrefersReducedMotion()
  const count = Math.min(8, Math.max(2, Math.round(layers)))
  const [point, setPoint] = React.useState({ x: 0, y: 0, hovering: false })

  if (reduced) {
    return (
      <div data-slot="repetition-image-hover" className={cn("relative h-72", className)}>
        <div className="absolute top-1/2 left-1/2 flex h-48 w-64 -translate-x-1/2 -translate-y-1/2 items-end rounded-2xl bg-linear-to-br from-orange-300 to-rose-500 p-4 text-lg text-slate-950">{label}</div>
      </div>
    )
  }

  return (
    <div
      data-slot="repetition-image-hover"
      className={cn("relative h-80 overflow-hidden rounded-xl border bg-slate-950", className)}
      onPointerMove={(event) => {
        const rect = event.currentTarget.getBoundingClientRect()
        const dx = event.clientX - (rect.left + rect.width / 2)
        const dy = event.clientY - (rect.top + rect.height / 2)
        const length = Math.hypot(dx, dy)
        if (length < 8) {
          setPoint({ x: 140, y: 0, hovering: true })
          return
        }
        const reach = Math.max(140, Math.min(170, length))
        setPoint({
          x: (dx / length) * reach,
          y: (dy / length) * Math.min(64, reach),
          hovering: true,
        })
      }}
      onPointerLeave={() => setPoint({ x: 0, y: 0, hovering: false })}
    >
      {Array.from({ length: count }, (_, index) => (
        <Echo key={index} index={index} count={count} nx={point.x} ny={point.y} hovering={point.hovering} label={label} />
      ))}
    </div>
  )
}

export { RepetitionImageHover }

"use client"

import { motion } from "motion/react"
import * as React from "react"

import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { cn } from "@/lib/utils"

export interface ResourceCard {
  id: string
  title: string
  topic: string
  summary: string
  hue: number
}

export interface ResourceSearchHeroProps {
  cards?: readonly ResourceCard[]
  className?: string
}

const CARDS: readonly ResourceCard[] = [
  { id: "signal", title: "信号墙", topic: "背景", summary: "滚动速度拖出残影", hue: 262 },
  { id: "orbit", title: "轨道列表", topic: "文字", summary: "两列反向波动", hue: 190 },
  { id: "lens", title: "方形透镜", topic: "指针", summary: "放大、扭曲、分色", hue: 28 },
  { id: "mask", title: "遮罩过渡", topic: "滚动", summary: "圆形、色块、条纹、文字", hue: 330 },
  { id: "lid", title: "笔记本", topic: "滚动", summary: "屏幕随滚动打开", hue: 210 },
  { id: "heat", title: "热力年历", topic: "数据", summary: "一年的密度格", hue: 152 },
  { id: "json", title: "JSON 树", topic: "数据", summary: "折叠、搜索、复制路径", hue: 48 },
  { id: "filter", title: "分面筛选", topic: "表格", summary: "字段、条件、可编辑标签", hue: 12 },
]

interface FuseLike {
  search: (query: string) => { item: ResourceCard }[]
}

function includesMatch(cards: readonly ResourceCard[], query: string) {
  const needle = query.toLowerCase()
  return cards.filter((card) =>
    `${card.title} ${card.topic} ${card.summary}`.toLowerCase().includes(needle),
  )
}

function ResourceSearchHero({ cards = CARDS, className }: ResourceSearchHeroProps) {
  const reduced = usePrefersReducedMotion()
  const [query, setQuery] = React.useState("")
  const [fuse, setFuse] = React.useState<FuseLike | null>(null)
  const inputId = React.useId()

  React.useEffect(() => {
    let cancelled = false
    void import("fuse.js").then((mod) => {
      if (cancelled) return
      const Fuse = mod.default
      setFuse(new Fuse([...cards], { keys: ["title", "topic", "summary"], threshold: 0.42 }))
    })
    return () => {
      cancelled = true
    }
  }, [cards])

  const results = !query.trim()
    ? [...cards]
    : fuse
      ? fuse.search(query.trim()).map((item) => item.item)
      : includesMatch(cards, query.trim())

  return (
    <section data-slot="resource-search-hero" className={cn("w-full space-y-5", className)}>
      <style>
        {`@keyframes effect-ui-search-glow {
          50% { box-shadow: 0 0 0 4px color-mix(in oklab, var(--primary) 30%, transparent), 0 0 28px color-mix(in oklab, var(--primary) 45%, transparent); }
        }`}
      </style>
      <div className="space-y-2 text-center">
        <h2 className="font-display text-4xl tracking-tight">找一个主题</h2>
        <p className="text-sm text-muted-foreground">输入后卡片会按匹配重新排列。</p>
      </div>
      <label htmlFor={inputId} className="sr-only">
        搜索主题
      </label>
      <input
        id={inputId}
        value={query}
        onChange={(event) => setQuery(event.target.value)}
        placeholder="试试 滚动、数据、透镜"
        className={cn(
          "mx-auto block h-12 w-full max-w-xl rounded-full border bg-background px-5 text-sm outline-none focus-visible:ring-2 focus-visible:ring-primary",
          !reduced && "motion-safe:animate-[effect-ui-search-glow_2.8s_ease-in-out_infinite]",
        )}
      />
      {results.length === 0 ? (
        <p className="text-center text-sm text-muted-foreground">没有匹配的主题</p>
      ) : (
        <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
          {results.map((card) => (
            <motion.article
              key={card.id}
              layout
              transition={reduced ? { duration: 0 } : { type: "spring", stiffness: 360, damping: 32 }}
              className="rounded-xl border p-3"
            >
              <div
                className="mb-3 h-16 rounded-lg"
                style={{ background: `linear-gradient(145deg, hsl(${card.hue} 55% 36%), hsl(${card.hue} 75% 58%))` }}
              />
              <p className="text-xs text-muted-foreground">{card.topic}</p>
              <h3 className="text-sm font-medium">{card.title}</h3>
              <p className="mt-1 text-xs text-muted-foreground">{card.summary}</p>
            </motion.article>
          ))}
        </div>
      )}
    </section>
  )
}

export { ResourceSearchHero }

