  const step = (delay ?? 35) / 1000

  return (
    <div
      data-slot="rolling-text-hover"
      className={cn("flex flex-wrap items-center gap-4", className)}
      style={textStyle(undefined, fontSize, fontWeight, letterSpacing, align)}
