        <Check aria-hidden="true" className="size-4" />
      ) : (
        <motion.span
          animate={{ rotate: phase === "loading" ? 180 : 0 }}
          transition={{ duration: prefersReducedMotion ? 0 : 0.45 }}
        >
          <ChevronRight aria-hidden="true" className="size-4" />
        </motion.span>
      )}
    </button>
  )
}

