        initial={false}
        transition={spring}
      />
      {onLabel && offLabel ? (
        <span className={cn("relative z-10 px-6 font-medium", on ? "text-primary-foreground" : "text-muted-foreground")}>
          {on ? onLabel : offLabel}
        </span>
      ) : (
        <span className="inline-block h-5 w-10" />
      )}
    </button>
  )
}

