  const narrow = width < 440;
  const leftRoom = narrow ? (width < 300 ? 116 : 132) : 168, rightRoom = ranks ? (narrow ? 76 : 96) : (narrow ? 52 : 64);
  const x0 = leftRoom, x1 = Math.max(x0 + 40, width - rightRoom);

