// Ported from kokonutUI (MIT) — https://github.com/kokonut-labs/kokonutui/blob/main/components/kokonutui/spending-ring.tsx

/**
 * @author: @dorianbaffier
 * @description: Spending Ring
 * @version: 1.0.0
 * @date: 2026-10-15
 * @license: MIT
 * @website: https://kokonutui.com
 * @github: https://github.com/kokonut-labs/kokonutui
