import { afterEach, expect, test } from "vitest"
import { cleanup, render } from "@testing-library/react"
import "@testing-library/jest-dom/vitest"

import { SplitText } from "./split-text"

function installMatchMedia(reduce: boolean) {
  window.matchMedia = (query: string) =>
    ({
      matches: reduce && query.includes("prefers-reduced-motion"),
      media: query,
      onchange: null,
      addEventListener: () => {},
      removeEventListener: () => {},
      dispatchEvent: () => false,
      addListener: () => {},
      removeListener: () => {},
    }) as unknown as MediaQueryList
}

afterEach(() => {
  cleanup()
})

test("不传新 prop 时文字按原样拆开，且不写排版样式", () => {
  installMatchMedia(true)
  const view = render(<SplitText text="Hi" delay={0.4} by="char" />)
  expect(view.container.textContent).toBe("Hi")
  expect(view.container.querySelector("[data-slot=split-text]")).not.toHaveAttribute("style")
})

test("减弱动效时仍显示全文，传入排版 prop 后写到样式上", () => {
  installMatchMedia(true)
  const view = render(
    <SplitText text="Hi" fontSize={22} fontWeight={600} letterSpacing={0.02} align="right" loop interactive />,
  )
  expect(view.container.textContent).toBe("Hi")
  const style = view.container.querySelector("[data-slot=split-text]")?.getAttribute("style") ?? ""
  expect(style).toContain("font-size: 22px")
  expect(style).toContain("font-weight: 600")
  expect(style).toContain("letter-spacing: 0.02em")
  expect(style).toContain("text-align: right")
  expect(style).not.toContain("width")
})

"use client"

import * as React from "react"
import { motion, type Variants } from "motion/react"

import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { cn } from "@/lib/utils"

export interface SplitTextProps {
  text: string
  /** 入场延迟，单位秒。保持原含义。 */
  delay?: number
  by?: "char" | "word"
  className?: string
  /** 入场结束后再播一次。不传则只播一次。 */
  loop?: boolean
  /** 精细指针移入时重播。触屏上忽略移入。 */
  interactive?: boolean
  fontSize?: number
  fontWeight?: number
  letterSpacing?: number
  align?: "left" | "center" | "right"
}

function coarsePointer() {
  return window.matchMedia("(pointer: coarse)").matches
}

const container: Variants = {
  hidden: {},
  show: {
    transition: {
      staggerChildren: 0.03,
    },
  },
}

const item: Variants = {
  hidden: { opacity: 0, y: 12, filter: "blur(6px)" },
  show: {
    opacity: 1,
    y: 0,
    filter: "blur(0px)",
    transition: { duration: 0.45, ease: [0.22, 1, 0.36, 1] },
  },
}

function SplitText({
  text,
  delay = 0,
  by = "char",
  className,
  loop = false,
  interactive = false,
  fontSize,
  fontWeight,
  letterSpacing,
  align,
}: SplitTextProps) {
  const reduced = usePrefersReducedMotion()
  const [replay, setReplay] = React.useState(0)
  const pieces = React.useMemo(
    () => (by === "word" ? text.split(/(\s+)/) : Array.from(text)),
    [by, text],
  )
  const style: React.CSSProperties = {}
  if (fontSize !== undefined) style.fontSize = fontSize
  if (fontWeight !== undefined) style.fontWeight = fontWeight
  if (letterSpacing !== undefined) style.letterSpacing = `${letterSpacing}em`
  if (align !== undefined) style.textAlign = align

  return (
    <motion.span
      key={replay}
      data-slot="split-text"
      className={cn("inline-flex flex-wrap", className)}
      style={Object.keys(style).length > 0 ? style : undefined}
      variants={container}
      initial={reduced ? false : "hidden"}
      animate="show"
      transition={reduced ? { duration: 0, delayChildren: 0 } : { delayChildren: delay }}
      onAnimationComplete={() => {
        if (loop && !reduced) setReplay((current) => current + 1)
      }}
      onPointerEnter={() => {
        if (reduced || !interactive || coarsePointer()) return
        setReplay((current) => current + 1)
      }}
    >
      {pieces.map((piece, index) => (
        <motion.span
          key={`${piece}-${index}`}
          variants={item}
          className="inline-block"
          transition={
            reduced ? { duration: 0 } : { duration: 0.45, ease: [0.22, 1, 0.36, 1] }
          }
        >
          {piece === " " ? "\u00A0" : piece}
        </motion.span>
      ))}
    </motion.span>
  )
}

export { SplitText }

"use client"

import * as React from "react"

import { useAnimationActive } from "@/hooks/use-animation-active"
import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { textStyle } from "@/lib/text-style"
import { cn } from "@/lib/utils"

export interface SpoilerTextProps {
  text: string
  className?: string
  /** 遮挡粒子数量。不传则 90。 */
  count?: number
  /** 粒子抖动速度倍率。不传则 1。 */
  speed?: number
  color?: string
  fontSize?: number
  fontWeight?: number
  letterSpacing?: number
  align?: "left" | "center" | "right"
}

interface Speck {
  x: number
  y: number
  vx: number
  vy: number
  life: number
}

function SpoilerText({
  text,
  className,
  count,
  speed,
  color,
  fontSize,
  fontWeight,
  letterSpacing,
  align,
}: SpoilerTextProps) {
  const reduced = usePrefersReducedMotion()
  const [revealed, setRevealed] = React.useState(false)
  const hostRef = React.useRef<HTMLButtonElement>(null)
  const canvasRef = React.useRef<HTMLCanvasElement>(null)
  const specks = React.useRef<Speck[]>([])
  const active = useAnimationActive(hostRef)
  const visible = revealed || reduced
  const speckCount = Math.max(1, Math.round(count ?? 90))
  const pace = speed === undefined || !Number.isFinite(speed) ? 1 : speed

  React.useEffect(() => {
    const canvas = canvasRef.current
    if (!canvas || visible || !active) return
    const ctx = canvas.getContext("2d")
    if (!ctx) return
    const resize = () => {
      const { width, height } = canvas.getBoundingClientRect()
      const dpr = Math.min(window.devicePixelRatio || 1, 2)
      canvas.width = width * dpr
      canvas.height = height * dpr
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0)
      specks.current = Array.from({ length: speckCount }, () => ({
        x: Math.random() * width,
        y: Math.random() * height,
        vx: 0,
        vy: 0,
        life: 1,
      }))
    }
    resize()
    let frame = 0
    const tick = () => {
      const { width, height } = canvas.getBoundingClientRect()
      ctx.clearRect(0, 0, width, height)
      for (const speck of specks.current) {
        speck.x += (Math.random() - 0.5) * 0.8 * pace
        speck.y += (Math.random() - 0.5) * 0.8 * pace
        ctx.fillStyle =
          color === undefined
            ? `color-mix(in oklab, var(--foreground) ${40 + speck.life * 40}%, transparent)`
            : color
        ctx.fillRect(speck.x, speck.y, 2.2, 2.2)
      }
      frame = window.requestAnimationFrame(tick)
    }
    frame = window.requestAnimationFrame(tick)
    return () => window.cancelAnimationFrame(frame)
  }, [active, color, pace, speckCount, visible])

  const reveal = () => {
    if (reduced) {
      setRevealed(true)
      return
    }
    const canvas = canvasRef.current
    const ctx = canvas?.getContext("2d")
    if (!canvas || !ctx) {
      setRevealed(true)
      return
    }
    const { width, height } = canvas.getBoundingClientRect()
    specks.current = specks.current.map((speck) => ({
      ...speck,
      vx: (speck.x - width / 2) * 0.08,
      vy: (speck.y - height / 2) * 0.08,
    }))
    let steps = 0
    const burst = () => {
      ctx.clearRect(0, 0, width, height)
      for (const speck of specks.current) {
        speck.x += speck.vx
        speck.y += speck.vy
        speck.life *= 0.9
        ctx.globalAlpha = speck.life
        ctx.fillRect(speck.x, speck.y, 2.2, 2.2)
      }
      steps += 1
      if (steps < 18) window.requestAnimationFrame(burst)
      else setRevealed(true)
    }
    burst()
  }

  return (
    <button
      ref={hostRef}
      type="button"
      onClick={reveal}
      className={cn("relative inline-block rounded-md px-2 py-1 text-left", className)}
      aria-label={visible ? text : "点击揭示隐藏文本"}
    >
      <span className={cn(!visible && "opacity-0")} style={textStyle(undefined, fontSize, fontWeight, letterSpacing, align)}>
        {text}
      </span>
      {!visible ? <canvas ref={canvasRef} className="absolute inset-0 size-full cursor-pointer" /> : null}
    </button>
  )
}

export { SpoilerText }

"use client"

import * as React from "react"
import { motion, useMotionTemplate, useMotionValue } from "motion/react"

import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { cn } from "@/lib/utils"

export interface SpotlightCardProps extends React.HTMLAttributes<HTMLDivElement> {
  spotlightColor?: string
  radius?: number
  speed?: number
  intensity?: number
}

function pace(speed: number | undefined) {
  return speed === undefined || !Number.isFinite(speed) || speed <= 0 ? 1 : speed
}

function SpotlightCard({
  className,
  children,
  spotlightColor = "color-mix(in oklab, var(--primary) 35%, transparent)",
  radius = 240,
  speed,
  intensity,
  ...props
}: SpotlightCardProps) {
  const reduceMotion = usePrefersReducedMotion()
  const mouseX = useMotionValue(0)
  const mouseY = useMotionValue(0)
  const falloff = intensity === undefined || intensity === 1 ? 70 : Math.min(100, Math.max(0, 70 * intensity))
  const keepDuration = speed === undefined || speed === 1

  const onMouseMove = (event: React.MouseEvent<HTMLDivElement>) => {
    if (reduceMotion || window.matchMedia("(pointer: coarse)").matches) return
    const { left, top } = event.currentTarget.getBoundingClientRect()
    mouseX.set(event.clientX - left)
    mouseY.set(event.clientY - top)
  }

  const background = useMotionTemplate`radial-gradient(${radius}px circle at ${mouseX}px ${mouseY}px, ${spotlightColor}, transparent ${falloff}%)`
  const staticBackground = `radial-gradient(${radius}px circle at 50% 50%, ${spotlightColor}, transparent ${falloff}%)`

  return (
    <div
      data-slot="spotlight-card"
      onMouseMove={onMouseMove}
      className={cn(
        "group relative overflow-hidden rounded-xl border bg-card p-6 text-card-foreground shadow-sm",
        className,
      )}
      {...props}
    >
      <motion.div
        className={cn(
          "pointer-events-none absolute -inset-px rounded-xl opacity-0 transition-opacity pointer-fine:group-hover:opacity-100 motion-reduce:hidden",
          keepDuration && "duration-300",
        )}
        style={{ background, transitionDuration: keepDuration ? undefined : `${300 / pace(speed)}ms` }}
      />
      <div
        aria-hidden
        className="pointer-events-none absolute -inset-px rounded-xl opacity-0 pointer-coarse:opacity-100 motion-reduce:opacity-100"
        style={{ background: staticBackground }}
      />
      <div className="relative z-10">{children}</div>
    </div>
  )
}

