// Ported from SmoothUI (MIT) — https://github.com/educlopez/smoothui/blob/main/packages/smoothui/components/svg-clip-mask/index.tsx

import { useAnimationActive } from "@/hooks/use-animation-active"
import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { cn } from "@/lib/utils"


const HOVER_QUERY = "(hover: hover) and (pointer: fine)";

function subscribeHover(onStoreChange: () => void) {
  const media = window.matchMedia(HOVER_QUERY);
  media.addEventListener("change", onStoreChange);
  return () => media.removeEventListener("change", onStoreChange);
}

function hoverSnapshot() {
  return window.matchMedia(HOVER_QUERY).matches;
}

function useHoverCapable() {
  return useSyncExternalStore(subscribeHover, hoverSnapshot, () => false);
}

import {
  motion,
  useMotionValueEvent,
  useScroll,
} from "motion/react";
import {
  type ReactNode,
  type RefObject,
  useId,
  useRef,
  useState,
  useSyncExternalStore,
} from "react";

/** Motion scroll offset tuple, typed from `useScroll` itself. */
export type ScrollOffset = NonNullable<
  Parameters<typeof useScroll>[0]
>["offset"];

const EASE_MOVE = [0.645, 0.045, 0.355, 1] as const;
const TRANSITION_DURATION = 0.3;
const DEFAULT_MORPH_DURATION = 4;
// The mask has to finish opening while the frame is still in view; the full
// enter-to-exit range parks the fully-revealed state off-screen.
const DEFAULT_SCROLL_OFFSET: ScrollOffset = ["start 0.9", "end 0.6"];

const PRESET_PATHS = {
  arch: "M0,1 L0,0.4 C0,0.18 0.18,0 0.5,0 C0.82,0 1,0.18 1,0.4 L1,1 Z",
  blob: "M0.5,0.02 C0.75,0.02 0.98,0.25 0.98,0.5 C0.98,0.75 0.75,0.98 0.5,0.98 C0.25,0.98 0.02,0.75 0.02,0.5 C0.02,0.25 0.25,0.02 0.5,0.02 Z",
  diamond: "M0.5,0 L1,0.5 L0.5,1 L0,0.5 Z",
  wave: "M0,0.3 C0.25,0.05 0.75,0.55 1,0.3 L1,1 L0,1 Z",
} as const;

export type SvgClipMaskShape = "blob" | "arch" | "diamond" | "wave" | "custom";
export type SvgClipMaskAnimate = "none" | "morph" | "scroll" | "hover";

export interface SvgClipMaskProps {
  /**
   * "morph" cycles through morphPaths forever, "scroll" steps through them as
   * the container scrolls, "hover" swaps to morphPaths[0] on hover.
   */
  animate?: SvgClipMaskAnimate;
  children: ReactNode;
  className?: string;
  /** Ref to a scrollable ancestor that drives "scroll" mode instead of the window. */
  container?: RefObject<HTMLElement | null>;
  /** Seconds for one full "morph" loop. */
  duration?: number;
  /**
   * Paths to cycle between for "morph"/"scroll"/"hover". They must all share
   * the same command structure (same sequence of M/L/C/Z and point counts) —
   * browsers interpolate matching parameters positionally, so mismatched
   * structures snap instead of morphing smoothly.
   */
  morphPaths?: string[];
  /** Custom path data, in objectBoundingBox (0..1) coordinates. Required when shape is "custom". */
  path?: string;
  shape?: SvgClipMaskShape;
}

export function SvgClipMask({
  children,
  shape = "blob",
  path,
  animate = "none",
  morphPaths,
  duration = DEFAULT_MORPH_DURATION,
  container,
  className,
}: SvgClipMaskProps) {
  const clipId = useId();
  const prefersReducedMotion = usePrefersReducedMotion();
  const hostRef = useRef<HTMLDivElement>(null);
  const motionOn = useAnimationActive(hostRef);
  const shouldReduceMotion = prefersReducedMotion || !motionOn;
  const isHoverCapable = useHoverCapable();
  const [isHovered, setIsHovered] = useState(false);
  const [scrollIndex, setScrollIndex] = useState(0);

  const basePath =
    shape === "custom" ? (path ?? PRESET_PATHS.blob) : PRESET_PATHS[shape];
  const paths = morphPaths && morphPaths.length > 1 ? morphPaths : [basePath];

  const { scrollYProgress } = useScroll({
    container,
    offset: DEFAULT_SCROLL_OFFSET,
    target: hostRef,
  });

  useMotionValueEvent(scrollYProgress, "change", (value) => {
    if (shouldReduceMotion || animate !== "scroll" || paths.length < 2) {
      return;
    }
    const index = Math.min(paths.length - 1, Math.floor(value * paths.length));
    setScrollIndex(index);
  });

  const isMorphing =
    animate === "morph" && !shouldReduceMotion && paths.length > 1;

  const activeD = (() => {
    if (shouldReduceMotion || animate === "none" || isMorphing) {
      return paths[0];
    }
    if (animate === "scroll") {
      return paths[scrollIndex] ?? paths[0];
    }
    if (animate === "hover") {
      return isHoverCapable && isHovered ? (paths[1] ?? paths[0]) : paths[0];
    }
    return paths[0];
  })();

  return (
    <div
      className={cn("relative", className)}
      onPointerEnter={() => setIsHovered(true)}
      onPointerLeave={() => setIsHovered(false)}
      ref={hostRef} data-reduced={prefersReducedMotion ? "true" : "false"} data-slot="svg-clip-mask"
    >
      <svg aria-hidden="true" className="absolute h-0 w-0">
        <defs>
          <clipPath clipPathUnits="objectBoundingBox" id={clipId}>
            <motion.path
              animate={isMorphing ? { d: paths } : { d: activeD }}
              initial={false}
              transition={
                isMorphing
                  ? {
                      duration,
                      ease: EASE_MOVE,
                      repeat: Number.POSITIVE_INFINITY,
                      repeatType: "loop",
                    }
                  : { duration: TRANSITION_DURATION, ease: EASE_MOVE }
              }
            />
          </clipPath>
        </defs>
      </svg>
      <div
        className="h-full w-full"
        style={{
          clipPath: `url(#${clipId})`,
          WebkitClipPath: `url(#${clipId})`,
        }}
      >
        {children}
      </div>
    </div>
  );
}

"use client"

import * as React from "react"

import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { cn } from "@/lib/utils"

export type MaskPreset = "circle" | "blob" | "stripes" | "text"

export interface SvgMaskScrollTransitionProps {
  className?: string
  intensity?: number
  speed?: number
  count?: number
}

function pace(speed: number | undefined) {
  return speed === undefined || !Number.isFinite(speed) || speed <= 0 ? 1 : speed
}

const PRESETS: readonly { id: MaskPreset; label: string }[] = [
  { id: "circle", label: "圆形" },
  { id: "blob", label: "色块" },
  { id: "stripes", label: "条纹" },
  { id: "text", label: "文字" },
]

function SvgMaskScrollTransition({ className, intensity, speed, count }: SvgMaskScrollTransitionProps) {
  const reduced = usePrefersReducedMotion()
  const reactId = React.useId().replace(/:/g, "")
  const maskId = `effect-ui-mask-${reactId}`
  const [progress, setProgress] = React.useState(reduced ? 1 : 0)
  const [preset, setPreset] = React.useState<MaskPreset>("circle")
  const rate = pace(speed)
  const gain = intensity === undefined || intensity === 1 ? 1 : intensity
  const stripes = count === undefined || count === 7 ? 7 : Math.max(1, Math.round(count))

  const onScroll = (event: React.UIEvent<HTMLDivElement>) => {
    if (reduced) return
    const element = event.currentTarget
    const max = element.scrollHeight - element.clientHeight
    const next = max <= 0 ? 1 : element.scrollTop / max
    setProgress(next)
  }

  const shaped = rate === 1 ? progress : Math.min(1, Math.pow(Math.max(progress, 0), rate))
  const amount = reduced ? 1 : shaped

  return (
    <div data-slot="svg-mask-scroll-transition" className={cn("w-full space-y-3", className)}>
      <div className="flex flex-wrap gap-2" role="radiogroup" aria-label="遮罩形状">
        {PRESETS.map((item) => (
          <button
            key={item.id}
            type="button"
            role="radio"
            aria-checked={preset === item.id}
            className={cn("rounded-md border px-3 py-1.5 text-sm", preset === item.id && "bg-primary text-primary-foreground")}
            onClick={() => setPreset(item.id)}
          >
            {item.label}
          </button>
        ))}
      </div>
      <div
        tabIndex={0}
        aria-label="滚动切换场景。下一幕从 SVG 遮罩里显出。"
        className="h-80 overflow-auto rounded-xl border outline-none focus-visible:ring-2 focus-visible:ring-primary"
        onScroll={onScroll}
      >
        <div className="relative h-[180vh]">
          <div className="sticky top-0 h-80 overflow-hidden">
            <div className="absolute inset-0 grid place-items-center bg-[linear-gradient(145deg,#1e1b4b,#0f766e)] text-3xl font-medium text-white">
              上一幕
            </div>
            <div
              className="absolute inset-0 grid place-items-center bg-[linear-gradient(160deg,#9a3412,#f59e0b)] text-3xl font-medium text-white"
              style={{ mask: `url(#${maskId})`, WebkitMask: `url(#${maskId})` }}
            >
              下一幕
            </div>
            <svg className="pointer-events-none absolute h-0 w-0" aria-hidden>
              <mask id={maskId} maskContentUnits="objectBoundingBox">
                {preset === "circle" ? (
                  <circle cx="0.5" cy="0.5" r={gain === 1 ? 0.04 + amount * 0.72 : 0.04 + amount * 0.72 * gain} fill="white" />
                ) : null}
                {preset === "blob" ? (
                  <>
                    <ellipse cx="0.46" cy="0.48" rx={gain === 1 ? 0.08 + amount * 0.42 : 0.08 + amount * 0.42 * gain} ry={gain === 1 ? 0.06 + amount * 0.34 : 0.06 + amount * 0.34 * gain} fill="white" />
                    <ellipse cx="0.62" cy="0.58" rx={gain === 1 ? 0.05 + amount * 0.24 : 0.05 + amount * 0.24 * gain} ry={gain === 1 ? 0.08 + amount * 0.22 : 0.08 + amount * 0.22 * gain} fill="white" />
                  </>
                ) : null}
                {preset === "stripes"
                  ? Array.from({ length: stripes }, (_, index) => (
                      <rect
                        key={index}
                        x={index / stripes + 0.008}
                        y={1 - (gain === 1 ? amount : amount * gain)}
                        width={1 / stripes - 0.016}
                        height={gain === 1 ? amount : amount * gain}
                        fill="white"
                      />
                    ))
                  : null}
                {preset === "text" ? (
                  <text
                    x="0.5"
                    y="0.58"
                    textAnchor="middle"
                    fill="white"
                    fontSize={gain === 1 ? 0.05 + amount * 0.42 : 0.05 + amount * 0.42 * gain}
                    fontFamily="sans-serif"
                  >
                    OPEN
                  </text>
                ) : null}
              </mask>
            </svg>
          </div>
        </div>
      </div>
    </div>
  )
}

export { SvgMaskScrollTransition }

