            className,
          )}
          data-reduced={reduced ? "true" : undefined}
          data-slot="tab-navigation-link"
          href={href}
          onClick={disabled ? (event) => event.preventDefault() : undefined}
        >
          {children}
        </a>
      </NavigationMenuPrimitive.Link>
    </NavigationMenuPrimitive.Item>
  )
}

