                : "stroke-zinc-200 dark:stroke-zinc-700"
            }
            cx={8}
            cy={8}
            fill="none"
            key={r}
            r={r}
            strokeWidth={i === index ? 1.5 : 1}
          />
        );
      })}
    </svg>
  );
}

