        <p className="font-mono text-[11px] text-muted-foreground">
          {flowActive
            ? sealed
              ? `Stopping — ${delivered} of ${total} made it across.`
              : `Moving ${delivered} of ${total}…`
            : "Drag a selected item across, or use the command."}
        </p>
        <button
          type="button"
          data-sl-move
          disabled={flowActive || selected.size === 0}
          onClick={onMoveClick}
          className="rounded-sm border border-border bg-background px-3 py-1.5 text-xs font-medium text-foreground outline-none transition-colors hover:border-foreground/25 focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background disabled:cursor-not-allowed disabled:opacity-50 disabled:pointer-events-none"
        >
          Move selected to {destinationLabel}
        </button>
      </div>

      <p aria-live="polite" className="sr-only">
        {liveMessage}
      </p>

      <svg
        ref={svgRef}
        aria-hidden
        className="pointer-events-none absolute left-0 top-0 h-full w-full overflow-visible"
        viewBox={`0 0 ${size.w || 1} ${size.h || 1}`}
        preserveAspectRatio="none"
      >
        {tubeD ? (
          <path
            ref={pathRef}
            d={tubeD}
            className={`sl-tube-path ${fading ? "sl-tube-fading" : ""} ${recoil ? "sl-tube-recoil" : ""}`}
          />
        ) : (
          <path ref={pathRef} d="" className="sl-tube-path" style={{ opacity: 0 }} />
        )}
      </svg>

      {flowActive && stopPos ? (
        <button
          type="button"
          data-sl-stop
          aria-label="Stop transfer"
          onClick={breakSeal}
          style={{ left: stopPos.x, top: stopPos.y }}
          className="sl-stop-btn absolute -translate-x-1/2 -translate-y-1/2 rounded-full border border-border bg-card text-foreground outline-none transition-colors hover:border-foreground/40 focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background"
        >
          <span aria-hidden className="sl-stop-icon" />
        </button>
      ) : null}

      {dragGhost ? (
        <div
          aria-hidden
          className="pointer-events-none fixed z-50 rounded-md border border-border bg-card px-2.5 py-1.5 text-xs text-foreground"
          style={{ left: dragGhost.x, top: dragGhost.y }}
        >
          {dragGhost.count} {dragGhost.count === 1 ? "item" : "items"}
        </div>
      ) : null}
    </div>
  );
}

