            GitHub
          </Button>
        </div>
      </div>
      <div className="mt-10 [perspective:1400px]">
        <motion.div
          style={reduced ? undefined : { y, rotateX, rotateY, rotateZ: -8 }}
          className="mx-auto grid max-w-4xl grid-cols-3 gap-3 [transform-style:preserve-3d]"
        >
          {cards.map((card) => (
            <article
              key={card.title}
