"use client"

import * as React from "react"
import { Maximize2, Minimize2, Pause, PictureInPicture2, Play, Volume2, VolumeX } from "lucide-react"

import { cn } from "@/lib/utils"

export interface VideoPlayerProps {
  src: string
  poster?: string
  className?: string
}

function formatTime(seconds: number) {
  if (!Number.isFinite(seconds)) return "0:00"
  const mins = Math.floor(seconds / 60)
  const secs = Math.floor(seconds % 60)
  return `${mins}:${secs.toString().padStart(2, "0")}`
}

function VideoPlayer({ src, poster, className }: VideoPlayerProps) {
  const videoRef = React.useRef<HTMLVideoElement>(null)
  const [playing, setPlaying] = React.useState(false)
  const [muted, setMuted] = React.useState(false)
  const [current, setCurrent] = React.useState(0)
  const [duration, setDuration] = React.useState(0)
  const [volume, setVolume] = React.useState(1)
  const [fullscreen, setFullscreen] = React.useState(false)

  const togglePlay = React.useCallback(() => {
    const video = videoRef.current
    if (!video) return
    if (video.paused) {
      void video.play()
    } else {
      video.pause()
    }
  }, [])

  React.useEffect(() => {
    const video = videoRef.current
    if (!video) return
    const onPlay = () => setPlaying(true)
    const onPause = () => setPlaying(false)
    const onTime = () => setCurrent(video.currentTime)
    const onMeta = () => setDuration(video.duration)
    video.addEventListener("play", onPlay)
    video.addEventListener("pause", onPause)
    video.addEventListener("timeupdate", onTime)
    video.addEventListener("loadedmetadata", onMeta)
    return () => {
      video.removeEventListener("play", onPlay)
      video.removeEventListener("pause", onPause)
      video.removeEventListener("timeupdate", onTime)
      video.removeEventListener("loadedmetadata", onMeta)
    }
  }, [])

  const onKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
    const video = videoRef.current
    if (!video) return
    if (event.key === " " || event.key === "k") {
      event.preventDefault()
      togglePlay()
    }
    if (event.key === "ArrowRight") video.currentTime = Math.min(video.duration, video.currentTime + 5)
    if (event.key === "ArrowLeft") video.currentTime = Math.max(0, video.currentTime - 5)
    if (event.key === "m") {
      video.muted = !video.muted
      setMuted(video.muted)
    }
    if (event.key === "f") void toggleFullscreen()
  }

  const toggleFullscreen = async () => {
    const root = videoRef.current?.parentElement
    if (!root) return
    if (document.fullscreenElement) {
      await document.exitFullscreen()
      setFullscreen(false)
    } else {
      await root.requestFullscreen()
      setFullscreen(true)
    }
  }

  const togglePip = async () => {
    const video = videoRef.current
    if (!video) return
    if (document.pictureInPictureElement) {
      await document.exitPictureInPicture()
    } else {
      await video.requestPictureInPicture()
    }
  }

  return (
    <div
      tabIndex={0}
      onKeyDown={onKeyDown}
      className={cn("group relative overflow-hidden rounded-xl border bg-black outline-none", className)}
    >
      <video
        ref={videoRef}
        src={src}
        poster={poster}
        className="aspect-video w-full"
        onClick={togglePlay}
        playsInline
      />
      <div className="absolute inset-x-0 bottom-0 flex flex-col gap-2 bg-linear-to-t from-black/70 to-transparent p-3 text-white opacity-0 transition-opacity motion-reduce:transition-none group-hover:opacity-100 group-focus-within:opacity-100">
        <input
          type="range"
          min={0}
          max={duration || 0}
          step={0.1}
          value={current}
          aria-label="进度"
          className="w-full accent-white"
          onChange={(event) => {
            const next = Number(event.target.value)
            if (videoRef.current) videoRef.current.currentTime = next
            setCurrent(next)
          }}
        />
        <div className="flex items-center gap-2 text-xs">
          <button type="button" onClick={togglePlay} aria-label={playing ? "暂停" : "播放"}>
            {playing ? <Pause className="size-4" /> : <Play className="size-4" />}
          </button>
          <span className="tabular-nums">
            {formatTime(current)} / {formatTime(duration)}
          </span>
          <button
            type="button"
            className="ml-1"
            aria-label={muted ? "取消静音" : "静音"}
            onClick={() => {
              const video = videoRef.current
              if (!video) return
              video.muted = !video.muted
              setMuted(video.muted)
            }}
          >
            {muted || volume === 0 ? <VolumeX className="size-4" /> : <Volume2 className="size-4" />}
          </button>
          <input
            type="range"
            min={0}
            max={1}
            step={0.05}
            value={muted ? 0 : volume}
            aria-label="音量"
            className="w-16 accent-white"
            onChange={(event) => {
              const next = Number(event.target.value)
              setVolume(next)
              if (videoRef.current) {
                videoRef.current.volume = next
                videoRef.current.muted = next === 0
                setMuted(next === 0)
              }
            }}
          />
          <span className="ml-auto flex items-center gap-2">
            <button type="button" aria-label="画中画" onClick={() => void togglePip()}>
              <PictureInPicture2 className="size-4" />
            </button>
            <button type="button" aria-label={fullscreen ? "退出全屏" : "全屏"} onClick={() => void toggleFullscreen()}>
              {fullscreen ? <Minimize2 className="size-4" /> : <Maximize2 className="size-4" />}
            </button>
          </span>
        </div>
      </div>
    </div>
  )
}

export { VideoPlayer }

"use client"

import * as React from "react"
import { flushSync } from "react-dom"
import { LayoutGroup, motion } from "motion/react"

import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { cn } from "@/lib/utils"

export interface GalleryShot {
  id: string
  title: string
  tint: string
}

export interface ViewTransitionGalleryProps {
  shots?: GalleryShot[]
  className?: string
  gap?: number
  size?: number
}

const defaultShots: GalleryShot[] = [
  { id: "north", title: "北岸", tint: "#312e81" },
  { id: "violet", title: "暮紫", tint: "#7c3aed" },
  { id: "tide", title: "潮色", tint: "#22d3ee" },
  { id: "bloom", title: "花影", tint: "#f472b6" },
  { id: "ember", title: "余烬", tint: "#f59e0b" },
  { id: "ink", title: "墨色", tint: "#18181b" },
]

function canUseViewTransition() {
  return typeof document.startViewTransition === "function"
}

function ViewTransitionGallery({ shots = defaultShots, className, gap, size }: ViewTransitionGalleryProps) {
  const gapPx = gap === undefined || gap === 12 ? undefined : gap
  const thumbPx = size === undefined || size === 112 ? undefined : size
  const reduced = usePrefersReducedMotion()
  const native = React.useSyncExternalStore(
    () => () => {},
    canUseViewTransition,
    () => false,
  )
  const [selected, setSelected] = React.useState<string | null>(null)
  const shot = shots.find((item) => item.id === selected) ?? null
  const useNative = native && !reduced

  const change = (next: string | null) => {
    if (!useNative) {
      setSelected(next)
      return
    }
    const name = `shot-${next ?? selected}`
    const outgoing = document.getElementById(next ? `thumb-${next}` : `detail-${selected}`)
    if (outgoing) outgoing.style.viewTransitionName = name
    document.startViewTransition(() => {
      flushSync(() => setSelected(next))
      if (outgoing) outgoing.style.viewTransitionName = ""
      const incoming = document.getElementById(next ? `detail-${next}` : `thumb-${selected}`)
      if (incoming) incoming.style.viewTransitionName = name
    })
  }

  return (
    <LayoutGroup>
      <div className={cn("relative rounded-2xl border bg-background p-4", className)}>
        <p className="mb-3 text-xs tracking-[0.22em] text-muted-foreground uppercase">Shared element</p>
        <div className={gapPx === undefined ? "grid grid-cols-3 gap-3" : "grid grid-cols-3"} style={gapPx === undefined ? undefined : { gap: gapPx }}>
          {shots.map((item) => (
            <button
              key={item.id}
              type="button"
              id={`thumb-${item.id}`}
              onClick={() => change(item.id)}
              className="text-left"
            >
              <motion.span
                layoutId={useNative ? undefined : `shot-${item.id}`}
                className={
                  thumbPx === undefined
                    ? "grid h-28 w-full place-items-end rounded-xl p-3 text-sm text-white"
                    : "grid w-full place-items-end rounded-xl p-3 text-sm text-white"
                }
                style={
                  thumbPx === undefined
                    ? { background: `linear-gradient(160deg, ${item.tint}, #09090b)` }
                    : { background: `linear-gradient(160deg, ${item.tint}, #09090b)`, height: thumbPx }
                }
              >
                {item.title}
              </motion.span>
            </button>
          ))}
        </div>
        {shot ? (
          <div className="absolute inset-0 z-10 grid place-items-center bg-black/45 p-6" onClick={() => change(null)}>
            <motion.div
              id={`detail-${shot.id}`}
              layoutId={useNative ? undefined : `shot-${shot.id}`}
              className="grid h-64 w-full max-w-md place-items-end rounded-3xl p-5 text-white shadow-2xl"
              style={{
                background: `linear-gradient(160deg, ${shot.tint}, #09090b)`,
                viewTransitionName: useNative ? `shot-${shot.id}` : undefined,
              }}
              onClick={(event) => event.stopPropagation()}
            >
              <span className="text-2xl">{shot.title}</span>
              <button type="button" className="mt-3 rounded-full bg-white/15 px-3 py-1 text-xs" onClick={() => change(null)}>
                返回
              </button>
            </motion.div>
          </div>
        ) : null}
      </div>
    </LayoutGroup>
  )
}

export { ViewTransitionGallery }

"use client"

import * as React from "react"
import { useVirtualizer } from "@tanstack/react-virtual"

import { cn } from "@/lib/utils"

export interface VirtualListProps<T> {
  items: T[]
  height?: number
  estimateSize?: number
  renderItem: (item: T, index: number) => React.ReactNode
  className?: string
}

function VirtualList<T>({
  items,
  height = 320,
  estimateSize = 40,
  renderItem,
  className,
}: VirtualListProps<T>) {
  const parentRef = React.useRef<HTMLDivElement>(null)
  const virtualizer = useVirtualizer({
    count: items.length,
    getScrollElement: () => parentRef.current,
    estimateSize: () => estimateSize,
    overscan: 8,
  })

  return (
    <div ref={parentRef} className={cn("overflow-auto rounded-xl border", className)} style={{ height }}>
      <div className="relative w-full" style={{ height: virtualizer.getTotalSize() }}>
        {virtualizer.getVirtualItems().map((row) => (
          <div
            key={row.key}
            className="absolute top-0 left-0 w-full"
            style={{ height: row.size, transform: `translateY(${row.start}px)` }}
          >
            {items[row.index] !== undefined ? renderItem(items[row.index] as T, row.index) : null}
          </div>
        ))}
      </div>
    </div>
  )
}

export { VirtualList }

